/* Generated by build_narr.py: AOI_NARR[hash of English caption] = [clip in audio/narr/, what Aoi says];
   AOI_WORDS[Japanese word on a card] = clip in audio/narr/ (tap to hear). */
var AOI_NARR = {"c59f5d39":["fa3b68dd77f1.mp3","標準語、大阪弁、京都弁。それから、日本のいろんな地方の言葉をめぐる旅だよ！"],"e5344932":["d64a291a6a71.mp3","日本にはたくさんの方言があるの。標準語は東京の言葉がもとになっていて、テレビや学校、このアプリでも使ってる。誰にでも通じるよ。"],"28c8ec88":["a6ba30b1b418.mp3","一番有名なのは関西弁。大阪、京都、神戸の言葉だね。メロディーが違って、アクセントが逆になる言葉もあるんだ。ありがとうは「おおきに」！"],"d9f98784":["46579df3fdd4.mp3","大阪弁は元気いっぱいで、お笑いで有名！「ほんま」は本当、「あかん」はダメ。そして、ツッコミといえば「なんでやねん！」"],"58e2a5bc":["2a2176aced11.mp3","大阪の「なんでやねん」。英語だと、why on earth、みたいな感じ。漫才の定番のツッコミだよ。"],"824c8aa8":["1d25ee38162b.mp3","関西では、「ない」の代わりに「へん」を使うの。「行かない」は「行かへん」になるよ。"],"70cf5cf4":["86e743be5a94.mp3","京都弁はやわらかくて丁寧。有名なのが「はる」。やさしく敬意を表す言い方で、「来はる」は「来る」の丁寧な形だよ。"],"f8a757fb":["ab7410cc8da7.mp3","京都の昔ながらのお迎えの言葉。老舗のお店やお茶屋さんで聞けるよ。「おいでやす」。"],"8260214d":["bf6946bc9da1.mp3","福岡には博多弁があるの。この甘いセリフが有名だよ。「好いとーよ」。好きだよ、っていう意味！"],"0e969a71":["0869df436dcc.mp3","広島では、「だから」の意味で「じゃけえ」って言うよ。"],"1ff33d2d":["16c2cf671586.mp3","名古屋では、「とても」のことを「でら」って言うの。「でらうまい」は、すごくおいしい！"],"aeb4ec0f":["34e231a6689c.mp3","北の東北地方では、「べ」をよく使うよ。「行くべ」は、行こう、っていう意味。"],"73e377e5":["6d1397ab1400.mp3","沖縄には、琉球の言葉があるの。有名な歓迎の言葉は「めんそーれ」！"],"68c87e11":["65f77efb8cac.mp3","私はぜんぶ標準のメロディーで読んでいるから、本当のアクセントは地元の人に聞いてみてね。それに、標準語ならどこでも通じるから安心して！"],"ac122ede":["01ff7fcb8540.mp3","語順、文の最後に来る動詞、それから言葉を省略すること。"],"6d2db954":["2bcca4ffd7af.mp3","日本語では、動詞が最後に来るの。基本の順番は、話題、それから詳しいこと、最後に動詞だよ。"],"a1ec5788":["b3ce6d455a2a.mp3","助詞っていう小さな言葉が、単語のあとについて、その役割を決めるの。ここでは「に」が、行き先を表しているよ。"],"8ea50358":["0106e87fbbf8.mp3","誰のことか分かっているときは、省略していいの。日本語では「私」や「あなた」をしょっちゅう省くんだ。"],"6531ee30":["db26c9c4629f.mp3","時間や場所も、動詞の前に来るよ。よくある順番は、話題、時間、場所、目的語、そして動詞。"],"00ca54e0":["0f06ccccbabe.mp3","動詞の終わりで時制が分かるの。「食べます」は今かこれから、「食べました」は過去。くわしくは「動詞と時制」でね。"],"d16d5565":["3397b5623802.mp3","「XはYです」で、XはYだ、と言えるよ。最後の「です」は丁寧な言い方なんだ。"],"daa083ea":["a3ae9f09e024.mp3","単語のあとについて、その単語の役割を表す小さな言葉、助詞だよ。"],"642507be":["a604155ea7e8.mp3","「は」は話題を表すの。文が何についての話かを示すんだ。書くときは「は」だけど、発音は「わ」だよ。"],"86eec30e":["13f1de0114e4.mp3","「を」は目的語、つまり動作を受けるものを表すよ。発音は「お」。"],"b9158ec1":["dce21fe121e2.mp3","「に」は一つの点を表すの。何かが起きる時間や、行き先だよ。"],"3cd910b2":["06b8e8cb586d.mp3","「で」は、何かをする場所や、電車で、みたいに手段を表すよ。"],"c63b4695":["bb823f8a9c7f.mp3","「へ」は方向、「〜のほうへ」っていう意味。書くときは「へ」だけど、発音は「え」。行き先を言うときは「に」とほとんど同じだよ。"],"f210104c":["4ab5946fab93.mp3","「と」は「一緒に」、それから名詞と名詞をつなぐ「and」の意味だよ。"],"72838af9":["8ec340043f65.mp3","「も」は「〜も」、tooやalsoの意味。「は」「が」「を」の代わりに使うよ。"],"ae8b1252":["decd9aaabca0.mp3","「の」は名詞と名詞をつなぐの。英語のofや、アポストロフィーsみたいにね。「私の名前」は、my name。"],"383c8071":["f455a5094ff8.mp3","「が」は主語を指して、好きなものやほしいものにも使うよ。「猫が好き」は、I like cats。"],"2c72bdcf":["0e47afab5dce.mp3","丁寧な文の最後に「か」をつけると、質問になるよ。"],"d4433582":["081b5452b541.mp3","二つの時制、丁寧な形とカジュアルな形、そして三種類の動詞。"],"a2dcbdda":["34d9ed35974b.mp3","日本語の時制は二つだけ。過去と、過去じゃないもの。同じ形で、今のこともこれからのことも言えるの。"],"6b9e065d":["2de18862d860.mp3","ここでは同じ「行きます」が、明日行く、っていう意味になるよ。「明日」があるからね。"],"4131a628":["0c39703256b2.mp3","過去にするときは、「ます」を「ました」に変えるよ。"],"37dd84c8":["fe6e801e0a84.mp3","否定にするときは、「ます」を「ません」に。過去の否定は「ませんでした」だよ。"],"2a4af7f5":["5e29cbd88d4e.mp3","カジュアルな話し方では、普通形を使うの。意味は同じで、友だちや家族と話すときに使うよ。"],"c60decc0":["d19fea70ebc7.mp3","動詞は三種類。る動詞は「る」を取って、う動詞は最後の音が変わる。そして、不規則動詞が二つあるよ。"],"c636c266":["0d42a1170b09.mp3","「ています」は、今まさにしていること、または続いている状態を表すよ。"],"fec4b0b0":["eddc1ffbedcf.mp3","何かをしたいときは、動詞の語幹に「たいです」をつけるの。"],"1095873b":["0f557e8cb163.mp3","「です」、二種類の形容詞、そしてその過去形と否定形。"],"bdadb14c":["e92a282c5170.mp3","名詞には「です」を使うよ。カジュアルだと「だ」になって、よく省略されるの。"],"2fafc479":["5c5e070a5cb4.mp3","い形容詞は「い」で終わるよ。丁寧に言うときは「です」をつけてね。"],"ccc81551":["4518fb895eda.mp3","い形容詞は、自分の語尾が変わるの。「高い」「高くない」「高かった」。「高いでした」とは言わないよ。"],"4b69f4a4":["d6b62ecea976.mp3","な形容詞は名詞と同じように、「です」や「だ」と一緒に使うよ。"],"bcda1c56":["0051a6c762ca.mp3","名詞の前では、な形容詞に「な」がつくの。「静かな町」。い形容詞はそのまま、「高い山」だよ。"],"6786555d":["240612f05c0a.mp3","例外が一つ。「いい」は、ほかの形では「よ」に変わるの。「よくない」「よかった」。"],"ec026f69":["7e84a79f64d0.mp3","「か」、何、どこ、いつ、誰。それから、答え方。"],"27a1bc4f":["6fd6d1fad136.mp3","丁寧な質問は、文の最後に「か」をつけるだけ。語順は変わらないよ。"],"e594eda4":["cb5f031bc727.mp3","「何」は what。「です」の前では「なん」って読むよ。"],"208b716f":["6d390ddce515.mp3","「どこ」は where。これはたくさん使うよ！"],"ede69551":["3ef534ddc840.mp3","「いつ」は when だよ。"],"825b5fe1":["0dbd8d5ac0bd.mp3","「誰」は who だよ。"],"c73cd2a7":["a4ad9377023f.mp3","カジュアルなときは、「か」を取って語尾を上げるか、「の」で終わるよ。"],"f8fbc7fd":["d5a3c2bc96e2.mp3","答えるときは、動詞をくり返すのが普通。「行きます」とか「行きません」。「はい」は yes だよ。"],"b1294587":["1a801d125841.mp3","してください、しませんか、しましょう。て形と、その仲間たち。"],"9eb85900":["517a8784a14a.mp3","誰かに何かをお願いするときは、て形に「ください」をつけるよ。"],"cd92032f":["d63d153bd490.mp3","る動詞のて形は、「る」を「て」に変えるだけ。"],"22d9094f":["cb481fc7f7d5.mp3","う動詞は、最後の音によって変わり方が違うの。「行く」だけは例外で、「行って」になるよ。"],"da36c8a7":["35a4bdfc6ce4.mp3","誘うときは、「ませんか」と否定の形で聞くの。英語の won't you? だね。"],"4ee09f16":["64591dba612a.mp3","「ましょう」は、let's の意味だよ。"],"f625a7a5":["e9e5b6befa37.mp3","友だち同士なら、カジュアルな「〜しよう」は「おう」か「よう」で終わるよ。"],"9180002c":["d076a3cea8a9.mp3","動詞のグループ。辞書形から、ます形へ。どの形もタップすると聞けるよ。"],"440223f4":["38863d42450f.mp3","「食べる」、to eat。る動詞だから、「る」を取って語尾をつけるよ。"],"54b63a1a":["f4504f9cf34f.mp3","「行く」、to go。う動詞だから、最後の音が変わるの。く、き、か、こ、みたいにね。"],"7b222c17":["d76bd015560f.mp3","「する」、to do。不規則動詞だから、そのまま覚えてね。「勉強する」みたいに、たくさんの動詞を作るよ。"],"0f2c9483":["eb2afc134b7c.mp3","「来る」、to come。不規則動詞で、「来」の読み方が、く、こ、き、と変わるの。"],"684154ec":["c507c840d727.mp3","て形。辞書形から、て形へ。どの形もタップすると聞けるよ。"],"b16e13e0":["bd887bd3d638.mp3","「高い」、expensive や tall の意味。い形容詞だから、自分の語尾が変わるよ。"],"ab7687ab":["7639a6b46923.mp3","「静か」、quiet。な形容詞だから、名詞みたいに「だ」や「です」を使うよ。名詞の前では「な」をつけて、「静かな町」。"],"20894bee":["e18d4edd1eeb.mp3","「学生」、student。名詞だね。名詞は「だ」や「です」を使うよ。かたい書き言葉では、否定は「ではありません」。"],"eb3de42d":["bf7e4a6a188f.mp3","左、右、まっすぐ。それから、どこにあるか聞く方法。"],"6bed9f3f":["79e3787be14a.mp3","店員さんの呼び方、注文の仕方、そしてお会計。"],"0a64e039":["7779b63ff8e5.mp3","動物たち、何をするか、そして日本語での鳴き声！"],"1d64c62f":["7d83a1f5a72f.mp3","日本で見かけたり、聞いたりする鳥たちと、その鳴き声。"],"ddb5c646":["35c091915691.mp3","虫たち、何をするか、そして夏の一番うるさい音！"],"18ead113":["37f222eecf19.mp3","種から花まで。そして、日本で愛されている植物たち。"],"916e0afd":["c9c02514c1fd.mp3","魔女、ほうき、呪文。それから、日本のお父さんお母さんが本当に使うおまじない！"],"74ce425c":["49bbc8c80320.mp3","ドレス、着物。それから、「着る」を表す三つの違う動詞。"],"a650668d":["b5e65d2e3a43.mp3","目、耳、鼻、口、歯。それぞれ何をするのかな。"],"0879591b":["8e33afc30cf7.mp3","頭からつま先まで。そして、体の中で毎日がんばっている臓器たち。"],"2813c9cc":["a67fc7546bc1.mp3","どこが痛いかを伝える言葉。薬局でも、病院でも使えるよ。"],"7d2bd9c6":["fe5787983df8.mp3","日本語での八つの惑星。それから、曜日の名前がどこから来たのか。"],"d1b3a969":["edcf7a1b1076.mp3","星の言葉、天の川、そして七夕の恋の物語。"],"9e740cc1":["4a871d41f96a.mp3","心臓の四つの部屋、動脈と静脈を、日本語で。"],"95e73679":["5bcc631a93e4.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日は月から来たお姫さま、日本で一番古いお話の一つ、かぐや姫。読んだ行は下に積み重なっていくから、いつでも上にスクロールして見返してね。"],"ffce48eb":["d892257a9b94.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日はヨーロッパの昔話を、やさしい日本語で。顔の言葉がたくさん出てくるよ。読んだ行は積み重なっていくから、いつでも上にスクロールして見返してね。"],"6bb20658":["5b130426cdcd.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日は桃から生まれた男の子と、三匹の動物の仲間たちのお話。読んだ行は積み重なっていくから、いつでも上にスクロールして見返してね。"],"6a21120e":["884b78a0f98f.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。これは日本の子どもたちが学校で習う歌。どの番も同じ形のくり返しだから、「が」と「に」の練習にぴったり！読んだ行は積み重なっていくから、いつでも見返してね。"],"7d93d2ea":["412bb7b3895e.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。子どもがハトに豆をまいてあげる歌。カジュアルな毎日の文法がいっぱいだよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"3aee7213":["fd083ae4709c.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。お母さんカラスが鳴いているのは、山のおうちで子どもたちが待っているから。読んだ行は積み重なっていくから、いつでも見返してね。"],"f6b25e8a":["9a9259428d17.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。ウサギが、のろまだねってカメをからかうの。競走の結末は、知ってるよね！読んだ行は積み重なっていくから、いつでも見返してね。"],"8529f102":["d104d03147f0.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。大人になった人が、小さいころ誰かに背負われて、夕焼けの中で見た赤とんぼを思い出す歌。読んだ行は積み重なっていくから、いつでも見返してね。"],"d34a420d":["e8d5f6146561.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。昔の日本語で書かれているから、言葉が昔どうだったかを、ちょっとのぞけるよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"e8cf5132":["33eee7e1647d.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。これは昔の言葉で書かれた、もとの歌詞だよ。「弥生」は三月の昔の呼び名で、桜が咲くころなんだ。読んだ行は積み重なっていくから、いつでも見返してね。"],"1f45dcea":["4ab2ef9c074f.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。一人が真ん中で目をかくしてしゃがんで、ほかの子たちが歌いながらまわりを歩くの。歌が終わったら、真後ろにいるのは誰か当てるんだよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"62f443a2":["10313d5c514c.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。動きもやってみてね。手をにぎって「結んで」、手を開いて「開いて」、手をたたいて「手を打って」、最後に手を「上に」！読んだ行は積み重なっていくから、いつでも見返してね。"],"7311336f":["96ead436a24f.mp3","俳句の時間だよ！一句ずつ読んで、そのあと今の言葉でも言うね。好きな言い方を選んでね。俳句は五、七、五の音でできていて、季節を表す「季語」が一つ入るの。この六つは、日本でとても有名な句だよ。読んだ句は積み重なっていくから、いつでも見返してね。"],"03ac3e97":["703872764959.mp3","五本の線、四つの間、そしてそこに住んでいる音符たち。五線の上の音符をタップすると、音が聞けるよ。"],"8f093959":["86aff2fc21b4.mp3","楽譜は五線に書くの。五本の線と、四つの間。音符が高いところにあるほど、高い音になるよ。"],"21553fb7":["429b24dd0db5.mp3","このくるっとした記号が、ト音記号。下から二本目の線に巻きついていて、その線が G、つまりソの音なんだ。"],"25220b8e":["cb85f2b0091a.mp3","線の音は、下から E、G、B、D、F。英語では、Every Good Boy Does Fine、って覚えるんだよ。"],"e2a8dd71":["dd694b3f18f9.mp3","間の音は、言葉になるの。F、A、C、E。FACE、顔だね！"],"bd089aa0":["3b2cfd48e087.mp3","真ん中のドは、五線の下にある短い線、加線の上にあるよ。ピアノの真ん中あたりの音なんだ。"],"65e3b710":["9e2e086967b0.mp3","ドからドまで、日本のドレミ、それからシャープとフラット。五線の上の音符をタップすると聞けるよ。"],"ddab32c1":["f572ae75b95e.mp3","音の名前は、七つのアルファベット。C、D、E、F、G、A、B。そしてまた、一オクターブ上の C から始まるよ。"],"14c932d0":["e30ba7eaefdd.mp3","日本の学校の音楽では、ドレミを使うよね。ド、レ、ミ、ファ、ソ、ラ、シ、ド。一緒に歌おう！"],"b133101b":["dd55e87b5a34.mp3","日本の調の名前は、昔のかなを使うの。C、D、E、F、G、A、B は、ハ、ニ、ホ、ヘ、ト、イ、ロ。だから C major は、ハ長調だよ。"],"f503b66e":["9bb29bd272bb.mp3","シャープは、音を半音上げる記号。聞いてみて。ファ、そしてファのシャープ。"],"70094c8e":["4aa91b29457d.mp3","フラットは、音を半音下げる記号。ピアノでは、シャープやフラットはだいたい黒い鍵盤だよ。"],"ab7bd71b":["b9a199429c02.mp3","全音符、二分音符、四分音符、八分音符、付点、そして休符。五線の上の音符をタップすると聞けるよ。"],"54f0d105":["f1496889cd51.mp3","全音符は、棒のない白い丸。長さは四拍だよ。"],"44f3f165":["650b415f4c13.mp3","二分音符は、棒のついた白い丸。一つで二拍。"],"6f12f7cc":["c3262a19246d.mp3","四分音符は、黒くぬった丸に棒。一つで一拍だよ。"],"46ca7a28":["877026a17481.mp3","八分音符には、小さな旗がついてるの。半拍だから、一拍に二つ入るよ。"],"efc16489":["67ad1604c1eb.mp3","付点は、その音符の半分の長さを足すの。付点二分音符は三拍だよ。"],"b2119fe4":["71f37a77db82.mp3","休符は、同じ長さのお休み。ここでは、音、休み、音、休み。"],"93f849a2":["49ef21734eb2.mp3","小節線、拍子記号、そしてはじめてのメロディー。五線の上の音符をタップすると聞けるよ。"],"9b04073a":["c1984f27d40f.mp3","小節線は、音楽を小節に区切る線。最初の数字が拍子記号で、四分の四は、一小節に四分音符が四つ、っていう意味だよ。"],"1e7b00b2":["7ed2a4deaa33.mp3","四分の三は、一小節に三拍。ワルツみたいに、イチ、ニ、サン、イチ、ニ、サン。"],"7e1edfd0":["211b2a081c4d.mp3","本物の曲を読んでみよう。日本のきらきら星の始まりだよ。私がハミングするから、音符を一つずつ追ってね。"],"c15b4063":["9a153041a149.mp3","次の行だよ。だんだん下がっていくのに気づいたかな。ファ、ミ、レ、ド。"],"51eaa97b":["4c54ffce6894.mp3","これで楽譜が読めたね！次は日本の歌もやってみて。さくらさくら、ちょうちょう、ほかにもあるよ。音符をタップすると聞けるよ。"],"3321c01a":["ffe97e162605.mp3","やさしいコードが八つあれば、何百曲も弾けちゃうよ。図は弦を表していて、左が一番低いEの弦。どこを押さえるかも書いてあるよ。図をタップすると、ジャランと鳴るよ。"],"d7835187":["8120ad8fc6f8.mp3","C メジャー。明るくて、楽しいコード。一番低いEの弦は弾かないでね。形は、バツ、3、2、0、1、0。"],"7ff4a23c":["e3777ffc5a3d.mp3","G メジャー。大きくて、広がる響き。六本ぜんぶ鳴らすよ。形は、3、2、0、0、0、3。"],"df380a7e":["6bfb171edd06.mp3","D メジャー。上の四本だけで、小さな三角の形。形は、バツ、バツ、0、2、3、2。"],"e84ec781":["99bfd5ac34af.mp3","E マイナー。指はたった二本！マイナーコードは、やわらかくて少しさみしい響きだよ。形は、0、2、2、0、0、0。"],"33befa33":["4476ae75d9f3.mp3","A マイナー。E メジャーと同じ形を、弦一本ぶんずらしたものだよ。形は、バツ、0、2、2、1、0。"],"5339b50b":["3720b39d7f26.mp3","E メジャー。Em に、G の弦の指を一本足した形。形は、0、2、2、1、0、0。"],"c0f0daf4":["41ce4d1e25be.mp3","D マイナー。上の四本で、やさしくて切ない響き。さくらさくらでも使うよ。形は、バツ、バツ、0、2、3、1。"],"c44c9b51":["1f01f2c4b4ee.mp3","F メジャーセブン。むずかしいセーハがいる F の、かんたんな代わりだよ。夢みたいな響き。形は、バツ、バツ、3、2、1、0。"],"7e010c70":["666368ac5b1e.mp3","C、G、Am、Em を切り替えてみて。数えきれないほどのポップスで使われているコードだよ。タップすると聞けるよ。"],"1889632f":["a63b30fb2faa.mp3","コードの図鑑だよ。どの図もタップすると聞けるよ。まずはオープンコード、それからセブンス、セーハコード、そして J-rock のパワーコード。"],"34c37925":["ecea93b99c83.mp3","オープンコード。一つずつタップして鳴らしてみてね。"],"4a67ea4d":["c9d5ad03dad5.mp3","セブンス。J-pop らしい色だよ。一つずつタップして鳴らしてみてね。"],"87ddedbb":["0f7deb1cc38d.mp3","セーハコード。一つずつタップして鳴らしてみてね。"],"dfa3e7bc":["e5bcfc3fe95b.mp3","パワーコード、J-rock の音！一つずつタップして鳴らしてみてね。"],"9801db47":["dc76197426a7.mp3","指一本で六本の弦をぜんぶ押さえる。これが、ネックのどこでもコードを弾くカギだよ。図をタップすると聞けるよ。"],"c4812810":["3e89f05f8570.mp3","セーハコードは、人差し指をカポみたいに使って、一つのフレットの弦をぜんぶ押さえるの。図の中の棒がそれを表しているよ。"],"f7dacb87":["d0939cebd39b.mp3","F は、最初に出会う有名なセーハコード。人差し指を少しだけ骨のある側に転がして、親指はネックの裏に。フレットのすぐ近くを押さえるのがコツだよ。"],"9219501b":["cd752771c199.mp3","Bm は、Aの弦の2フレットからのセーハ。一番低いEの弦は弾かないでね。"],"aac9faff":["838d88a7d37f.mp3","ここが魔法のところ。同じセーハの形をネックの上にずらすと、別のコードになるの。F の形を3フレットに持っていくと G、5フレットなら A だよ。"],"82803ad7":["1f2e444f1208.mp3","最初はセーハがビビっても大丈夫、普通のことだよ。毎日数分練習すれば、力がついてくるからね。それまでは、Fmaj7 が F のやさしい代わりになってくれるよ。"],"d3ab6018":["035f7b08e0f9.mp3","音は二つか三つ、大きくてパンチがある。これが J-rock の音！図をタップすると聞けるよ。"],"9525346e":["2b51ed9d7bbb.mp3","パワーコードは、ルート音とその五度の音だけ。上にオクターブの音を足すことも多いよ。E5 みたいに、5 をつけて書くの。"],"5396c37b":["c382272d4821.mp3","三度の音がないから、メジャーでもマイナーでもない。だから、ひずみを強くかけても音がにごらないの。ロックバンドが大好きな理由だよ。"],"9b4405ba":["1ca95164623c.mp3","この形は、どこへでも動かせるよ。ルートは低いEの弦かAの弦、五度はその隣の弦の、二フレット上。"],"c6ced5b9":["a502d2d0f973.mp3","E5、G5、A5 と弾いてみて。この形をずらす動きは、数えきれないロックのリフに出てくるよ。"],"cd2d1cdf":["71998e719e5f.mp3","J-rock らしい疾走感を出すなら、速いダウンストロークで弾いてみて。手のひらをブリッジの近くの弦に軽くのせるの。これがパームミュートだよ。"],"1f86ee76":["570c0df8c97a.mp3","キック、スネア、ハイハット。それから、ビートの数え方。"],"e0974c4a":["8d3f067de01d.mp3","キックドラムは、足で踏む大きくて低いドンという音。曲の心臓の音みたいなものだよ。"],"0e4c6606":["27b218bd6db6.mp3","スネアは、真ん中で鳴るパシッという鋭い音。たいてい二拍目と四拍目に入るよ。これがバックビート。"],"1d43858b":["06cd66cab9a9.mp3","ハイハットは、チッチッとリズムを刻むシンバル。たいてい八分音符ごとに鳴らすよ。"],"18ccc7a4":["0d9c0afc7482.mp3","ドラマーは十六分音符を、ワン・エ・アン・ダ、ツー・エ・アン・ダ、って数えるの。グリッドの四角一つが、その一つ分だよ。"],"05d354f8":["a375d5c5ef31.mp3","ぜんぶ合わせると、8ビート！ロックや J-pop の基本のリズムだよ。次は自分で叩いてみよう！"],"ae08cbb8":["bd0e789b0258.mp3","四本の弦、ルート音、そしてキックと息を合わせること。"],"eaa5dda5":["bc79c85e5597.mp3","ベースの弦は四本。E、A、D、G で、ギターの低い四本より、一オクターブ低い音だよ。"],"b032b2d7":["845fd29da55c.mp3","ベースの一番の仕事はルート。コードの名前になっている音のことだよ。C のコードなら、C を弾くの。"],"a0f538ff":["b2a3b2f2a23c.mp3","キックドラムと息を合わせよう。キックが鳴るとき、ベースもたいてい一緒に弾くの。この二つで、リズムセクションだよ。"],"457a6bc7":["f519858b2f3c.mp3","それから、動きをつけてみよう。ルートの一オクターブ上や、五度の音。同じコードでも、ぐっと弾むよ。"],"eacd028c":["ac4c8fadd311.mp3","セッションの時間だよ！私がギターとドラムを弾くから、あなたはフレットボードでベースラインを弾いてね。"],"ec0dad99":["57a8df998fab.mp3","私たちの八つの惑星を、本当の大きさの比率で。それぞれの豆知識もあるよ。"],"78f90e92":["0166c19da0c9.mp3","3Dの太陽系だよ！ドラッグで回して、ピンチでズーム。惑星をタップすると名前が聞けるよ。ぜんぶ画面に入るように、大きさと距離はぎゅっと縮めてあるの。"],"360b6aee":["63c7e84317e2.mp3","太陽のまわりを、八つの惑星が回っているの。ここでは、それぞれ本当の大きさの比率で並べているよ。"],"de7ea411":["6ca6f52959f5.mp3","水星。一番小さくて、一番太陽に近い惑星。日の出から次の日の出までの一日が、一年より長いんだよ！"],"362893e6":["827ac3543d95.mp3","金星。一番熱い惑星で、およそ465度。厚い二酸化炭素の空気が熱を閉じこめているからなの。ほかのほとんどの惑星とは逆向きに回っているよ。"],"d6bf8d96":["184c999af21a.mp3","地球。表面に液体の水があって、生命がいると分かっている、ただ一つの惑星だよ。"],"1dc571ed":["f6033b97b24e.mp3","火星。赤く見えるのは、砂ぼこりにふくまれる酸化鉄、つまりサビのせい。太陽系で知られている一番高い火山、オリンポス山があるよ。"],"fdaebf7e":["489a2d094d5f.mp3","木星。一番大きな惑星で、横に地球がおよそ十一個並ぶくらい。大赤斑は、地球より大きな嵐なんだよ。"],"5ac20b9a":["c7d700ac44a3.mp3","土星。氷と岩でできた輪で有名だよ。大きさのわりにとても軽くて、平均すると水より密度が小さいの。"],"d6d0484c":["a7501658262a.mp3","天王星。およそ98度もかたむいているから、横に寝転がったまま太陽のまわりを回っているの。"],"1bdd2f50":["a796580dc498.mp3","海王星。一番遠い惑星で、太陽系で観測された中で一番速い風が吹いているよ。およそ時速2000キロ！"],"32162ed5":["a3ff059b71ba.mp3","日本語では、五つの惑星が昔の五つの元素から名前をもらっているの。水、金、火、木、土。曜日の名前にもなっているよ！"],"1d952f30":["160399d79af6.mp3","オリオン座、北極星、そして七夕の星を、本当の位置から探してみよう。"],"e6444f54":["da5494b4ff9f.mp3","冬の夜空の主役は、狩人のオリオン。三つ並んだ星がベルトで、日本語では「三つ星」。赤いベテルギウスは昔「平家星」、白いリゲルは「源氏星」と呼ばれていたの。ライバルの二つの一族の名前だよ。"],"d0639f54":["d170435d268f.mp3","ベテルギウス、シリウス、プロキオンで、冬の大三角。シリウスは、夜空で一番明るい星だよ。"],"b213e98b":["056bc4e33238.mp3","北斗七星のひしゃくの先にある二つの星、メラクからドゥーベへ。その間の五倍くらいのばしていくと、北極星にたどり着くよ。"],"02706ad6":["28264d81a862.mp3","カシオペヤ座は、W か M の形。北極星をはさんで、北斗七星の反対側にあるの。だから片方が低いときは、もう片方が高いところにあるよ。"],"0d001339":["4def356529eb.mp3","ベガは織姫星、アルタイルは彦星。そしてデネブで、夏の大三角。七夕の伝説では、二人の恋人、ベガとアルタイルの間に天の川が流れているの。デネブは、はくちょう座にあるよ。"],"5612d4b7":["64b73dccc6f1.mp3","3Dで本物の夜空を見てみよう。明るい星はぜんぶ、本当の位置に置いてあるの。ドラッグで上も下もぐるっと見回して、星をタップすると名前が聞けるよ。"],"9a1b92aa":["56fa9e39b81e.mp3","星座は、人が思い描いた形なの。同じ星座の星でも、地球からの距離は全然違うことがあるよ。ベテルギウスの光は、届くまでに何百年もかかっているんだ。"],"f64337ac":["87159ae1c971.mp3","a二乗たすb二乗は、c二乗。どんな直角三角形でも、一番長い辺が分かる式だよ。"],"bd4506b5":["806f61807840.mp3","直角三角形には、直角の角が一つあるの。その向かいにある一番長い辺が、斜辺、c だよ。"],"4965b984":["2d3bb7114b1d.mp3","それぞれの辺に正方形を作ってみよう。数えてみて。小さな正方形9個と16個で、25個。小さい二つを合わせると、いつも大きい一つと同じになるの。"],"473adf81":["50b5c471b5fe.mp3","どうしてかな？大きな正方形の中に、同じ三角形を四つはめてみて。真ん中に残るすき間が、ちょうど c の二乗。並べ替えると、それが a の二乗たす b の二乗になるの。"],"c3985012":["9f3ec46ea84a.mp3","身近な例だよ。長さ5メートルのはしごを、壁から3メートル離して立てると、高さ4メートルまで届くの。それにテレビの大きさは対角線の長さ、つまり斜辺なんだよ！"],"46dd9800":["44c6aec08edf.mp3","日本では「三平方の定理」って呼ぶよ。自分の好きな数字でも試してみてね！"],"e80d7c8c":["b0444af2481e.mp3","貯金や投資がどうやって増えるのか。そして、早く始めるのが大事な理由。"],"df783d88":["bf8ea421db35.mp3","単利は、預けたお金にだけ利息がつくの。複利は、もらった利息にもまた利息がつく。増えた分が、また増えるんだよ。"],"c7bd85af":["32fb10a7ceaa.mp3","72の法則。72を一年の利回りで割ると、お金が二倍になるまでのだいたいの年数が分かるの。6パーセントなら、およそ12年だよ。"],"be427773":["ba80772ab2a7.mp3","少しずつでも、積み重なると大きくなるよ。毎月の金額、利回り、年数を変えて試してみてね。"],"379322be":["e76f64268ce8.mp3","投資は上がったり下がったりして、利益は決して保証されないの。手数料やインフレも大事だよ。これは計算の勉強で、投資のアドバイスではないからね。"],"ff2fb3ba":["9f045550a163.mp3","たまにたくさんやるより、毎日少しずつのほうがいい理由。"],"b6eb4a49":["935353f7a819.mp3","一日15分を一年続けると、91時間以上。長い一日なんて一度もなしで、二週間分のお仕事より多く勉強できるんだよ。"],"c3f1d0a7":["389281ff3dea.mp3","間をあけるのが効くの。覚えたことはすぐに忘れていくけど、復習するたびに忘れるスピードがゆっくりになるんだ。毎日の短い勉強が、その復習になるの。心理学では、分散効果って呼ぶよ。"],"7f6fa168":["8f5e5b8f2509.mp3","小さな成長も、複利で増えるよ。毎日1パーセントずつ良くなると、一年で約37倍。1.01の365乗は37.8だからね。素敵な計算だけど、約束じゃないよ！"],"88906b04":["84169df75963.mp3","コツは、かんたんにすること。毎日同じ時間に、小さな目標で、まだ楽しいうちにやめる。だから私のレッスンは短いんだよ！"],"9fdcc9cc":["d1906afcab9e.mp3","心臓がどこにあるか、四つの部屋、そして血液の流れ方。本物の解剖図もあるよ。"],"c6ae1d1f":["845d400ecdfc.mp3","あなたの心臓とご対面！これはかわいいイラストの模型だよ。ドラッグでぐるっと回して、それぞれの部分をタップすると名前が聞けるよ。"],"bc4003f7":["f640feaf4a22.mp3","心臓は、胸の真ん中、胸の骨のうしろ、二つの肺の間にあって、少しだけ左にかたむいているの。大きさは、だいたい自分のにぎりこぶしくらいだよ。"],"e256b730":["486e3b080008.mp3","肺が両側から心臓を包んでいるの。体の図では、その人と向かい合って見ているから、その人の左側は、あなたから見て右側になるよ。"],"1e6eb42d":["e1bba06508e4.mp3","心臓には四つの部屋があるの。上にある二つの心房が血液を集めて、下にある二つの心室が送り出す。模型でタップしてみてね！青が右側、赤が左側だよ。"],"4c19ba2d":["7d010fba7efc.mp3","右側は、酸素をもらうために血液を肺へ送るの。左側は、それを全身へ送り出すよ。"],"403c84ed":["e4402d5ca759.mp3","上にある二本の太い管が、体へ血液を運ぶ大動脈と、肺へ運ぶ肺動脈。心臓は、表面にある小さな冠動脈で、自分自身にも栄養を送っているんだよ。"],"0383c39f":["f809dcdc28a9.mp3","大人の心臓は、安静にしているとき、一分間におよそ60回から100回打つの。一日だと、およそ10万回！手首や首で脈を感じてみてね。"],"6fb71f95":["a241ec7360b4.mp3","マイクやギターを、FL Studio に録音する方法を、一歩ずつ。"],"c16c858f":["2c5a5d4a32c7.mp3","オーディオインターフェースが必要だよ。プリアンプつきのマイク入力、ギターやベース用の楽器入力、それにヘッドホンとスピーカーの出力があるの。"],"852af2cb":["1d7edf4872ac.mp3","Options の Audio settings で、Windows ならインターフェースの ASIO ドライバー、Mac ならそのデバイスを選んでね。録音するときは、128 や 256 サンプルみたいな小さいバッファにすると、遅れが少なくなるよ。"],"6fd5041f":["1ed74f97f9f9.mp3","ミキサーを開いて、空いているインサートトラックを選んでね。インサートの入力メニューで、インターフェースの入力を選ぶの。たとえば、マイクなら入力1。"],"d7214727":["d87538a8774f.mp3","インサートの録音ボタンで録音待機にして、一番大きいところがマイナス12からマイナス6 dB くらいになるようにレベルを合わせてね。赤いところまでは絶対に行かせないで。"],"4b7b2cec":["8dac25baa07c.mp3","録音ボタンを押して、プレイリストにオーディオクリップとして録音する設定を選ぶの。メトロノームとカウントインをオンにして、再生を押したら演奏スタート！"],"7d3cb60b":["4a7bd0c9169a.mp3","コツだよ。エフェクトは強くかけずに録音すること。あとから足せるからね。歌にはポップフィルターを使って、ギターは楽器入力につないで、アンプシミュレーターのプラグインはあとからかけよう。"],"113e696d":["67964df326c2.mp3","ぜんぶの音がちゃんと聞こえるように、トラックのバランスをとること。"],"7424b896":["1ffc63a8561e.mp3","楽器はそれぞれ自分のミキサーインサートに送ろう。そうすれば、楽器ごとに音量、パン、エフェクトを調整できるよ。"],"eb0df987":["81e67f7eaa6b.mp3","まずはレベルとパンから。プラグインを使う前に、フェーダーでだいたいのバランスをとってね。マスターには余裕、ヘッドルームを残しておくこと。"],"b6b89b75":["9848be572627.mp3","EQ では、Fruity Parametric EQ 2 を使って、ベースやキック以外の音の、80から100ヘルツより下の低いゴロゴロをカット。ぶつかっている周波数は、上げる前にまず削ろう。"],"cfa9e4b2":["9e46a02924c4.mp3","コンプレッサーは、大きい音と小さい音の差をならしてくれるの。だから歌がミックスの中で安定するよ。最初はやさしい設定でね。"],"646ca681":["432d04d84d3c.mp3","リバーブとディレイはセンドトラックに入れて、それぞれの楽器から少しずつ送るの。そうすると、ぜんぶの音が一つの空間にまとまるよ。"],"0ab28d6e":["58471834c890.mp3","ミックスは小さい音で、ヘッドホンでもスマホのスピーカーでも確認してね。好きな曲と聴き比べて、休憩もとること。耳は疲れるからね。"],"1bf0ab5a":["a1634db71fcc.mp3","曲をみんなに聴いてもらう前の、最後の仕上げ。"],"bacfea8f":["5498a6cae2df.mp3","マスタリングは最後のステップ。ミックス全体にやさしく EQ とコンプをかけて、マスターチェーンの一番最後にリミッターを入れるの。"],"6b44de53":["2802d61761a8.mp3","Fruity Limiter みたいなリミッターは、ピークが天井を超えないようにしてくれるの。天井はマイナス1 dB くらいにしてね。そうすれば、配信用に変換されたあとも音が割れないよ。"],"718669dd":["2675a4452788.mp3","配信サービスは、大きい曲の音量を下げて、だいたい同じ大きさにそろえるの。よくマイナス14 LUFS くらい。だから、ぎゅうぎゅうに音を大きくしても得しないんだよ。ラウドネスメーターがあると便利。"],"176f3e07":["3379466750e8.mp3","マスターは24ビットの WAV で書き出して、MP3 はそこから作ってね。公開する前に、いろんなスピーカーで聴いてみよう。"],"207802b6":["1266c026ca38.mp3","エフェクターの種類ごとの役目、よくある並べ順、そして音が聴けるボード。"],"286180fe":["784fb8e15d80.mp3","エフェクターは、ギターの音がアンプに届く前に音を変えるの。いくつかオンにして、ジャランと弾いてみて！"],"70450785":["15c721459d39.mp3","ドライブ系はざらっとした音を足すよ。オーバードライブは温かくて軽め、ディストーションは重く、ファズはワイルドでもこもこ。ディストーションをオンにして、リフを弾いてみて。"],"5a2be9b1":["5d5f3ae040dc.mp3","モジュレーション系は音を動かすの。コーラスはきらきら揺れて、トレモロは音量がふわふわ波打って、フェイザーとフランジャーはシュワーンってうねるよ。"],"76ddd0c4":["5e5a332cbab3.mp3","空間系は広がりを足すよ。ディレイは弾いた音をくり返して、リバーブは部屋やホールにいるような響きにするの。"],"3fcfd099":["d6d407c20b47.mp3","よくある順番は、チューナー、ワウ、コンプ、ドライブ、モジュレーション、ディレイ、そして最後にリバーブ。ルールは破ってもいいけど、まずはここから始めるといいよ。"],"63d6a3f1":["00efb8557c79.mp3","四分の三拍子のボックスステップ。イチ、ニ、サン、イチ、ニ、サン。"],"6f1f1390":["12bd0a395fae.mp3","ワルツは四分の三拍子。イチ、ニ、サン、イチ、ニ、サン、と数えて、イチで少しだけ体重をのせるの。"],"50d16af0":["d8954b34145a.mp3","カウント1。左足を前に出すよ。"],"a7453e71":["d951a861fc29.mp3","カウント2。右足を横へ、少しだけ前に出すよ。"],"7fb70994":["4921acf54ce3.mp3","カウント3。左足を右足の横にそろえる。これで箱の半分！"],"c8d7d37f":["ed74d746a623.mp3","もう一度カウント1。右足を後ろへ。カウント2、左足を横へ。カウント3、右足をそろえる。床に四角が描けたね！"],"5669554a":["8671a74e5f6c.mp3","再生を押して、一緒にステップしてみよう。四角がくるくる続くよ。背すじをのばして、腕で形を作って、カウント2と3で少しだけ伸び上がるの。パートナーは鏡みたいに、右足を後ろに引くところから始めるよ。"],"c930cb97":["105253e845ea.mp3","小切手の一つ一つの欄、そして安全に使う方法。"],"f3031498":["c1e3abf388d5.mp3","これはアメリカ式の小切手の見本だよ。どの部分も大事。一つずつ見ていこう。"],"1bac5b5e":["4f409ae4640b.mp3","右上に、今日の日付を書くよ。"],"cee9fe1b":["be3764824918.mp3","Pay to the order of のあとに、お金を受け取る人の名前を正確に書くの。個人の名前か、会社の名前だよ。"],"8b18d796":["27e104ebd785.mp3","四角い枠には、金額を数字で書くよ。ドルの記号のすぐ横から書き始めて、あとから何も書き足せないようにするの。"],"80fceb45":["e078915d5026.mp3","長い線には、金額を英語の言葉で書くよ。セントは100分のいくつ、と分数で。書き終わったら、余白に線を引いてうめてね。数字と言葉が合わないときは、言葉のほうが正式な金額になるんだよ。"],"c8649837":["27997c28ffda.mp3","メモの欄は書いても書かなくてもいいの。請求書の番号みたいな、自分用のメモだよ。最後に、銀行に登録しているのと同じサインをしてね。"],"37eecbef":["462fa61af916.mp3","下にある数字は、銀行のルーティング番号、あなたの口座番号、そして小切手の番号。何も書いていない小切手には絶対にサインしないで、いつもペンで書いて、書き間違えたら VOID と大きく書いてね。"],"54585999":["43d2ea547b61.mp3","日本では、個人で小切手を使うことはほとんどないの。みんな「振込」を使うよ。「小切手」は、ほとんど会社で使うものなんだ。"],"b1f788f9":["2f38c3db9d37.mp3","どれくらい体を動かせばいいか、安全なウォームアップ、そして私と一緒にやる6ラウンドのタイマー。"],"d23d78f9":["83b8edf4ff4b.mp3","世界保健機関、WHO によると、大人は一週間に150分から300分、早歩きくらいの運動をして、さらに週2日以上は筋トレをするのがおすすめなの。子どもは一日に一時間くらいだよ。"],"4f5b68c5":["9b027071a4ba.mp3","まずは5分から10分、ウォームアップしよう。足踏みして、腕を振って、肩を回して、筋肉の準備をしてね。"],"3f8665f2":["5fd913d1571b.mp3","速さより、正しいフォームが大事だよ。スクワットではひざをつま先と同じ向きにして、背中はまっすぐ。腕立て伏せは、頭からかかとまで一直線に。壁やひざをついた腕立てから始めるのもいいよ。"],"58b4e9f5":["ce7b9342ac96.mp3","胸の痛み、めまい、するどい痛みを感じたらすぐにやめてね。持病がある人は、始める前にお医者さんに相談しよう。"],"0ba6cc29":["6b2e001ec1b7.mp3","準備はいい？六つの動きを、それぞれ30秒、休憩は15秒。私がカウントするからね！"],"8a05ca69":["a9bc65c0621d.mp3","ガーリックバターパスタを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"fede41cc":["f1beca3224d0.mp3","かんたん野菜炒めを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"b47a5822":["fc12493c1bc1.mp3","トマトと卵の炒めものを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"29fe5be0":["4adfbd8bdd41.mp3","基本のパンケーキを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"adc0779b":["5106f70af631.mp3","かんたんチャーハンを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"4a81736d":["839dbe12e0fe.mp3","天板で焼くロースト野菜を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"92c9446c":["7882c8c3166c.mp3","お味噌汁を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"e04502da":["92d6237f84a9.mp3","小さなお鍋に水とだしの素を入れて、ふつふつするくらいに温めてね。"],"f630cd1e":["9f222a70ba8c.mp3","乾燥わかめを入れるよ。一、二分でふくらむからね。"],"c3a9dca7":["89cdd3b8718b.mp3","さいの目に切った豆腐をそっと入れて、一分くらい温めよう。"],"21b7588c":["25fee0974aac.mp3","火を弱くしてね。お玉に味噌をのせて、お汁にひたしながら溶かして、全体に混ぜるの。味噌を入れたあとは沸騰させないでね。煮立たせると風味が飛んじゃうから。"],"8a467106":["eb7ff3f2e344.mp3","すぐにお椀によそって、ねぎをのせてできあがり！"],"d20e02b3":["178bc796a65e.mp3","チキンと野菜のスープを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"f418e347":["51fefc35be09.mp3","大きなお鍋に油を入れて中火で温めて、玉ねぎ、にんじん、セロリを5分くらい炒めて、しんなりさせてね。"],"34a1f08d":["c95539dae5ef.mp3","にんにくを入れて、30秒くらい混ぜるよ。"],"1fca7977":["b2493168af9b.mp3","鶏肉、スープストック、じゃがいも、タイムを入れて、沸騰したら火を弱めて、ふたをして20分から25分煮込もう。"],"22023156":["4758113f8e46.mp3","鶏肉を取り出してね。真ん中が74度になっていれば火が通ってるよ。フォーク二本でほぐして、お鍋に戻してね。"],"af023d2f":["eec31acec808.mp3","塩とこしょうで味をととのえて、皮がパリッとしたパンと一緒にどうぞ。"],"bf9ffda0":["3ff359edfc26.mp3","どら焼きを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"d3a1d207":["b238c6c1d2c6.mp3","卵、砂糖、はちみつを、白っぽくなめらかになるまで泡立ててね。"],"612a99de":["ecb0902688fd.mp3","小麦粉とベーキングパウダーをふるい入れて、粉っぽさがなくなるまでさっくり混ぜるの。生地は15分休ませてね。"],"c1751bc8":["9c6200aa1047.mp3","水をスプーン一杯ずつ加えて混ぜて、とろっとしたクリームみたいにゆっくり流れるくらいにしてね。"],"840a3dfe":["7d08d0329806.mp3","フッ素加工のフライパンに油を薄くひいて、弱めの中火で温めるよ。一枚につき大さじ3杯くらいの生地を流して、表面にぷつぷつ泡が出てきたら、だいたい2分くらいね、ひっくり返してもう30秒焼こう。"],"c5c7e634":["67628e25c477.mp3","焼けた生地は、きれいなふきんをかけて冷ますと、しっとりやわらかいままだよ。一枚にあんこをぬって、もう一枚を重ねたらできあがり。召し上がれ！"],"0e4dd75f":["3fef0cec2b21.mp3","白玉団子を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"7db3b78d":["bd88c50a8e3c.mp3","白玉粉をボウルに入れて、水を少しずつ加えながらこねてね。耳たぶくらいのやわらかさになったらオーケー。これが日本の昔ながらの目安だよ。"],"dee57101":["ca6d24fa24c3.mp3","直径2センチくらいに丸めて、真ん中を少しへこませてね。そうすると、均一にゆであがるよ。"],"15ad59cd":["e6d6b76482ad.mp3","沸騰したお湯に入れてね。浮かんできたら、さらに1、2分ゆでよう。"],"7663b6f8":["1aff0d987141.mp3","氷水を入れたボウルにすくって、冷やしてきゅっとさせたら、水気を切ってね。"],"2e6c0c20":["b61fb9c25ca1.mp3","きなこ砂糖やあんこをかけて召し上がれ。もちもちしているから、小さい子やお年寄りには小さく切って、よくかんで食べてね。"],"cf5d64e0":["27da2abc65d8.mp3","いちごパフェを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"ca3fbad1":["0b20085a0bd8.mp3","ミートボールのトマト煮を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"ff5fdc20":["973866bc06c2.mp3","お客さんを紹介するね。マリアさんは小さな金物屋さんを経営していて、15年間ずっと紙の帳簿を使っているの。テクノロジーが嫌いなわけじゃないけど、「時間の節約」になるはずの道具が、逆に時間を食うのを何度も見てきたんだ。"],"e1774362":["ce05052001e4.mp3","マリアさんが本当に疑っているのは、投資に見合う効果、ROI があるかどうか。それに、自分と二人の従業員が使い方を覚えられるかも心配なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"52f3749e":["7ff743015d1d.mp3","機能の一覧から始めないで、今本当に困っていることから話そう。売り込む前に、紙の帳簿で何がうまくいかないのか聞いてみてね。"],"291e012a":["0d2e91a6ebbb.mp3","リスクなしで本当に試せる方法を提案しよう。あいまいな約束じゃなくて、お店がひまな週にお試しする、とかね。"],"c942aac3":["9e14d677ae44.mp3","覚えるのが大変、という不安から逃げずに、まっすぐ向き合おう。「かんたんですよ」と言うだけじゃなくて、準備がどれだけ少ないかを実際に見せてね。"],"dd5367e9":["55ea7a1f312e.mp3","お客さんを紹介するね。デイビッドさんは中規模の会計事務所のオフィスマネージャー。ライバル会社との二年契約が始まって、八か月たったところ。満足はしていないけど、乗りかえるのは面倒だと感じているの。"],"0e450ed7":["0694bd78e678.mp3","デイビッドさんは、身動きがとれないと感じているの。解約金や、乗りかえ中にサービスが止まることが心配なんだ。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"c663c8b1":["1d61c589b588.mp3","今のサービスの、具体的にどこが不満なのか聞いてみよう。ありきたりな売り込みより、そこが本当のカギになるよ。"],"7cdd1870":["afe7ee815ac9.mp3","乗りかえのコストに正面から向き合おう。解約金の分を埋め合わせできるか、それとも契約が終わるときのために今の価格で予約できるか。"],"f79d4854":["168f9bdff792.mp3","移行が具体的にどう進むのか、実際どれくらいしか止まらないのかを説明して、リスクの不安を小さくしよう。"],"e9baf4ca":["d89c6ade0c92.mp3","お客さんを紹介するね。トムさんは、同じコードつき掃除機を十二年使っているの。重いし、コードはじゃまだけど、ゴミはちゃんと吸ってくれるんだ。"],"5843de91":["24190b7bf5ec.mp3","トムさんは、わざわざ解決するほどの問題だと思っていなくて、値段にも敏感なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"1d16f937":["bb1199300663.mp3","「その掃除機はダメですよ」と言い争わないで。コードの長さとか、二階に運ぶときとか、困る瞬間を具体的に聞いて、トムさん自身に気づいてもらおう。"],"e5cec626":["7c15c93e750a.mp3","紙の上で性能を説明するより、軽さや動かしやすさを実際に見せるほうがずっと伝わるよ。"],"a169fb0e":["5c36e1e2d04a.mp3","値段の話になったら、「すぐに元が取れますよ」みたいな決まり文句じゃなくて、トムさんが実際にどれくらい使うかと比べてみてね。"],"0720c068":["dda580dacc3d.mp3","お客さんを紹介するね。プリヤさんはデモで商品を気に入ってくれたけど、次の四半期まで予算の承認が止まっているんだって。"],"8861edef":["f1cc0f893838.mp3","プリヤさんは、本当に予算が足りないだけで、興味がないわけじゃないの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"e2ac8f52":["ac75f070aa33.mp3","今ある小さな予算に収まる、もっと小さなプランや、お試しの導入がないか聞いてみよう。"],"5d2024e8":["336959bf0e5e.mp3","予算がいつ再開するのかをはっきり聞いて、開始は後でも、今日の価格で予約できると提案しよう。"],"18a794ff":["caed40b7bcfa.mp3","本当にお金の事情があるなら、無理に押さないで。それを尊重して、プレッシャーの代わりに具体的な次の一歩を提案しよう。"],"12ee1859":["494d2de212c0.mp3","お客さんを紹介するね。ジョーダンさんは学習コンテンツを気に入っているけど、8歳の子どものデータのプライバシーと、画面を見る時間を心配しているの。"],"ac2943e4":["2f011d73c2e4.mp3","ジョーダンさんは、値段の話より前に、まず信頼が必要なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"5eb41fb2":["67b5730ce636.mp3","値段や機能の前に、プライバシーと安全の具体的な話から始めよう。どんなデータを集めるのか、保護者が使える設定は何があるのか。"],"fff4766b":["5ccfa1a9e70f.mp3","時間制限つきや、画面の時間に上限があるお試しを提案しよう。言葉で安心させるだけじゃなくて、しくみで不安に応えるの。"],"215c3b69":["c41c4e6c2591.mp3","質問をたくさんしてもらって、信頼を作る段階にじっくり付き合おう。契約を急がないでね。"],"4e64a359":["bc0f6ded0f54.mp3","お客さんを紹介するね。アランさんは毎週末、自分で芝刈りと芝の手入れをしているの。三時間以上かかって、仕上がりはまあまあ。でも、自分でやることにちょっと誇りを持っているんだ。"],"e4e38cf5":["3a67bea18f7e.mp3","アランさんの反論は、お金の問題だけじゃなくて、「自分でやる」ことへのこだわりなの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"4c733d69":["0e3eaef548cd.mp3","売り込む前に、アランさんの努力をはっきり認めよう。今の仕上がりを責められていると感じさせないでね。"],"710b547d":["5e06f049380d.mp3","「あなたは下手ですね」じゃなくて、「週末をもっと好きなことに使えますよ」というふうに伝えよう。"],"bf2cd26e":["3cb93d69025c.mp3","長い契約じゃなくて、一回だけのお試しにすれば、乗りかえることへの心の抵抗が小さくなるよ。"],"4c33c9ff":["a4ad8dd45e5c.mp3","お客さんを紹介するね。キーシャさんは、会社が用意した基本の生命保険に入っていて、それで十分だと思っているの。足りない部分について、あまり考えたことがないんだ。"],"c74c8b47":["d98f7fb4344f.mp3","キーシャさんは反対しているわけじゃなくて、自分の保障の中身をよく知らないだけなの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"10194539":["71031b7b0d05.mp3","「それじゃ足りませんよ」と決めつけないで、会社の保険が実際に何をカバーしているのか聞いてみよう。多くの人は、実際より多く保障されていると思っているの。"],"4180ebc2":["673e277343ea.mp3","業界の一般的な数字じゃなくて、キーシャさん自身の収入や家族の人数を使って、本当に足りない部分があるかを見せよう。"],"7856429f":["b115b19bfc3f.mp3","不安をあおるプレッシャーはやめよう。足りない部分は、キーシャさんが自分で決めるための情報として伝えてね。"],"07f6bc32":["f5de118812a8.mp3","お客さんを紹介するね。ロバートさんは72歳で、自立して暮らしているの。「緊急通報ボタン」なんて持ったら、年寄りで人に頼っているみたいに見えると感じているんだ。"],"4e7ae8e2":["f263d478d3e3.mp3","ロバートさんが嫌がっている理由は、値段や機能じゃなくて、気持ちやプライドの問題なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"e0568d27":["17db4e782a6f.mp3","ここでの本当の反論は、理屈じゃなくて気持ち。機能の話より先に、その人らしさに寄りそおう。"],"c83c8162":["4ed70ca0b228.mp3","弱さの話じゃなくて、「もっと長く自立して暮らすための道具」として伝えてみよう。"],"91485ee4":["b63e54f05865.mp3","家族も一緒に話しているなら、家族の意見は主役じゃなくて、後押しにしてもらおう。ロバートさんが、自分で選んだと感じられることが大事なの。"],"9c48f385":["85e1ab1540f8.mp3","お客さんを紹介するね。ユキさんはもう三つ見積もりをとっていて、一番安いところに合わせて値下げしてほしいと、はっきり交渉してきているの。"],"17bbad2c":["77b47cf876bd.mp3","ユキさんは一番安い値段がほしいの。だから、見積もりの間で本当に何が違うのかを分かってもらう必要があるよ。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"f31aad17":["91fcc91c3321.mp3","ただ値下げするんじゃなくて、安い見積もりと比べて、材料、作りの丁寧さ、保証がどう違うのかを具体的に説明しよう。"],"3f521c2f":["00fabbee373c.mp3","交渉の余地があるなら、値段だけを下げるんじゃなくて、納期を長くする、違う木材にする、みたいに条件を交換しよう。"],"21abe1d9":["8269053c3a07.mp3","値段の差が本当の品質の差なら、値段だけで選ぶお客さんを逃しても大丈夫。自分の価値を安売りしないでね。"],"f62c2f81":["3482bc9a1408.mp3","お客さんを紹介するね。クリスさんは二年前に別のミールキットを試したの。量が少なくて、食べ物が傷んで届くことも多かったから、解約しちゃったんだ。"],"201c9548":["d92500680c21.mp3","クリスさんが疑っているのは、このジャンルそのものじゃなくて、前の嫌な経験のせいなの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"4d35faae":["257462afa3d4.mp3","なんとなく言い訳したり、ライバルの悪口を言ったりしないで、前の嫌な経験をちゃんと具体的に受けとめよう。"],"350c6188":["3b65916a69cf.mp3","量が少ない、傷んでいた、という具体的な失敗に、確かめられる具体的な話で答えよう。ふわっとした「大丈夫ですよ」じゃなくてね。"],"d3758589":["d25279dfea8d.mp3","一箱だけ、すぐ解約できる、みたいな気軽なお試しが、ここではいつも以上に大事。一度信頼が壊れているからね。"],"933610aa":["f39cb8f0f66e.mp3","やばい、マジ、ウケる、エモい。日本の若い人が本当に使う言葉と、それに一番近い英語のスラングを教えるね！"],"2160e299":["4ca280fdb018.mp3","left on read、sus、the GOAT、cringe、no cap。英語のスラングを、日本語ならどう言うか教えるね！"],"06b24b3e":["002db2c8242a.mp3","火をはく西洋のドラゴンと、雨を呼ぶ東洋の龍。そして、異世界でドラゴンが最強な理由。"],"14e91348":["aa29322362d5.mp3","ドラゴンは世界中のお話に出てくるけど、東と西では、想像の仕方が全然違うんだよ。"],"39e5e47c":["ab975fe0e8f8.mp3","西洋のドラゴンは、翼のある巨大な爬虫類。よく火をはいて、宝物を守っているの。聖ゲオルギウスみたいな昔のヨーロッパのお話では、英雄がたおす怪物なんだ。"],"fa66d4bb":["e9b3c985ea4b.mp3","東洋の龍は中国生まれで、ヘビみたいに長くて、翼はないのに雲の中を飛ぶの。雨と幸運を運んで、皇帝のシンボルでもあったんだよ。"],"f3fd0ac9":["4ce4ea51e1e5.mp3","日本語では、龍か竜と書いて、りゅう、またはたつと読むよ。龍神は海の神さまで、浦島太郎のお話に出てくる海の中の御殿が、竜宮城なんだ。"],"56e5e7a8":["13a45f292439.mp3","爪の数を数えてみて！中国の皇帝の龍は、ふつう五本の爪で描かれて、日本の龍は三本のことが多いんだよ。"],"b27e5ce2":["eddbcd462560.mp3","辰、たつは、十二支の動物のひとつ。2024年は辰年で、次は2036年だよ。"],"b2b27fcf":["1000f9fa00da.mp3","異世界やファンタジーのアニメでは、ドラゴンはたいてい一番強い生き物。ラスボスだったり、かしこい古い守り神だったり、意外とやさしい仲間だったりするよ。"],"7dce5650":["74812890496e.mp3","狐、狸、河童、天狗、鬼。日本の伝説の生き物たちを、江戸時代の本物の絵と一緒に。"],"3c5f266f":["c6ad7a3cf412.mp3","妖怪は、日本の伝説に出てくる精霊や生き物のこと。こわいのも、おもしろいのも、やさしいのもいるよ。"],"ed449f61":["3a8db1bf592d.mp3","狐。狐はお米の神さま、お稲荷さまのお使いだから、稲荷神社には狐の像があるの。昔のお話では、狐は年をとってかしこくなるほど尻尾が増えて、最大で九本になるんだって。"],"b7b6b0aa":["da67cbea7516.mp3","狸は、日本に本当にいる動物なんだよ！お話では、頭に葉っぱをのせて化ける、陽気ないたずら者。大きな笠をかぶった狸の置物が、お店の前でお客さんをお出迎えしているよ。絵文字はアライグマで、狸のそっくりさんなの。"],"1efff150":["a09d5fef2ede.mp3","河童は川に住んでいるの。頭の上にお皿があって、その水がこぼれると力が出なくなっちゃう！きゅうりが大好物だから、きゅうりのお寿司を、かっぱ巻きって呼ぶんだよ。"],"b1a0fb43":["3b66fe11e1b6.mp3","天狗は山の精霊。赤い顔に長い鼻、またはカラスのくちばしをしているの。武術の達人で、羽のうちわで空を飛ぶよ。"],"7395daef":["d8417024fcba.mp3","鬼は、角があって、虎の皮のパンツをはいて、金棒を持っているの。2月3日ごろの節分には、家族で炒った大豆をまいて、「鬼は外、福は内」って叫ぶんだよ！"],"97ee6429":["7236183334e5.mp3","とても長生きした猫は、尻尾が二つに分かれた猫又になるかもしれないの。それから、ろくろ首はふつうの人に見えるけど、夜になると首がのびるんだって！"],"93f859d6":["11a21c8722e1.mp3","昔の絵巻には、百鬼夜行、百の妖怪の夜の行列が描かれているの。1700年代に鳥山石燕という絵師が、何百もの妖怪を絵本に描いて、その絵は今でもマンガやアニメの妖怪の姿に影響しているんだよ。"],"0cae07a3":["3d417c6450c2.mp3","スライム、エルフ、ドワーフ、ゴブリン、妖精、人魚、グリフォン、不死鳥。そして、本当はどこから来たのか。"],"e6b8e5f3":["6c415ee161f7.mp3","異世界は、別の世界という意味。異世界のお話では、主人公がこんな生き物でいっぱいのファンタジーの世界に、転移したり転生したりするの。"],"f280bd7b":["ce9b5c03e16e.mp3","スライム。西洋のテーブルゲームでは、スライムは危ないどろどろの怪物だったの。でも1980年代の日本の RPG が、にっこり笑うかわいい最初の敵にしたんだ。今ではスライムは、異世界のシンボルだよ。"],"d80243e6":["62e393da741f.mp3","エルフは、北欧やゲルマンの伝説から来ているの。トールキンの指輪物語で、背が高くて優雅で長生きな姿になって、そのあとのファンタジーの絵やゲームで、あの有名なとがった耳がついたんだよ。"],"76e54ad3":["55505c037c68.mp3","ドワーフも北欧神話の出身。神話では、雷の神トールのハンマー、ミョルニルみたいな神々の宝物をきたえたの。ファンタジーでは、背が低くてひげの生えた、鉱夫や鍛冶屋だよ。"],"fd1d901e":["5237f7c39a6c.mp3","ゴブリンはヨーロッパの伝説の、小さくていたずら好きな生き物。オークはトールキンが有名にしたの。異世界では、ゴブリンが新米の冒険者の、はじめての本当の戦いになることが多いよ。"],"6a0c286e":["2d3d5ed4838a.mp3","妖精は、羽のある小さな自然の精霊。人魚は、半分人で半分魚。日本にも人魚の伝説があって、人魚の肉を食べた娘が800年生きたという、八百比丘尼のお話があるんだよ。"],"fa610878":["40bc8f8cec6f.mp3","組み合わせの生き物たち！グリフォンは、ワシの頭と翼にライオンの体。ユニコーンは、らせんの角が一本ある馬。そしてフェニックスは炎に包まれて、灰の中からよみがえるの。だから日本語では、死なない鳥、不死鳥って呼ぶんだよ。"],"94898e98":["a2198bc0ef98.mp3","異世界のお話は、ゲームからもいろいろ借りているの。魔王がモンスターを支配して、冒険者はギルドに入って、ステータス画面でレベルやスキルが見える。まるで RPG みたいにね。"],"cf47ec4c":["d35648085273.mp3","ほうきと大きなお鍋、ハロウィン、バーバ・ヤガー、マーリン、日本の陰陽師、そして魔法少女。"],"52aa5d86":["b40f5ade5be9.mp3","魔女と魔法使いは、世界中のお話に出てくるよ。"],"c5b6637a":["67f77ec7a172.mp3","ヨーロッパの伝説では、魔女は大きなお鍋で薬を作って、黒猫を飼って、ほうきで空を飛ぶの。"],"84ef2c9a":["c197216218e2.mp3","10月31日のハロウィンは、サウィンという昔のケルトのお祭りから来ているの。収穫の終わりのお祭りで、精霊が近くに来ると信じられていたんだ。魔女はハロウィンの人気の仮装になって、日本でもみんな仮装するよ。"],"57328c9b":["18625dbdabb8.mp3","ロシアにはバーバ・ヤガーっていう魔女がいて、その小屋はニワトリの足で歩き回るの！そしてマーリンは、アーサー王の伝説の有名な魔法使いで、王さまの相談役だよ。"],"e169deb2":["3193885d5402.mp3","日本の魔法使いといえば陰陽師。星や暦を読んだ、朝廷の占い師なの。千年くらい前に生きた安倍晴明は、式神という精霊をあやつれる伝説の人になったんだよ。"],"d6b4cb3e":["b67f29350b6c.mp3","巫女さんは、今も神社で、儀式や神楽の舞を手伝っているの。アニメでは、お札という紙のお守りで、よく精霊と戦っているね。"],"b9ddcd4d":["56ecc2411cf5.mp3","魔女のアニメは、それだけで一つのジャンル。魔法少女が、ステッキやお守りで変身して、みんなを助けるの。このジャンルは1960年代の日本で始まって、今も大人気だよ。"],"24d3c671":["7c2c4895d42a.mp3","少年、少女、異世界、メカ、日常系など。アニメのジャンルのしくみ。"],"1ea5b2f2":["c6cec26eaf49.mp3","アニメにはたくさんのジャンルがあって、日本では、もともとのマンガ雑誌の読者にあわせて、誰に向けて作られたかでも分けるの。"],"594d9474":["01f7bf9094a5.mp3","少年は男の子のこと。アクション、友情、修行、ライバル。少女は女の子のこと。気持ち、恋愛、友情。でも、誰でもどっちも楽しめるよ！"],"163eb96c":["e2ba35ba5b68.mp3","青年は大人の男性向け、女性は大人の女性向け。仕事や生活や恋愛の、もっと大人なお話が多いよ。"],"d38239a3":["9e4d69f0229f.mp3","異世界。誰かが別の世界に転移したり転生したりするお話。多くはウェブ小説やライトノベルから始まって、2010年代に大ブームになったの。"],"1d093765":["5d89eeff760b.mp3","魔法少女は、変身して悪と戦う女の子たち。メカは、中に乗って操縦する巨大ロボットだよ。"],"1b7239a3":["813832de4a79.mp3","日常系は、学校や仕事のふだんの毎日を描くの。癒し系は、ゆったり落ち着いた、リラックスするためのアニメだよ。"],"ec30bb00":["0afd43b4dd00.mp3","ほかにも、スポーツ、アイドル、ラブコメ、ホラー、SF もあるよ。好きなレッスンにはハートをタップして、もっと見たいときは「More please」のスイッチを入れてね！"],"e5d1eb9b":["8c33776d7bbf.mp3","節分の鬼、猫の日、犬の日、龍になる鯉、お盆、そして日本のハロウィン。"],"a3d7e52c":["e8541078cdc8.mp3","日本のカレンダーは、本物や想像の生き物の日でいっぱい。楽しいものを紹介するね。"],"efd929ab":["caedd937c576.mp3","2月3日ごろの節分は、昔の暦で春の始まりの前の日。誰かが鬼のお面をかぶって、みんなで炒った大豆をまいて、「鬼は外、福は内！」って叫ぶの。"],"cbc69931":["52a16ae981db.mp3","2月22日は猫の日。2、2、2を、ニャンニャンニャンって読めるからだよ！そして11月1日は犬の日。1、1、1で、ワンワンワン。"],"8fc9be69":["c935d1996e68.mp3","5月5日のこどもの日には、家族で鯉のぼりをあげるの。滝を登りきった鯉は龍になるという伝説があって、だから登竜門は、成功への入り口という意味なんだよ。"],"6ae12b71":["cf3fcafbd5c4.mp3","夏のお盆には、家族がご先祖さまの霊をお家にお迎えするの。野菜で小さな動物を作る家もあるよ。早く来られるように、きゅうりの馬。ゆっくり帰れるように、なすの牛。"],"47240bd2":["da9717262912.mp3","京都の伏見稲荷大社は、お稲荷さまの総本宮。何千もの赤い鳥居と、たくさんの狐の像があって、口に鍵や玉をくわえていることが多いんだよ。"],"e0ba9374":["a7ecd8563d19.mp3","そして10月31日には、日本の街もハロウィンの仮装でいっぱい。魔女も、妖怪も、アニメのキャラクターも、みんな並んで歩いているよ。"],"29aa7c0e":["a52a6e391341.mp3","三畳紀から白亜紀まで、ティラノサウルスとステゴサウルス、鳥が恐竜である理由、そして日本の恐竜。"],"60ea18b1":["f9005075fb6d.mp3","恐竜は、およそ1億6500万年もの間、陸を支配していたの。日本語では恐竜、おそろしい竜。英語の名前は、おそろしいトカゲという意味なんだよ。"],"aa0e0624":["ab618b471166.mp3","恐竜の時代、中生代には三つの時代があるの。三畳紀はおよそ2億5200万年前から2億100万年前、ジュラ紀は2億100万年前から1億4500万年前、白亜紀は1億4500万年前から6600万年前だよ。"],"cbe3b9be":["c8d6a8e5a0f5.mp3","ティラノサウルスは、一番最後、およそ6800万年前から6600万年前に生きていたの。体長は12メートルくらいで、歯はバナナくらいの大きさ！"],"bdbc1579":["0953d8ecf23b.mp3","ブラキオサウルスみたいな竜脚類は、首がとても長い草食恐竜。アルゼンチノサウルスみたいに、30メートルを超えたかもしれない種もいて、陸の動物で史上最大なんだよ。"],"8723c94a":["e7d2574afd35.mp3","背中に板、尻尾にトゲのあるステゴサウルスは、ジュラ紀に生きていたの。ティラノサウルスが現れるより8000万年くらい前に絶滅したから、私たちのほうが、ステゴサウルスよりティラノサウルスに時代が近いんだよ！"],"1371c54a":["4c4895a2da44.mp3","空を飛ぶ翼竜や、海の首長竜は恐竜じゃなくて、親戚の爬虫類なの。でも鳥は恐竜なんだよ！羽毛のある小さな恐竜から進化したから、ニワトリはティラノサウルスの生きている親戚なんだ。"],"81e0aa2e":["529dd6b99b7e.mp3","およそ6600万年前、直径10キロくらいの小惑星が、今のメキシコのチクシュルーブに衝突したの。大きな火山の噴火とあわせて、鳥以外の恐竜の時代は終わったんだよ。"],"408a6418":["f046ccd69ad0.mp3","日本にも恐竜がいたよ！福井県ではフクイラプトルみたいな化石がたくさん見つかっていて、大きな恐竜博物館もあるの。北海道のむかわ町では、アイヌ語の神さまという言葉から名前がついた、カムイサウルスが見つかったんだよ。"],"6546b55a":["816443da8b3f.mp3","日本の六つの犬種、ハチ公、人気のペットの犬、そして犬の日。"],"33bbab08":["732b0b4dbe85.mp3","犬は、いぬ。日本の犬は、ワンワンって鳴くよ。日本には、日本犬と呼ばれる六つの犬種がいるの。"],"80eecba1":["106c31337cb2.mp3","秋田犬、甲斐犬、紀州犬、柴犬、四国犬、北海道犬の六つは、ぜんぶ天然記念物として守られているんだよ。"],"2cb295b3":["d31cb6c51161.mp3","柴犬は一番小さい日本犬。狐みたいな顔、くるんと巻いた尻尾、そしていやなときの、すごく大きな柴犬の叫び声で有名だよ。"],"48039a5d":["90b4afb138d2.mp3","秋田犬は一番大きい日本犬。秋田犬のハチ公は、飼い主が亡くなったあとも、10年近く毎日渋谷駅で待ち続けたの。駅前の銅像は、有名な待ち合わせ場所だよ。"],"4e2921df":["4dab16e9cdaf.mp3","山梨県の甲斐犬は、虎みたいなしま模様の毛並み。紀州犬はたいてい白くて、四国犬は小さなオオカミみたい。たくましい北海道犬は、雪の多い北海道のために育てられたんだよ。"],"2fdbe56e":["697fb20ea499.mp3","日本で人気のペットの犬種は、ほとんどが小さな犬。トイ・プードル、チワワ、ミニチュア・ダックスフンド、ポメラニアン。柴犬もすぐうしろだよ。"],"02ef6aef":["f6395155297b.mp3","11月1日は犬の日。1、1、1が、ワンワンワンに聞こえるからだよ。わんちゃんを、いつもより多くお散歩に連れて行ってあげてね！"],"46fcfedd":["e88063f40129.mp3","ジャパニーズ・ボブテイル、三毛猫、招き猫、猫の駅長さん、猫島、そして猫の日。"],"3109ee3b":["e535c171c9f0.mp3","猫は、ねこ。猫は、ニャーって鳴くよ。日本は猫が大好き！"],"5268c261":["f3d5282aba2f.mp3","ジャパニーズ・ボブテイルは、自然の遺伝子で、短いふわふわのポンポンみたいな尻尾をしているの。何百年も前から日本に住んでいるんだよ。"],"7cc1d45a":["5760b066311f.mp3","三毛猫は、白、茶色、黒の三色の猫。三毛猫はほとんどがメスなの。茶色と黒の色はX染色体で決まるから、両方の色が出るにはXが二つ必要なんだ。オスの三毛猫は、とってもめずらしいんだよ。"],"696d9d93":["6280f5e6de2a.mp3","招き猫は、お店にお客さんを招く猫。左手をあげているとお客さんを、右手をあげているとお金や幸運を招く、とよく言われるよ。"],"2bf5b21c":["6f6f58fb3b79.mp3","2007年に、たまという三毛猫が、和歌山の貴志駅の駅長さんになったの。たまに会いに来る観光客のおかげで、小さな鉄道の路線が救われたんだよ。"],"c75dccb0":["783a9e8b6e1c.mp3","日本には、田代島や青島みたいな猫島があって、人より猫のほうが多いんだよ。"],"507b2f67":["885d19b5214b.mp3","日本で人気の猫種には、スコティッシュフォールドやマンチカンがいるよ。フォールドの折れた耳は軟骨の遺伝子によるもので、関節の痛い病気になることがあるから、繁殖には注意が必要だと多くの獣医さんが言っているの。日本の猫の多くは、元気な雑種なんだよ。"],"96028663":["c9cbcf88a958.mp3","2月22日は猫の日。2、2、2が、ニャンニャンニャンに聞こえるからだよ！"],"67452e23":["7cfee40badfe.mp3","たくさんの小さなコアが一度に働く。グラフィックス、シェーダー、VRAM、そして AI が GPU で動く理由。"],"8732f05f":["319541f37508.mp3","GPU、グラフィックス・プロセッシング・ユニットは、何千もの小さな計算を同時にするために作られたチップだよ。"],"137d4a36":["5e5a7ddae6da.mp3","CPU には、いろんな仕事を一つずつ順番にこなすのが得意な、強いコアが少しだけあるの。GPU には、同じ種類の仕事をいっせいにする、シンプルなコアが何千もある。これを並列処理って呼ぶよ。"],"e2135dea":["05cdf50eefcc.mp3","フル HD の画面は、1920かける1080ピクセルで、200万以上。GPU はその一つ一つの色を、一秒に60回以上計算しているんだよ。"],"9a056513":["379fa43e9043.mp3","グラフィックスのパイプライン。3Dのモデルは三角形でできているの。頂点シェーダーが三角形を動かして回して、ラスタライズでピクセルにして、ピクセルシェーダーが光やテクスチャーで、一つ一つのピクセルに色をつけるよ。"],"4e587578":["3f8cd414cd1f.mp3","GPU には、VRAM という専用の速いメモリーがあって、テクスチャーやモデルを、それを使うコアのすぐ近くに置いておけるの。"],"20102e22":["6db183840233.mp3","AI が GPU で動くのは、ニューラルネットワークのほとんどが、巨大な行列のかけ算だから。同じかけ算と足し算を、何百万回もくり返すの。今の GPU には、NVIDIA の Tensor コアみたいな、そのための特別なユニットまであるんだよ。"],"d21a039d":["9fc6bc8730ca.mp3","プログラマーは API を通して GPU とやりとりするの。グラフィックスには Vulkan、DirectX、Apple の Metal。一般的な計算には、NVIDIA の CUDA。そしてこのアプリの3Dの惑星や心臓は、あなたのスマホの GPU が WebGL で描いているんだよ！"],"8991f835":["9f8a627d0066.mp3","一つのチップに一台のコンピューター。大きいコアと小さいコア、GPU、NPU、カメラの ISP、モデム、そしてスマホが熱くなる理由。"],"0e8163f3":["5c66923ce803.mp3","スマホのチップは、システム・オン・チップ、SoC。指の爪くらいのシリコン一枚に、コンピューターがまるごとつまっているの。"],"bc9b8cdd":["009a76c6fe09.mp3","CPU には二種類のコアがあるの。重い仕事のための大きくて速いコアと、軽い仕事をこなしてバッテリーを節約する小さくて効率のいいコア。Arm はこの考え方を big.LITTLE と呼んでいるよ。"],"39e80e20":["1d66d6315067.mp3","グラフィックスのための GPU、顔認証や写真の加工みたいな AI 機能のための NPU、ニューラルエンジン。そして、カメラのセンサーのデータを写真にする ISP、画像信号プロセッサーがあるよ。"],"b0c3674b":["b972e1448336.mp3","モデムは 4G や 5G みたいなモバイルネットワークにつなぐの。Wi-Fi や Bluetooth の無線もあるよ。ただ、モデムが別のチップになっているスマホもあるの。"],"5956865a":["1f0ca6c354a6.mp3","スマホのチップのほとんどは、Arm の命令セットを使っているの。Apple の A シリーズ、Qualcomm の Snapdragon、Google の Tensor、MediaTek の Dimensity は、どれも Arm だよ。"],"326b2c6e":["b35f50942f97.mp3","トランジスタは、オンとオフを切り替える小さなスイッチ。最上位のスマホのチップには、100億個よりずっと多く入っているの。3ナノメートルみたいな名前は、製造の世代のラベルで、正確な大きさじゃないんだよ。"],"57acfb28":["2bcab8719faf.mp3","熱は大敵！ほとんどのスマホにはファンがないから、チップが熱くなりすぎると、安全のために自分でスピードを落とすの。これをサーマルスロットリングって呼ぶよ。"],"8c68b4db":["3462fe24070a.mp3","コード、エディター、コンパイラー、Git、デバッガー、SDK、Claude Code みたいな AI の助っ人、そしてチップの設計の仕方。"],"124f5187":["49f05908157c.mp3","ソフトウェアは、ソースコードから始まるの。Python、JavaScript、Swift、C みたいなプログラミング言語で書いた文章だよ。"],"b1327974":["22b7e21c637b.mp3","開発者は、エディターや IDE、統合開発環境でコードを書くの。VS Code、Android Studio、Xcode みたいなものだよ。まちがいに色をつけて、入力も手伝ってくれるの。"],"3f01cdba":["ad6ba1986c6e.mp3","コンパイラーは、コードをチップが実行できる機械の命令に翻訳するの。Python みたいな言語は、インタープリターを使って、代わりにコードを一歩ずつ実行するよ。"],"2e4f88a4":["c25e2b21664c.mp3","Git はコードのすべてのバージョンを残してくれるから、まちがいを元に戻したり、チームで作業したりできるの。GitHub は Git のプロジェクトをオンラインで預かってくれるところ。このアプリも、そこに住んでいるんだよ！"],"6069bf45":["ccf47213a8b1.mp3","デバッガーを使うと、プログラムを一時停止して、一行ずつ中をのぞけるの。テストは、変更するたびにプログラムがまだちゃんと動くか確かめる、小さなプログラムだよ。"],"a6ba2ed6":["b6499c698e05.mp3","SDK、ソフトウェア開発キットは、Android アプリのための Android SDK みたいに、その環境用の道具をそろえてくれるの。npm や pip みたいなパッケージマネージャーは、ほかの人が書いたライブラリーを持ってきてくれるよ。"],"dd730fee":["feb4c5588f40.mp3","Claude Code みたいな AI のコーディングアシスタントは、プロジェクト全体を読んで、コードを書いて、テストを動かして、エラーを説明してくれるの。このアプリも、そうやって作られたんだよ！"],"1f892a3b":["f58fe25f3774.mp3","チップも、コードで作るんだよ！エンジニアは Verilog や VHDL みたいなハードウェア記述言語で回路を書いて、シミュレーターでテストして、コードで回路を組みかえられる FPGA で試してから、ファウンドリーっていう工場に設計を送るの。"],"1f8b8091":["482d2bbbd986.mp3","スイッチをタップしてね。論理ゲート、半加算器、そして CPU の心臓、4ビットの加算器。"],"90a45558":["a403be8d0ef1.mp3","どんなチップも、論理ゲートからできているの。1と0を受け取って、1と0を出す小さな回路だよ。A と B をタップして、ゲートが変わるのを見てみて！"],"0f01942a":["67134725ce62.mp3","AND は、両方が1のときだけ1。OR は、どちらかが1なら1。NOT はビットを反転させて、XOR は、二つが違うとき1になるの。ぜんぶの場合を、真理値表にまとめたよ。"],"f9282018":["ba525ea2076d.mp3","ゲートは、スイッチとして働くトランジスタでできているの。CMOS の NAND ゲートは、たった四つのトランジスタで作れて、どんな回路も NAND ゲートだけで作れるんだよ。"],"cde779eb":["ec08c3a6cb10.mp3","半加算器を作ってみよう。二つのビットを足す回路だよ。和は A XOR B、桁上がりは A AND B。1たす1をやってみて。和が0、桁上がりが1で、二進数の10、つまり2だね！"],"c7e75594":["1cadb12e45f1.mp3","全加算器は、桁上がりも受け取るから、つなげていけるの。全加算器を四つつなぐと、15たす15まで足せる4ビットの加算器になるよ。ビットをタップしてみてね！"],"0eb80de9":["655d7e2d8c35.mp3","これが、CPU の ALU、算術論理演算装置の心臓部。本物のチップは、何十億個ものトランジスタでできていて、こういうゲートやブロックにつながっているんだよ。"],"bc0dcfd3":["941eaa3b7c42.mp3","本物を作ってみたい？初心者でも Verilog でチップを設計して、FPGA のボードで試せるし、Tiny Tapeout みたいなオープンなプロジェクトに参加することもできるの。いろんな人の小さな設計を、一つの本物のチップにのせてくれるんだよ。"],"fea96d8e":["2db9e8b681fe.mp3","ミント、生姜、カモミール、日本のハーブ、漢方、そして安全の大事なルール。医療のアドバイスじゃなくて、知識のレッスンだよ。"],"e82c57c1":["c1252a38bbdb.mp3","ハーブや薬草は、何千年も前から、味つけや癒しのために使われてきたの。このレッスンは知識のためで、医療のアドバイスではないからね。"],"88091a7a":["91d659e7d7fb.mp3","ペパーミントティーは、食後の定番の飲み物。メントールが、あのスーッとする感じを作るの。ペパーミントオイルのカプセルには、過敏性腸症候群の症状をやわらげるという研究もあるよ。"],"530e17c1":["d5c289b1ac07.mp3","生姜には、つわりをふくめて、吐き気をやわらげるという、しっかりした根拠があるの。でも妊娠中の人は、お医者さんに確認してね。日本では、お寿司と一緒に、甘酢漬けの生姜、ガリが出てくるよね。"],"58c114d3":["9e828b01c186.mp3","カモミールティーは、カフェインのない、やさしい寝る前の飲み物。キク科の植物だから、ブタクサのアレルギーがある人は反応することがあるよ。"],"805e1d98":["fe093d14c3d0.mp3","日本の台所には、日本のハーブがあるよ。紫蘇、三つ葉、茗荷、そして柚子の皮。緑の紫蘇の葉は、お刺身にそえるよね。"],"396b3e97":["bbd94c60ffc7.mp3","漢方は、中国の医学をもとに日本で発展した、伝統的な薬草の医学。日本では、お医者さんが健康保険でおよそ148種類の漢方薬を処方できるんだよ。"],"421fbf46":["43de78ba79ec.mp3","自然なものが、安全とはかぎらないよ！セイヨウオトギリソウは、ピルや一部の心臓の薬みたいな、ほかの薬が効かなくなることがあるの。ジギタリスはきれいだけど毒があって、正確な量で使う心臓の薬、ジゴキシンのもとになったんだよ。"],"4c394248":["4e36e981771f.mp3","大事なルール。信頼できるお店で買うこと。はっきり見分けられない野草は、絶対に食べないこと。飲んでいるハーブやサプリは、お医者さんや薬剤師さんに伝えること。特に、妊娠中や薬を飲んでいるときはね。"],"9a88ed9b":["79909b041b3f.mp3","規則。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"9eb95882":["36610fb2d1d5.mp3","飛行機、回転翼機、パワードリフト、ウェイトシフト機の資格には、17歳以上が必要なの。グライダーと気球なら16歳だよ。"],"90b9e40a":["cee24abe36db.mp3","40歳未満のパイロットなら、第3種の航空身体検査証明は、検査を受けた月から60暦月有効。40歳以上なら24か月だよ。"],"9e97add8":["95fef5010292.mp3","14 CFR 61.57 では、お客さんを乗せるには、過去90日以内に、同じカテゴリーとクラス、型式限定が必要ならその型式の機体で、離陸と着陸を3回ずつしている必要があるの。尾輪式の飛行機なら、着陸は完全に止まるまで、フルストップだよ。"],"560fbb7e":["480c23eb658c.mp3","BasicMed では、認められたオンラインの医学講習を24暦月ごとに受けて、さらに48か月ごとに、州の免許を持つお医者さんの診察を受けるの。FAA の総合診察チェックリストを使うよ。"],"ae37a7fe":["51a3b3a50e67.mp3","14 CFR 61.57 では、夜間のフルストップの離着陸は、これから飛ぶのと同じカテゴリーとクラス、必要なら同じ型式の機体でやる必要があるよ。"],"85616172":["0c386933f401.mp3","フライトレビューは24暦月ごとに必要。1時間以上の飛行訓練と、1時間以上の地上講習をして、ログブックに裏書きをもらうの。"],"528b39b5":["26500f603102.mp3","14 CFR 91.207 では、ELT の電池は、使用時間が合計1時間になったとき、または寿命や充電の50パーセントを過ぎたとき、早いほうで交換しなきゃいけないの。"],"868c8a4f":["6ad00e7abe74.mp3","14 CFR 91.151 では、昼間の VFR では、着陸予定地点からさらに30分以上飛べる燃料が必要だよ。"],"e8f79afa":["24e7220b92cf.mp3","夜間なら、14 CFR 91.151 では、通常の巡航速度で45分以上の予備燃料が必要だよ。"],"a5a16f44":["0c971a395cd9.mp3","14 CFR 91.3 では、機長は航空機の運航に直接の責任を持ち、最終的な決定権を持つ、と決められているの。"],"09bed7b6":["a8a0952ad29d.mp3","14 CFR 61.113 では、自家用パイロットは、自分が少なくとも頭割りの分を払えば、運航費用を乗客と分け合ってもいいの。"],"dde2b1d8":["b23cb66db93d.mp3","自家用パイロットは基本的に、報酬をもらって人や物を運ぶことはできないの。14 CFR 61.113 には、費用の頭割り、仕事のついでの飛行、一部のチャリティーや捜索の飛行みたいな、限られた例外があるよ。"],"111be4cd":["cdcca4499ad9.mp3","AROW は、機内に必要な書類を覚えるための合言葉。耐空証明書、登録証明書、運用限界、これは POH や AFM もふくむよ。そして重量と重心のデータ。"],"a6408430":["f65ee547ce18.mp3","耐空性改善通報、AD は、飛行の安全のために FAA が出す、必ず守らなきゃいけない修正の指示。決められた通りに対応する必要があるよ。"],"b1f453d7":["c449fdeaed48.mp3","14 CFR 91.409 では、ほとんどの航空機は、耐空性を保つために、過去12暦月以内に年次点検を受けている必要があるの。"],"1f1d0ee0":["3ab8d18e66d4.mp3","14 CFR 91.409 では、お金をもらって人を運ぶ航空機は、ふつう年次点検に加えて、100時間点検も必要だよ。"],"3b1ccc5b":["9785fb14ded7.mp3","地上3000フィートより上の VFR では、磁針路が0度から179度なら、奇数千フィート足す500フィート、たとえば5500や7500。180度から359度なら、偶数千フィート足す500フィートで飛ぶよ。"],"5d2a2c44":["64110e35f8bd.mp3","14 CFR 91.113 では、遭難している航空機は、ほかのすべての航空機に対して優先権を持つの。"],"f2632338":["6d5b5e56f511.mp3","人が密集している地域の上では、最低安全高度は、機体から水平2000フィート以内の一番高い障害物より、1000フィート上だよ。"],"ecd43465":["6ddb53f70fb2.mp3","密集地以外の上では、最低安全高度は地表から500フィート。ただし、海の上や人がまばらな地域では、人、船、車、建物から500フィート以上離れていればいいの。"],"093608cf":["60e860035b3d.mp3","14 CFR 91.211 では、客室の気圧高度が12500フィートを超えて14000フィートまでの間を、30分より長く飛ぶ場合、その部分では最小限の乗員が酸素を使わなきゃいけないの。"],"7ea70cf8":["70f10e8aad7a.mp3","客室の気圧高度が14000フィートを超えたら、最小限の乗員は、その高度にいる間ずっと酸素を使う必要があるよ。"],"5987f85a":["1230c7f32d88.mp3","91.103 では、どの飛行でも、使う予定の空港の滑走路の長さと、離着陸に必要な距離のデータを確認するの。IFR の飛行や、空港の近く以外を飛ぶときは、天気の報告と予報、必要な燃料、予定通りにいかないときの代わりの案、分かっている交通の遅れも確認するよ。"],"1acb5ca7":["93b77c6d4aa2.mp3","14 CFR 91.15 では、地上の人や物にけがや損害を与えないよう、十分な注意をすれば、物を落としてもいいの。"],"a38aea6f":["b54017addbc1.mp3","BasicMed での飛行は、高度18000フィート以下、指示対気速度250ノット以下に限られるの。ほかにも、報酬をもらう飛行はだめ、みたいな制限があるよ。"],"f7187d99":["390fa1b21a23.mp3","14 CFR 91.13 では、他人の命や財産を危険にさらす、不注意で無謀な操縦を広く禁止しているよ。"],"278ae1b4":["229587d86b96.mp3","ログブックには、日付、機体のメーカー、型式と登録記号、飛行経路、飛行時間を書くの。飛行時間は、昼間、夜間、実際の計器飛行や模擬計器飛行みたいに、条件ごとに分けて記録するよ。"],"71a0ccb1":["47ea62f25342.mp3","14 CFR 61.31 では、高性能機、複雑な機体、尾輪式、与圧機などに乗るには、必要な地上と飛行の訓練を受けて、認定された教官からログブックに裏書きをもらう必要があるの。"],"545473e5":["6afd11a16503.mp3","VFR の飛行計画は、ほとんどの飛行で法律上は必要ないけど、安全のために強くおすすめされているの。到着が遅れたときに捜索救助を始めるきっかけになるからね。防空識別圏みたいに、独自に飛行計画が必要な空域もあるよ。"],"2c736d2b":["d1200d5cba90.mp3","整備記録は、その作業が新しい作業に置きかわるまで、または 14 CFR 91.417 で決められた期間、保管しなきゃいけないの。機体の点検と整備の歴史を残すためだよ。"],"b08532e7":["1512ce92bb28.mp3","14 CFR 91.207 には、ELT がなくてもいい例外があるの。たとえば、出発した空港から50海里以内でおこなう、一部の飛行訓練だよ。"],"7356af7a":["b088f5cef247.mp3","14 CFR 91.413 では、ATC の要件を満たすためにトランスポンダーを使うには、過去24暦月以内に試験と点検を受けている必要があるよ。"],"837b4c1c":["e3332a9e8295.mp3","空域。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"1c249527":["d1dce0aef9d9.mp3","クラス A 空域は、平均海面から18000フィートから、FL600、つまり60000フィートまでだよ。"],"8fda50d5":["1a4782f738af.mp3","クラス B 空域に入るには、無線で連絡するだけじゃなくて、ATC からはっきりした許可をもらう必要があるの。"],"6520b7dd":["0c4b3787f9e8.mp3","クラス C 空域では、入る前に管制機関と双方向の無線連絡を確立して、それを保つ必要があるの。特別な許可はいらなくて、無線の連絡だけでいいよ。"],"180b55ea":["75887795b1ec.mp3","クラス C と同じように、クラス D 空域でも、入る前に ATC と双方向の無線連絡を確立する必要があるよ。"],"2be267e3":["0a3edfb8febe.mp3","アメリカ上空のクラス E 空域の多くは、地上1200フィートから始まるの。一部の空港の近くでは地上700フィートから、地表まで下りてきているところもあるよ。"],"e49a52af":["bd6730dd07be.mp3","クラス G は管制されていない空域。ここを飛ぶ VFR の機体に、ATC は間隔をあける業務をしないの。"],"998e2b86":["d6577f569170.mp3","高度10000フィート未満のクラス E では、雲の下に500フィート、上に1000フィート、横に2000フィート離れて、視程は3法定マイル必要だよ。"],"a5b2f769":["9f90872bc25d.mp3","特別有視界飛行、スペシャル VFR には、飛行視程1法定マイル以上、雲から離れていること、そして ATC の許可が必要なの。夜間は、パイロットが計器飛行証明を持っていて、機体も計器飛行の装備がある必要があるよ。"],"cf4c8ab6":["5dfec34cedde.mp3","TFR、一時的な飛行制限は、14 CFR 91.137 から 91.145 にもとづいて出されて、決められた範囲の飛行を制限するの。警備、災害救助、宇宙関連の運用、要人の移動などのためが多いよ。"],"7490a3af":["1a6742a5d702.mp3","MOA、軍事作戦区域は、制限空域じゃないの。VFR で飛んでもいいけど、活動中かを確認して、軍の訓練に注意してね。"],"7d4add6a":["aedece689237.mp3","飛行禁止区域は、安全保障などの理由で決められていて、特別な許可なしには飛べないよ。"],"3863567e":["0291d1a6af01.mp3","制限区域には、砲撃みたいな、目に見えないことも多い危険があるの。区域が活動中なら、管理している機関の許可が必要になることがあるよ。活動時間は、チャートや NOTAM で分かるの。"],"263310be":["7bbe18d99e06.mp3","警告区域は、アメリカの海岸から3海里より外側の、国内や国際の海の上にあって、関係のない航空機には危険な活動がおこなわれているよ。"],"47b5024d":["41128af5acaf.mp3","注意区域は、訓練の飛行がとても多い場所や、めずらしい種類の飛行がある場所を知らせるの。ふつうの規則で飛べるけど、特によく見張ってね。"],"e4dc3427":["9de0f5c6f244.mp3","軍事訓練ルート、MTR は、軍の飛行訓練のためのもので、低い高度を250ノットを超える速さで飛ぶことが多いの。セクショナルチャートに描いてあるから、横切るときは特に注意してね。"],"17d67190":["15278c1a8e38.mp3","ビクター航空路は、ふつう幅8海里で、中心線の両側に4海里ずつ。地上1200フィートから、クラス A の下の端の18000フィート未満までだよ。"],"5eb6b37b":["7d4f3a992438.mp3","14 CFR 91.215 では、クラス B の主要空港から30海里以内、地表から10000フィートまでは、ふつうモード C のトランスポンダーを作動させる必要があるの。これをモード C ヴェールって呼ぶよ。"],"8917923c":["0a85ef9291b9.mp3","クラス B 空域は、太い青の実線で描かれるの。同心円や不規則な形が多くて、それぞれの層に下限と上限の高度が書いてあるよ。"],"ddc3fc40":["05ff13355f70.mp3","一部のクラス B 空域には、VFR の通り道や通過ルートが公表されていて、決められた手順でその中や周りを通れるの。いつも最新のチャートと地元の手順を確認してね。"],"5c8f3036":["0ad6dc4d5305.mp3","NOTAM は、滑走路の閉鎖、設備の故障、新しい一時的な飛行制限みたいに、飛行の安全に関わる一時的で急ぎの情報を知らせてくれるよ。"],"e1e449af":["bccf4c88eb57.mp3","クラス B、C、D 空域は、交通量や複雑さに合わせて空港の周りに作られるの。一番混んでいる空港がクラス B、小さめの管制塔のある空港がクラス D だよ。"],"d1a43a26":["2e2444b35569.mp3","クラス B のすぐ外側でも、主要空港に向かうたくさんの交通が集まってくるの。クラス B の外にいても、いつも以上によく見張ってね。"],"296f6eba":["0a77a03c0c7c.mp3","管制空域は、クラス A から E まで。ATC のサービスの度合いはいろいろで、クラス A は完全な管制、クラス E はもっと限られたサービス。管制されていない空域がクラス G だよ。"],"2479d05f":["c88e5829048d.mp3","セクショナルチャートでは、クラス D 空域はふつう青い点線で描かれるの。空港の周りの、地表からの管制空域の境目を表しているよ。"],"4e0096b3":["38d15bf6ba34.mp3","マゼンタの点線は、ふつうクラス E の地表区域を表すの。いつもは上にあるクラス E 空域が、その空港の周りでは地面まで下りてきているんだよ。"],"3da72bd1":["8977f53ad11a.mp3","クラス G 空域の VFR の気象条件は、昼より夜のほうがきびしいの。目で見える手がかりが少ないから、もっと視程と雲からの距離が必要になるよ。"],"73042a14":["0faccda02d1c.mp3","クラス E で高度10000フィート以上、地上1200フィートより上なら、VFR には視程5法定マイル、雲の下に1000フィート、上に1000フィート、横に1法定マイルが必要。10000フィート未満よりきびしいよ。"],"3785cbdc":["b7992cd7757f.mp3","気象。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"2173e1d8":["d9fd483b6776.mp3","気温と露点の差が小さいと、空気が飽和に近いということ。霧、もや、低い雲ができやすいよ。"],"41be1194":["2855308e9323.mp3","安定した空気では、揺れが少なくて、層状の雲ができて、もや、煙、霧がこもって視程が悪くなりやすいよ。"],"282f11e3":["a71a19634a91.mp3","不安定な空気は、上にのびる雲を作るの。積雲ができて、揺れがあって、にわか雨から離れれば、たいてい視程はいいよ。"],"0b45e36b":["3aa5dfaed4df.mp3","寒冷前線が通ると、風向きが急に変わって、前線のうしろでは気温が下がることが多いの。空気がしめっていて不安定なら、境目にそってにわか雨や雷雨ができるよ。"],"4a40f606":["2bc5ad95b7df.mp3","気温が高い、湿度が高い、標高が高い。どれも密度高度を上げて、エンジンの力、揚力、プロペラの効率を下げるの。"],"7324825c":["c69495769bbf.mp3","METAR と TAF の風向きは、真方位で報告されるの。だから 10008KT は、真方位100度から8ノットの風。管制塔や ATIS が伝える風は、滑走路の番号に合わせた磁方位だよ。"],"df378e5d":["4ea1214d905c.mp3","標準大気では、高度が1000フィート上がるごとに、気温がおよそ2度、華氏なら3.5度下がるよ。"],"23f501b4":["c80de3f97135.mp3","TAF は一日に何回か出されて、空港のおよそ24時間から30時間先までの天気を予報するの。"],"c490a57f":["d7c886f5d411.mp3","マイクロバーストは、強い下降気流が地面で広がる現象なの。まず強い向かい風、そのあと強い追い風になるから、進入や出発のときにはとても危険なウィンドシアだよ。"],"6688620e":["fceb0399eabd.mp3","雷雨のセルは、積雲期、つまり成長する段階、それから成熟期、一番雨が強くて上昇気流と下降気流も一番強い段階、最後に下降気流が中心の消滅期、と進むよ。"],"2504643d":["7154767dfde4.mp3","放射霧は、晴れて風のない夜にできるの。地面が放射で熱をどんどん失って、すぐ上の空気が露点まで冷えるからだよ。"],"7af4fa7e":["0f60bf661599.mp3","移流霧は、しめった空気が冷たい地表の上を横に流れて、飽和するまで冷やされてできるの。海岸ぞいでよく見られるよ。"],"8a349e9b":["1705089aa241.mp3","機体への着氷には、雲や降水みたいな目に見える水分と、風が当たる部分の温度が0度以下であること、その両方が必要なの。"],"f7b5caa3":["4957587f098e.mp3","クリアアイスは表面に広がって、なめらかで密度が高い、かたい層を作るの。見えにくくて取りにくいから、空力性能を大きく下げてしまうよ。"],"9b0c5662":["0afffc00cabd.mp3","上空の風と気温の予報には、いろんな高度の予想気温がのっているの。だから、氷点、つまり0度になる高度がどこか、見当をつけられるよ。"],"859f3ed6":["644446b1e956.mp3","コンベクティブ SIGMET は、危険な対流性の天気を知らせるの。激しい雷雨や雲にかくれた雷雨、雷雨の列、雷雨にともなうひょうや竜巻だよ。"],"3163177e":["c67279ae394d.mp3","AIRMET シエラは、IFR の気象状態を知らせるの。広い範囲で雲底が1000フィート未満とか、視程が3マイル未満とか。それから、山が広く雲にかくれていることもだよ。"],"12207d55":["cf1bb13df875.mp3","AIRMET タンゴは、並の乱気流、地上で30ノット以上の風が続くこと、そして雷雨と関係のない低い高度のウィンドシアを知らせるよ。"],"fdfdac11":["df29a8c7e19b.mp3","AIRMET ズールーは、並の着氷と、予想される氷点の高度を知らせるよ。"],"773b6247":["86769e5f2209.mp3","PIREP は、飛行中に実際に出会った天気の報告。予報だけでは分からないすき間をうめてくれて、乱気流、着氷、雲の頂上の報告は特に役に立つよ。"],"2e87ea3b":["c4b766c664fa.mp3","北半球では、高気圧の風は時計回りに外へ吹き出して、低気圧の風は反時計回りに内側へ吹きこむの。"],"b14198b9":["61f1c85532a5.mp3","尾流雲、ヴァーガは、雲の底から筋みたいに見える降水が、地面に届く前に蒸発するもの。その下では、突風や不規則な風、乱気流があることもあるよ。"],"1ec1889f":["3d77e17ae15c.mp3","逆転層は、ふつうとは逆に、高くなるほど気温が上がる層のこと。水分、煙、もやを地表近くに閉じこめて、視程を悪くすることが多いよ。"],"f7fd6859":["6a49501ea8c0.mp3","強い風が山の尾根を越えて吹くと、風下に波のような流れができるの。激しい乱気流や、強い上昇気流と下降気流が起きて、特徴的なレンズ雲ができることもあるよ。"],"4a288e81":["a4ee93b7f27b.mp3","停滞前線は、二つの気団の境目が進まなくなったもの。また動き出すまで、その場所にそって曇りや雨が長く続くことが多いよ。"],"4cec2e1f":["279766f1b255.mp3","閉塞前線は、速い寒冷前線が遅い温暖前線に追いついてできるの。暖かい空気が、二つの冷たい空気の間で地面から持ち上げられるんだよ。"],"204c49ff":["502f0ade2352.mp3","リフティッド・インデックスみたいな安定指数は、大気の不安定さを数字で表すの。雷雨ができる可能性や、どれくらい激しくなりそうかを判断するのに役立つよ。"],"6727e806":["86dff54940f9.mp3","マイクロバーストは、局地的な強い下降気流で、ほとんどは雷雨と一緒に起きるの。でも、雲底の高い対流雲から出るヴァーガでも起きることがあるよ。"],"caa64977":["e90f7d5e567e.mp3","シーリング、雲高は、ブロークンかオーバーキャストと報告された一番低い雲の層の、地上からの高さ。または、視界をさえぎるものの中への鉛直視程のことだよ。晴れやスキャッタードの層はふくまないの。"],"28e578dc":["e438733fffee.mp3","安定した空気、特に逆転層の下では、上下に混ざりにくいから、もや、煙、ちりが地表近くにたまって、視程が悪くなるよ。"],"7c7fd736":["c30abfd7217f.mp3","SIGMET は、すべての種類の航空機にとって危険な天気を知らせるの。激しい乱気流、激しい着氷、広い範囲の砂ぼこりや砂嵐、火山灰だよ。AIRMET は、主に小さな機体にとって大事な状態を知らせるの。"],"2455771b":["a38b655dc73d.mp3","標準の気象ブリーフィングには、今の天気、予報、関係する NOTAM、そして予定のルートと高度にかかわる AIRMET や SIGMET などの情報がふくまれるよ。"],"e4ac0d67":["abb91c9e70e6.mp3","空気力学。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"0d0026c5":["f719aa45ce02.mp3","まっすぐ水平に、加速しないで飛んでいるときは、揚力と重力、推力と抗力がつり合っているの。この四つが、飛行機にはたらく基本の力だよ。"],"9e1cd3bc":["81ede27f09cf.mp3","迎え角は、翼の翼弦線と相対風、つまり翼に対する空気の流れの向きとの間の角度だよ。"],"776aecdf":["30c565bacd15.mp3","失速は、翼の臨界迎え角を超えると起きるの。どんな速度でも、どんな姿勢でも起きるよ。急旋回中なら、速い速度でも失速するんだ。"],"95bc442d":["5b3452c23d18.mp3","水平旋回でバンク角を大きくすると、荷重倍数が増えて、実際の失速速度が上がるよ。"],"a72f367f":["c742fe1bc233.mp3","旋回では、翼を上げるために下がった補助翼のほうが、上がった補助翼より誘導抗力が大きくなるの。だから機首が旋回と反対に向いてしまう。協調したラダー操作で、これを打ち消すよ。"],"cad82545":["7cf8fec79992.mp3","P ファクターは、下がっていくプロペラのブレードの迎え角が大きくなって、上がっていくブレードより推力が大きくなることで起きるの。高出力で迎え角が大きいときに一番強く出るよ。"],"8455bd43":["443648a55730.mp3","ニュートンの第三法則で、機体はプロペラの回転と反対向きにロールしようとするの。ふつうの時計回りのプロペラなら、機体は左にロールして、左に向こうとするよ。"],"8b3c5ba5":["63d39d8e2a73.mp3","地面から翼幅一つ分くらいの高さを飛ぶと、翼端渦と誘導抗力が小さくなるの。だから、地面効果の外より遅い速度で飛べたり、ふわっと浮き続けたりするよ。"],"bf898c8a":["b563d3ae0ac8.mp3","VFE は、構造をいためずにフラップを出したり使ったりできる最大の速度。速度計の白い弧の、上の端で示されるよ。"],"add5a883":["2903b723160f.mp3","重心が前にあるほど、縦の安定は増えるけど、引き起こしや機首上げにもっと昇降舵が必要になって、失速速度も少し上がるの。重心がうしろすぎると安定が減って、失速からの回復がむずかしくなることがあるよ。"],"8a48af1b":["1bdf208384df.mp3","補助翼は縦軸まわりのロール、昇降舵は横軸まわりのピッチ、方向舵は垂直軸まわりのヨーを操作するよ。"],"c1c965fa":["6ab2de947a70.mp3","今の揚力の説明では、ふつう二つを挙げるの。流れの速さの違いで圧力の差が生まれるベルヌーイの定理と、翼が空気を下に押し下げるニュートンの第三法則。どちらも揚力を生むのに役立っているよ。"],"6886fccf":["b45360faf9da.mp3","誘導抗力は、低速で迎え角が大きいときに一番大きくて、速度が上がると小さくなるの。有害抗力とは逆の傾向だよ。"],"80214950":["3b5c4198f8bf.mp3","有害抗力は速度が上がるほど増えて、だいたい速度の二乗に比例するの。誘導抗力とは逆だね。全体の抗力は二つを足したもので、揚抗比が一番いい速度で最小になるよ。"],"46e6b844":["0e1ebfc8d5f1.mp3","後方乱気流が一番強いのは、重くて、ゆっくり飛んでいて、脚とフラップを上げたクリーンな形の機体のうしろ。必要な揚力のために迎え角が大きくなって、渦が強くなるからだよ。"],"75c68f2e":["3608f19bc04f.mp3","前を行く大きな機体の飛行経路と同じか、それより上を飛んで、その接地点より先に着陸しよう。そうすれば、沈んでいく翼端渦をさけられるよ。"],"eb2c3bc2":["bf79690e93b4.mp3","ウォッシュアウトがあると、翼端より先に翼の付け根が臨界迎え角に達して失速するの。だから補助翼が効き続けて、失速がおだやかになるよ。"],"95f196e2":["7e1762b52ce1.mp3","上反角は横の安定を増やすの。横すべりすると、下がった翼の迎え角が大きくなって揚力が増えて、機体を水平に戻そうとするんだよ。"],"7f5e1889":["d7adc30035cd.mp3","スリップは、バンク角に対して旋回率が遅すぎるときに起きて、ボールは旋回の内側にずれるの。スキッドは旋回率が速すぎるときで、ボールは外側にずれる。どちらも協調していない飛行だよ。"],"06042d59":["d686d25a5005.mp3","荷重倍数はバンク角とともに増えるの。60度バンクの水平旋回ではおよそ2G になって、失速速度もおよそ40パーセント上がるよ。"],"dfca3981":["f3bf1c582ca5.mp3","加速失速は、ふつうの失速速度より速い速度で臨界迎え角を超えると起きるの。急旋回や急な引き起こしで、荷重倍数が増えたときが多いよ。"],"e7af5c7b":["162167b98cb8.mp3","スパイラル不安定のある飛行機は、少しのバンクを放っておくと、だんだんバンクが深くなっていくの。直さないと、速度がどんどん上がる急降下のスパイラルになることも。うっかり IMC に入ったときは特に危険だよ。"],"6436a124":["a49ab5cdc0b3.mp3","正の静安定は、乱されたあと、最初に元のトリムの状態に戻ろうとする性質のこと。ほとんどの練習機にあえて作りこまれている、うれしい特徴だよ。"],"434efea0":["70da8836aeea.mp3","迎え角が大きくなると、空気の力がまとまってはたらく点、圧力中心は、ふつうの翼型ではだいたい前に動くの。失速するまでね。"],"2c680a35":["febadfaee128.mp3","揚力は、ほかの要素とならんで、速度の二乗に比例するの。だから迎え角やほかの条件が同じなら、速度を二倍にすると、揚力はおよそ四倍になるよ。"],"35639e6a":["8e16d9dfec52.mp3","キャンバーは、翼型の上面と下面の曲がり具合のこと。キャンバーのある翼型は、同じ迎え角なら、ふつう対称翼より大きな揚力を生むよ。"],"a92bf1c2":["5adbd53dcb78.mp3","旋回の方向に協調したラダーを踏むと、補助翼の抗力の差で生まれるアドバースヨーを打ち消して、旋回の入りがきれいに協調するよ。"],"6b6e65f2":["ecb3c23ce422.mp3","同じ滑空の形なら、滑空比は重さにあまり左右されないの。でも重い飛行機は、同じ滑空比を出すのにもっと速く飛ぶ必要があって、降下率も大きくなるよ。"],"67774364":["2399c63b51d2.mp3","対称翼は、上と下が鏡みたいに同じ形だから、迎え角0度では揚力が出ないの。キャンバーのある翼は、0度や少しマイナスの迎え角でも揚力を出せるよ。"],"8e81f882":["b68b3c43a23a.mp3","アスペクト比は、翼幅と平均翼弦の比。グライダーみたいに細長くて高いアスペクト比の翼は、ふつう低いアスペクト比の翼より効率がいいよ。"],"ebe76e7e":["55facacc77f3.mp3","迎え角が臨界迎え角に近づくと、翼の上面の境界層の流れが表面からはがれやすくなるの。なめらかな流れがくずれて、揚力が失われ、失速につながるよ。"],"bce4ff06":["5949dd32a066.mp3","トリムは目標の速度を決めるもの。トリムをとり直さずにパワーを下げると、安定した飛行機はその速度を保とうとして降下するの。パワーがくれていたエネルギーの代わりに、高度を使うんだよ。"],"2130c00e":["2c9c6b7d11d0.mp3","航空機のシステム。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"1534379d":["398bbfe1dfd6.mp3","キャブレターアイスは、華氏20度から70度くらいの、わりとおだやかでしめった日にもできるの。ベンチュリの効果と燃料の気化で、キャブレターの中がぐっと冷えるからだよ。"],"8fd20175":["56cbdbbe33f6.mp3","マグネトーの点火系が二つあると、一つが故障しても大丈夫。それに、一つのシリンダーで二本の点火プラグを使うから、燃焼の効率も良くなるよ。"],"b68fd7f9":["2cd658c83e84.mp3","燃料噴射式にはキャブレターのベンチュリがないから、フロート式のキャブレターみたいな吸気系の着氷はずっと起きにくいの。まれに着氷することもあるけどね。"],"85c0014b":["2d29c35a91dc.mp3","ピトー静圧系は、ピトー圧、つまり動圧と、静圧を、速度計、高度計、昇降計に送っているよ。"],"eb9f92c6":["7c21c441d98a.mp3","昔ながらの姿勢指示器と方位指示器はジャイロ計器で、取り付け方によって、バキューム、つまり吸引の系統か、電気で動いているよ。"],"9bd8173b":["d4ae85a97593.mp3","フラップは翼のキャンバーと面積を実質的に増やして、同じ速度での揚力と抗力を増やすの。だから、もっとゆっくり、もっと急な角度で進入できるよ。"],"85488b6c":["e5ace4a3597b.mp3","トリムは、ほしい姿勢を保つための昇降舵の力を調整して、パイロットがずっと力を入れ続けなくていいようにしてくれるよ。"],"d5a31f5c":["b2e046fe5237.mp3","エンジンオイルは、動く部品をなめらかにして、熱を逃がすのを手伝うの。多くのエンジンでは、定速プロペラのガバナーみたいな油圧の部品も動かしているよ。"],"1980e6f3":["53690347b834.mp3","オルタネーター、または発電機は、エンジンが回っている間、機体のシステムに電気を送って、バッテリーを充電するの。エンジンが止まっているときや、オルタネーターが故障したときは、バッテリーだけが電気を送るよ。"],"faee04d4":["8cf979108ae6.mp3","バキュームポンプが故障すると、バキュームで動く姿勢指示器と方位指示器に影響が出るの。ピトー静圧の計器と、電気式の旋回計がついていればそれも、ふつうは影響を受けないよ。"],"3d457291":["76420fff7960.mp3","定速プロペラのガバナーは、パイロットが選んだ回転数を保つように、ブレードのピッチを自動で変えるの。いろんな速度や出力で効率が良くなるよ。"],"89e5d64d":["b24cfcc7e3d8.mp3","固定ピッチプロペラはブレードの角度を飛行中に変えられないから、一番効率がいいのは一つの速度と回転数の組み合わせだけ。ふつうは上昇か巡航のどちらかに合わせてあるよ。"],"803b7190":["dcd3814646df.mp3","高度が上がると、空気の密度が下がるの。リーンにしないと、同じ量の燃料が少ない空気と混ざって濃すぎる混合気になるから、リーンにして燃料と空気の比率を正しく戻すんだよ。"],"828c8935":["5baab1bb09ba.mp3","デトネーションは、燃料と空気の混合気が、異常に爆発的に、制御されずに燃えること。ものすごい熱と圧力でピストンなどをいためることがあるの。混合気が薄すぎる、マニホールド圧が高すぎる、オクタン価の低い燃料、などが原因になるよ。"],"2b7d5e19":["b16bc0c8fef9.mp3","ショッククーリングは、急にパワーを下げたときみたいに、エンジンの温度が急に下がりすぎると起きるの。特に降下中は、パワーをゆっくり変えてさけるようにしよう。"],"69f8edc8":["b60ced7b434f.mp3","スタティックウィックは、機体にたまった静電気をなめらかに空気中へ逃がすの。無線や航法の機器のじゃまになる雑音を減らしてくれるよ。"],"681d7c69":["fce9cc99af89.mp3","前輪のある三輪式の脚は、ふつう尾輪式より機首の上の見晴らしが良くて、地上での扱いもやさしいの。尾輪式は、特に横風のとき、つんのめったり、グラウンドループしたりしやすいよ。"],"6cb3e2ab":["64af3b2fe875.mp3","多くの高翼機では、翼の燃料タンクがエンジンより上にあるから、重力でキャブレターや燃料噴射系に燃料を送れるの。予備としてポンプがついていることも多いよ。"],"e4969c0f":["569e67693f78.mp3","カウルフラップは、エンジンルームを通る空気の量を調整するの。開けると冷却が増えて、上昇中や地上で役に立つよ。閉じると巡航中の抗力が減るの。"],"05b0446c":["a5003b2bcc5c.mp3","ウェットウイングでは、翼の中の構造そのものを密閉して、燃料タンクとして使うの。翼の中に別のゴムのタンクや硬いタンクを入れるのとは違うよ。"],"b38fcaca":["fa2c2eefdd29.mp3","電流計やロードメーターは、システムの電流の流れを表示するの。オルタネーターがちゃんとバッテリーを充電しているか、バッテリーが放電していないかを確かめられるよ。"],"c4977ab0":["f8b6bcf691d7.mp3","サーキットブレーカーとヒューズは、電流が安全な量を超えたら回路を切って、電気の回路や部品を守るよ。"],"344daa00":["efc7a3db7aff.mp3","ランナップでは、BOTH がふつうの状態。少しだけ L か R に切り替えて、マグネトーを一つずつ確かめるの。予想どおりの少しの回転数の低下があれば、両方の点火系が動いている証拠。下がりすぎたり、止まりそうになったりしたら問題ありだよ。"],"afd7cb75":["cd1970e453a4.mp3","油温と油圧を見ていると、潤滑の不足、オーバーヒート、機械のトラブルみたいなエンジンの問題を、大きくなる前に早めに見つけられるよ。"],"be00bac9":["0d8d9040d5b6.mp3","ミクスチャーは、エンジンに送る燃料と空気の比率を調整するの。高度が上がって空気が薄くなったらリーンにして、効率よく燃えるようにするよ。"],"0963d368":["a3f87c0e633d.mp3","アナンシエーターパネルや警告灯は、システムの特定の異常を知らせて、問題が大きくなる前に早めに気づかせてくれるよ。"],"6c2cd29a":["c87df35a3985.mp3","燃料セレクターバルブで、どのタンクからエンジンに燃料を送るか選べるの。燃料の管理と、左右のバランスを保つのに大事だよ。"],"372e98b7":["6005ed8cc7fd.mp3","性能と重量重心。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"3b7aea6d":["b1985c098667.mp3","密度高度が高いと、エンジンの出力、プロペラの推力、翼の揚力がぜんぶ減るの。だから離陸滑走が長くなって、上昇性能も落ちるよ。"],"13283b35":["8bf2681db9ae.mp3","重心は、その飛行機の実際の重さに対して、POH や AFM に書かれた前とうしろの限界の中に収まっていなければいけないよ。"],"c6fb0fc2":["7906941d63f7.mp3","有効搭載量は、最大許容重量から基本空虚重量を引いたもの。パイロット、乗客、荷物、使える燃料がふくまれるよ。"],"3564443b":["1040b335bc12.mp3","基本空虚重量には、機体、エンジン、固定された装備、使えない燃料、エンジンオイルみたいな満タンの作動液がふくまれるの。使える燃料と積み荷はふくまないよ。"],"74ab2878":["d6b9db672135.mp3","空気が薄いと、エンジンの力が減って、プロペラと翼の効率も下がるの。だから密度高度が高いと、上昇率も上昇角も小さくなるよ。"],"ce6b4480":["1f7a4559ed4d.mp3","標準大気では、海面の状態を29.92インチ水銀柱、15度、華氏59度と決めているよ。"],"e9a49c48":["869b3270bb30.mp3","気圧高度は、高度計のコールスマン窓を標準の29.92インチに合わせたときに、そのまま読める高度だよ。"],"d63b6be4":["464cc2a9bd3a.mp3","向かい風の成分があると、同じ対気速度でも対地速度が小さくなるの。だから浮き上がる速度までの滑走距離と全体の距離が短くなるよ。"],"45d88ccc":["29aebead3acd.mp3","短い滑走路からの離陸では、ふつう最大のパワーをかけて、POH がすすめるフラップと速度を使うの。障害物を越えるために、最良上昇角速度の VX を使うことが多いよ。"],"847582f6":["d6b67a2e2055.mp3","重い飛行機は、飛び続けるのにもっと揚力が必要で、同じ迎え角ならもっと速度がいるの。だから失速速度は重さとともに上がるよ。"],"6612a9cb":["3612602a23db.mp3","離陸、着陸、上昇の性能表は、ふつう気圧高度、気温、機体の重さ、風の成分を考えに入れるの。どれも性能に影響するからね。"],"23cbc0ba":["551143988f87.mp3","下り坂の滑走路では、離陸のときは加速を助けるから滑走が短くなるけど、着陸のときは減速のじゃまになって滑走が長くなるの。上り坂はその逆だよ。"],"c6245608":["2cd59e4f5d8a.mp3","芝生みたいなやわらかい、でこぼこの地面は、転がる抵抗が大きいから、舗装されたなめらかな滑走路より離陸滑走が長くなるよ。"],"f7c6c3ae":["5ca614f4fcee.mp3","最大総重量は、その航空機が安全に運航できると認められた一番重い重さ。メーカーが決めて、POH や AFM に制限として書いてあるよ。"],"3fcdfeb3":["8c23385fae63.mp3","モーメントは、基準点のまわりで重さが生む回す力のこと。重いものほど、基準点から遠いものほど、モーメントが大きくなって、重心を大きく動かすよ。"],"2b86d6ce":["7beebb828b5b.mp3","実用上昇限度は、最大の上昇率が毎分100フィートまで落ちる密度高度。絶対上昇限度は、上昇率が0になる高度だよ。"],"974ccbb8":["5f3abe7ec7b7.mp3","真対気速度は、較正対気速度を、標準じゃない気圧と気温で補正したもの。高度が上がって空気が薄くなるほど、真対気速度は指示や較正の速度よりどんどん大きくなるよ。"],"6a0126f8":["f6e1eba7df13.mp3","VY、最良上昇率速度は、一定の時間で一番高く上がれる速度。VX、最良上昇角速度は、一定の水平距離で一番高く上がれる速度で、障害物を越えるのに便利だよ。"],"697904d7":["af8f996b2d43.mp3","VX はふつう VY より遅い速度で、一番短い水平距離で一番高く上がるために選ぶの。障害物の上を上昇していくときに大事だよ。"],"b90401be":["3172f2576e51.mp3","内挿は、表にある二つの値の間の値を、比例で見積もること。一番近い値に丸めるだけじゃないよ。"],"cd2de9cb":["34967f4fff64.mp3","上昇性能は、その条件で POH がすすめる正しい上昇速度で飛ぶことに大きく左右されるの。遅すぎても速すぎても、上昇性能は落ちちゃうよ。"],"90cd75f4":["90e90bb78f5c.mp3","上昇率は、航空機が高度を上げていく垂直方向の速さで、ふつう毎分何フィートで表すよ。"],"0433c575":["5fcee09c01d7.mp3","有効搭載量には、乗っている人、荷物、貨物の重さに加えて、使える燃料もふくまれるの。ペイロードはもっとせまくて、燃料をのぞいた、乗客や貨物みたいな収入になる重さのことだよ。"],"13e98177":["a6b16d5360a4.mp3","重心がうしろにあると縦の安定が減って、ピッチが揺れやすくなることがあるの。機首を下げる力が少ないから、失速からの回復もむずかしくなるよ。"],"333418a0":["0d96728137f4.mp3","公表されている性能の数字は、ふつう整備が完ぺきな新しい機体を、腕のいいテストパイロットが正確な技術で飛ばして出したものなの。ふつうのパイロットと中古の機体では、少し悪くなることが多いから、慎重なパイロットは安全の余裕を足すよ。"],"5f900296":["8bf371eeb923.mp3","楽観的な想定じゃなくて、報告された風、気温、気圧みたいな今の実際の条件を使うと、もっと現実的で安全な性能の見積もりができるよ。"],"d6231834":["a7fb0ed887a7.mp3","公表された性能は、理想に近いテストの条件で出したものが多いから、慎重なパイロットは、公表された最小の距離ぎりぎりで計画しないで、離着陸の距離に安全の余裕を足すよ。"],"26b3508c":["9cc534051261.mp3","航法。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"b4c773bf":["f2e7df77cae0.mp3","セクショナルチャートの縮尺は50万分の1。1インチがおよそ6.86海里だよ。"],"de113521":["d5877a0ef329.mp3","VOR のラジアルは、局から外へ向かって測る磁方位のコース。1度ごとに一本で、360本あるよ。"],"32be2eea":["e99c36b6de89.mp3","TO と FROM の表示は、選んだコースを飛ぶと、局に向かうのか、局から離れるのかを教えてくれるだけ。機首の方向や、実際の航跡を直接示すわけじゃないの。"],"4f9e1698":["1c44a01c5692.mp3","偏差は、真北と磁北の角度の差で、場所によって変わるの。自差は、機体そのものの磁気で起きるコンパスの誤差だよ。"],"b6098cf4":["5f6bc5bab06e.mp3","真コースを風で補正すると真ヘディング。偏差を足すか引くと磁ヘディング。それを自差カードで補正すると、飛ぶべきコンパスヘディングになるよ。"],"49ec1eac":["265e34ca6cb0.mp3","地文航法は、地上の目印をチャートと目で見比べて飛ぶ方法。推測航法は、計算したヘディング、時間、速度、風をもとにする方法だよ。"],"fe020218":["78e3f8974c4d.mp3","WAAS は GPS の信号を補強して、精度を上げて、信頼性の監視もしてくれるの。だから、LPV 進入みたいな、垂直のガイダンスつきの GPS 進入ができるようになるよ。"],"1ad43ef6":["d78198d70506.mp3","白と緑が交互に光るのは、照明のある民間の陸上空港。白と黄色なら水上空港みたいに、ほかの組み合わせはほかの種類の施設を表すよ。"],"52d7c7f1":["0a9f7e5a71ad.mp3","UTC、ズールー時間という一つの基準の時刻を使うと、違う時間帯にいるパイロットや管制官が、予定や時刻について話すときに混乱しないですむの。"],"b39fad7c":["ebb5e50a8a67.mp3","風修正角は、コースに足したり引いたりして、風で流されても、地上でねらいのコースをたどるために飛ぶヘディングを決めるものだよ。"],"babddd7e":["6bf920563907.mp3","セクショナルチャートで、青い空港マークは管制塔のある空港、マゼンタは管制塔のない空港だよ。"],"6efeb916":["1f489e5c4434.mp3","セクショナルチャートでは、障害物の平均海面からの高さが太い数字で、地面からの高さは小さな数字で、かっこの中に書いてあることが多いよ。"],"1fb28b6e":["8283a250d9a5.mp3","FAA のガイダンスでは、VOT や地上のチェックポイントでの確認は、ふつうプラスマイナス4度までの誤差が認められているよ。"],"f9d00f61":["43ac45548c2d.mp3","DME は、航空機と地上局の間の斜めの距離を測るの。ふつう対地速度や、局までの時間も表示してくれるよ。"],"a7f48a69":["91a4106ed61a.mp3","ADF の針は、合わせた NDB 局の相対方位を指すの。機体のヘディングと組み合わせると、局への、または局からの磁方位が分かるよ。"],"28bb7ce6":["783aeea6cf78.mp3","RAIM は、余分な衛星の情報を使って、GPS の位置が信頼できるか確かめるの。航法に使えない信号の質なら、パイロットに警告してくれるよ。"],"40c45b81":["c4cc2293322a.mp3","地文航法のチェックポイントは、高いところからでも分かりやすくて、近くの似たものとまちがえにくい、目立つ特別な目印がいいよ。"],"b9349c82":["1d152d25eac8.mp3","VFR の飛行計画は、到着予定から適当な時間がたっても閉じられないと、フライトサービスが捜索救助を始めるの。これが飛行計画を出す大きな安全のメリットだよ。"],"9447bad4":["87012041b8ab.mp3","CDI の針は左右に振れて、選んだ VOR のコースやラジアルに対して、機体がどこにいるかを表すの。機体のヘディングを直接表しているわけじゃないよ。"],"a75f9b75":["7dce4217894d.mp3","等偏差線は、磁気偏差が同じ地点を結んだ線。無偏差線は、偏差が0、つまり真北と磁北が重なる地点を結んだ線だよ。"],"7bb2a099":["93dd9fe93596.mp3","ナビゲーションログは、ルートをチェックポイントの間の区間に分けて、区間ごとに予定のヘディング、距離、対地速度、所要時間、燃料の消費を書くの。推測航法の支えになって、地文航法とも照らし合わせられるよ。"],"7b9f2fff":["5f6ed4454189.mp3","電子機器は故障したり、電源や衛星の信号を失ったりすることがあるの。だから地文航法と推測航法は、大事な予備の技術で、全体の位置の感覚も強くしてくれるよ。"],"baf2a745":["bd86d1ebf611.mp3","VFR では必ずしも厳密な規則の最低限じゃないけど、山の上では、一番高い地形や障害物より、1000から2000フィートくらい上を飛ぶのがよくすすめられるの。下降気流、乱気流、緊急時の選択肢のためだよ。"],"30eb29d0":["757378ab74cd.mp3","チャートの凡例を見直すと、記号を正しく読めるの。記号は忘れやすいし、版が変わるときに更新されることもあるからね。"],"456ab68b":["a8696b57b7a5.mp3","大圏コースは、球の上の二点を結ぶ一番短い道。長距離の航法で大事だけど、ふつうは飛んでいる間ずっとヘディングを変え続ける必要があるよ。"],"b1f977e8":["b75b61b07665.mp3","航程線、ラームラインは、ルートの間ずっと同じコンパスヘディングを保つ道。飛ぶのはかんたんだけど、特に長距離では、ふつう大圏コースより長くなるよ。"],"f421d19b":["aa7605376f30.mp3","チェックポイントは、飛行の進み具合をこまめに確かめて、航法のまちがいを早く見つけられるくらいの間隔にしよう。でも、多すぎて操縦のじゃまになるほどにはしないでね。"],"9c67892b":["ec8784a42a6f.mp3","時間、速度、距離の計算で、距離と対地速度から所要時間を見積もれるの。推測航法の基本の技術だよ。"],"731bd3a3":["f6d5405a88d4.mp3","風修正角は、風で流される分を打ち消すようにヘディングをコースからずらすの。そうすれば、風があっても実際の航跡がねらいのコースをたどるよ。"],"2c489aea":["a60e74571b5b.mp3","2021年から、FAA のセクショナルチャートとターミナルエリアチャートは56日ごとに改訂されているの。飛ぶ前に、最新の版を使っているか確認してね。"],"8f02924e":["aba8f25053af.mp3","グラウンドトラックは、機体が地上を実際に進んだ道すじ。風で流されると、空気の中でのヘディングとは違ってくるの。コースは予定の航跡、トラックは実際の結果の道すじだよ。"],"3cfe3fd3":["834817284f5f.mp3","ヒューマンファクター。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"c8dc6375":["a9fc739cadfb.mp3","低酸素症は、まず変に気分が良くなったり、判断力が落ちたりすることが多いの。そのあと、チアノーゼ、そして最後は意識を失うような、もっと重い症状が出てくるよ。"],"f6a9e2b1":["d0e455984d44.mp3","過換気は、体に必要な以上に速く深く呼吸して、血液の二酸化炭素が減ることで起きるの。めまいやしびれみたいに、低酸素症と似た症状が出るよ。"],"3e64f650":["2e53e1afbed4.mp3","外の目で見える手がかりがないと、内耳の動きを感じる器官が、姿勢や動きについてまちがった感覚を作ることがあるの。これが空間識失調につながるよ。"],"cbf6b009":["280dd8cda868.mp3","上手な見張りは、空をいくつかの区画に分けて、短い目の動きで一つずつ見て、それぞれで少し止まるの。目は動いている間はうまくピントが合わないから、ずっと流し見したり、一点を見つめたりしないでね。"],"00282a1f":["b35de0b0ff09.mp3","IMSAFE は、自分の体調を確かめるチェックリスト。病気、薬、ストレス、アルコール、疲れ、そして気持ちや食事だよ。"],"4f45c366":["2d242daa90cc.mp3","一酸化炭素は、こわれた排気管や、キャビンヒーターに熱を送る熱交換器から、客室に入ってくることがあるの。だから一酸化炭素の検知器がすすめられているよ。"],"025f3acf":["5a2f7bf09e25.mp3","疲れは、反応の速さ、注意力、判断力、そして決断する力を落とすの。どれも安全な飛行にとって、とても大事なものだよ。"],"0446b835":["64bc15763a9a.mp3","PAVE は、リスクを四つに分けて考える方法。パイロット、機体、環境、そして外からのプレッシャー。飛行全体のリスクを順序だてて見積もれるよ。"],"503bb586":["330876a69ae3.mp3","14 CFR 91.17 では、お酒を飲んでから8時間以内、酔っている間、または血中アルコール濃度が0.04以上のときは、乗員として乗ってはいけないの。"],"5f8f2672":["c6b95e605542.mp3","夜は、目の中心のくぼみ、中心窩の外にある桿体細胞のほうが、中心に集まっている錐体細胞より暗い光に敏感なの。だから少しだけ中心をずらして見ると、夜に物を見つけやすくなるよ。"],"16260a1c":["bec8ed64e9d0.mp3","見るものが何もない視界では、目は近い距離にピントが合ったまま、ゆるんでしまうの。これを空虚視野近視って呼ぶよ。遠くの機体を見つけにくくなるんだ。"],"99399206":["9a07ae36ed38.mp3","オートキネシスは、暗いところで止まっている光をじっと見つめていると、数秒後にその光が勝手に動いているように見える現象。夜の空間識失調の原因になることがあるよ。"],"0cb67757":["c9060785a1eb.mp3","偽の水平線の錯覚は、かたむいた雲の層や、地上の光の並び方みたいなものを、本当の水平線だと思って機体を合わせてしまうこと。おかしな姿勢になってしまうことがあるよ。"],"4ebcc64b":["1e38a02c4914.mp3","いつもより幅のせまい滑走路は、実際より高くにいるような錯覚を起こすの。だから、いつもより低く進入してしまって、強い接地や手前への着陸につながることがあるよ。"],"5112b690":["f98012adc789.mp3","ブラックホール錯覚は、夜に、滑走路のまわりに明かりがほとんどない、暗くて何もない地形の上を進入するときに起きるの。気づかないうちに、危ないほど低く進入してしまうことがあるよ。"],"c06927e0":["84f481e385d6.mp3","ガイダンスでは、浮上の調整がいらないダイビングのあとは、8000フィートまでの飛行の前に少なくとも12時間待つようにすすめているの。調整が必要なダイビングのあとは、もっと長く待ってね。減圧症のリスクを下げるためだよ。"],"e673f05a":["71707597cc26.mp3","五つの危険な態度は、反権威、衝動性、不死身、マッチョ、そしてあきらめ。自分の中のこれに気づくことが、航空の意思決定の訓練の大事なところだよ。"],"a4d134a0":["5c7676113e5d.mp3","よくあるリスクの見積もり方は、どれくらいひどい結果になりうるかの重大さと、どれくらい起きそうかの可能性、その両方を考えるの。そのリスクを受け入れていいか判断するのに役立つよ。"],"7a5616cf":["6232f5636ac2.mp3","脱水は、疲れ、頭痛、めまい、頭の働きの低下につながることがあるの。飛行中のほかの体の負担に、さらに上乗せされるよ。"],"4df0b6af":["24334406a085.mp3","有効意識時間は、高度が上がるほどぐっと短くなるの。薄い空気には、酸素が少ないからだよ。"],"acb76abc":["9d3878338549.mp3","低酸素症の一番危ないところは、進んでいく間にも判断力や自分を見る力が落ちて、ときには変に気分が良くなって、パイロットが問題に気づけなくなることなの。"],"58a74773":["10218ace0b31.mp3","パイロットは、飛ぶたびにその前に、自分が飛べる体調か確かめるように訓練されるの。病気、疲れ、ストレス、薬は、日によって変わるからね。"],"627f98f7":["ac95aa5fd47d.mp3","疲れると、反応が遅くなって、注意力や見張りが落ちて、判断や決断も悪くなるの。どれも飛行の安全をおびやかすよ。"],"8fb2da5f":["49517ac217f6.mp3","DECIDE モデルは、順序だてて決める方法を示しているの。とっさに反応するんじゃなくて、飛行中の判断を一つずつ整理して考えられるようにしてくれるよ。"],"4b095a4c":["cddc26963c3f.mp3","適度なストレスは集中力を高めてくれることもあるけど、強すぎるストレスは注意をせまくして、判断を悪くして、全体の決断と動きを落としてしまうの。"],"ed33b728":["7b1ca701da12.mp3","状況認識は、機体、環境、飛行のまわりの状況を、いつも正しくとらえて理解していること。気が散ったり、疲れたり、やることが多すぎたりすると、失われることがあるよ。"],"cbad4dfc":["ff3c1e83a22f.mp3","タスク飽和は、やることの数や複雑さが、パイロットがうまくこなせる量を超えてしまうこと。大事なことを忘れたり、うまくできなかったりする原因になるよ。"],"e65bb4f2":["df6498059691.mp3","飛行計器。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"dab73723":["74350f5d75c2.mp3","18000フィート未満では、コールスマン窓にその地域の今の高度計規正値を合わせるの。18000フィート以上、クラス A 空域では、代わりに標準の29.92インチを使うよ。"],"7658e682":["fad14ef255e5.mp3","赤い線は VNE。構造がこわれる危険があるから、絶対にわざと超えてはいけない速度だよ。"],"a51491e5":["5f30fa292786.mp3","姿勢指示器はジャイロを使って、外が見えなくても、模型の水平線に対する機体のピッチとバンクを表示してくれるよ。"],"6d7abfac":["4e203954c465.mp3","ジャイロの歳差のせいで、方位指示器は時間がたつとずれてくるの。だからパイロットは、安定した加速していない飛行中に、ときどき磁気コンパスと見比べて合わせ直すよ。"],"057ba50f":["1a25aeb1abb9.mp3","旋回計、ターンコーディネーターのジャイロはかたむけて取り付けてあるから、ヨーだけじゃなくロールの速さにも反応するの。旋回に入るときや止めるときを、早めに教えてくれるよ。"],"2022d123":["bf35a516b667.mp3","昇降計は、計器のケースの中の調整された小さな穴を通して、静圧の変わる速さを感じとるの。だから、新しい上昇率や降下率を正しく表すまで、少し遅れがあるよ。"],"2860eb9d":["00b5145ce7a0.mp3","磁気の伏角のせいで、東か西のヘディングで加速すると、コンパスが一時的に北へ旋回したように見えて、減速すると南へ旋回したように見えるの。"],"33be453b":["44d348ceb0f7.mp3","ピトーヒーターは、ピトー管の入り口が凍らないようにして、速度計が正しい動圧を受け取り続けられるようにするよ。"],"774978d8":["96f82a8f09cc.mp3","ピトー静圧系は三つの計器につながっているから、静圧孔がつまると、速度計、高度計、昇降計がぜんぶまちがった値を示すの。だから多くの機体には、代わりの静圧源がついているよ。"],"f59c4f3a":["967e6e4bc392.mp3","7700 は、一般的な緊急事態のトランスポンダーコード。7600 は通信が途絶えたこと、7500 は不法な妨害、つまりハイジャックを表すよ。"],"0647cfcc":["bef6ee8dff4a.mp3","代わりの静圧源は、本当の外の静圧じゃなくて客室の気圧を拾うことが多いから、高度計、速度計、昇降計に少し誤差が出るの。その機体での補正の値は POH に書いてあるよ。"],"baf3ba7d":["1f3f4b92da91.mp3","暖かい空気からずっと冷たい空気へ、または高い気圧から低い気圧へ、高度計を合わせ直さずに飛ぶと、本当の高度は表示より低くなるの。地形や障害物の近くでは危ないよ。英語では、high to low、hot to cold、look out below、って覚えるの。"],"69fb26e8":["41e3f2656025.mp3","モード C は、モード A の基本の識別コードに、気圧高度を自動で知らせる機能を足したもの。ATC は声の報告なしで、レーダーで機体の高度が分かるよ。"],"adfcc2b9":["963bb0fc92fc.mp3","ADS-B アウトは、GPS で分かった機体の位置、高度、速度、識別の情報を発信するの。ATC の監視が良くなって、装備のあるほかの機体も周りの交通が分かるようになるよ。"],"dd040117":["96740ad0afc3.mp3","コンパス修正カードには、その機体ならではの自差の誤差が、ヘディングごとに書いてあるの。ほしい磁ヘディングにするために、正しいコンパスヘディングで飛べるよ。"],"a0d703d0":["b246782e045e.mp3","外気温計を見ると、キャブレターアイスの危険が分かるし、密度高度や真対気速度の計算にも使えるよ。"],"530b587f":["6013fe0f10ef.mp3","マニホールド圧力計は、吸気マニホールドの圧力を測るの。定速プロペラの機体では、回転数と一緒に、エンジンの出力を合わせたり見張ったりするのに使うよ。"],"261588bd":["1ed4cea50efe.mp3","ほとんどの失速警報装置は、翼の前縁近くのセンサーで、翼が臨界迎え角に近づいたときの空気の流れの変化を感じとるの。実際に失速する少し前に、音や光で知らせてくれるよ。"],"ce345e12":["2afb546b9365.mp3","ラムエアの入り口と水抜き穴の両方がつまると、ピトーの管の中の圧力が閉じこめられたままになるの。すると速度計は高度計みたいになって、実際の速度に関係なく、上昇すると高く、降下すると低く表示するよ。入り口だけがつまって水抜き穴が開いていれば、圧力がぬけて表示は0に向かって下がっていくの。"],"bb84e8b5":["01e331337fe7.mp3","グラスコックピットは、プライマリー・フライト・ディスプレイやマルチファンクション・ディスプレイと呼ばれる電子の画面で、飛行、エンジン、航法の情報をまとめてデジタルで表示するの。"],"7c46e19f":["c47de32c50b2.mp3","PFD は、ふつう姿勢指示器、速度計、高度計、方位指示器、昇降計、旋回計の役目を、一つの電子の画面にまとめているよ。"],"2a21ea07":["753cebdfa439.mp3","迎え角計は、翼の実際の迎え角を表示するの。失速は速度じゃなくて迎え角で決まるから、速度だけより、もっと直接に失速の近さを教えてくれるよ。"],"3c5b607d":["bb02012d775f.mp3","グラスコックピットの飛行機の多くは、予備の計器を残しているの。メインの画面が故障しても、基本の姿勢、速度、高度が分かるようにね。"],"5596d314":["e3be5c06723e.mp3","高い気圧から低い気圧へ、高度計を合わせ直さずに飛ぶと、高度計は本当の高度より高く表示するの。計器がまだ高い気圧の設定を基準にしているからだよ。high to low、look out below、って覚えてね。"],"584058e6":["b2fb44f3b498.mp3","方位指示器が故障したら、磁気コンパスが一番のヘディングの情報源になるの。旋回中や加速、減速のときの誤差があることは覚えておいてね。"],"19839caf":["b34aff6e905f.mp3","失速は臨界迎え角を超えると起きて、急旋回中の加速失速みたいに、どんな速度でも起きるの。だから迎え角を直接表示してくれると、速度だけより信頼できる失速の警告になるよ。"],"1e5ebb12":["d3b460c18695.mp3","ラグ、遅れは、急な上昇や降下みたいな実際の変化と、計器の表示が変わるまでの短い時間差のこと。特に高度計や昇降計みたいな、気圧を使う計器で起きるよ。"],"adcb47ee":["4f0435418bd3.mp3","通信と管制。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"13692b96":["d3e34f324d75.mp3","「セイ アゲイン」は、最後の送信をくり返してもらう決まった言い方。「ラジャー」は受け取ったという意味だけで、理解した、賛成した、という意味じゃないよ。"],"3b14926a":["61141853bb72.mp3","VFR で通信が途絶えたら、ふつうは 7600 をスコークして、管制塔の近くなら、光の信号やほかの指示のために、決められた周波数を聞き続けるの。そして、よく考えて安全に着陸するまで飛行を続けるよ。"],"385b649b":["ed18aa23a76b.mp3","CTAF は、管制塔のない空港で使う、共通のことが多い周波数。パイロットが自分の位置とこれからすることを、まわりの機体に知らせるのに使うよ。"],"a94f9d16":["d186830e026f.mp3","ATIS は、空港のいつもの情報を録音して、ずっと更新しながら流している放送。周波数が混まないように、ATC に連絡する前に聞いておいてね。"],"4bc4f752":["ecf762575f67.mp3","グラウンドコントロールは、空港の地上での地上走行を調整して許可するの。離陸や着陸の許可に使う管制塔の周波数とは別だよ。"],"838e3fb7":["ae40a57dfb07.mp3","地上の機体に向けた緑の光の点灯は、地上走行してよし。飛んでいる機体に向けた緑の点灯は、着陸してよし、だよ。"],"5f52e1c1":["96e847f27467.mp3","フライトフォローイングは、保証のない追加のサービス。管制官の手があいているときに、VFR の機体に周りの交通の情報をくれるの。"],"dfa0267a":["8132bd8d4e03.mp3","121.5 メガヘルツは、国際的な民間航空の緊急周波数。たくさんの ATC 施設が聞いていて、ELT の信号にも使われるよ。"],"30ee54a6":["0a511ab11cd1.mp3","トランスポンダーで 7700 をスコークすると、ATC のレーダー画面に警報が出て、声で連絡できなくても、その機体が緊急事態だと分かるの。"],"37c9a26c":["32f6d548a47f.mp3","「ノベンバー」はアルファベットの N。数字の9を言うときは「ナイナー」を使うの。雑音の中で「ナイン」とまぎれないようにするためだよ。"],"9ab878da":["564e7cfefaa7.mp3","ふつうの自己通報では、空港の名前、機体の識別、そしてダウンウィンドに入る、ベース、ファイナル、みたいな位置やこれからすることを言って、最後にもう一度空港の名前を言うの。ほかのパイロットが状況をつかみやすくなるよ。"],"6a0a0b29":["bf1a26e09f1b.mp3","決められたボイドタイムまでに出発しなかったら、その許可は無効になるの。出発する前に、ATC に新しい許可をもらってね。"],"a5689abf":["55f08dedd0b6.mp3","「ライン アップ アンド ウェイト」は、滑走路に入って出発の位置に並んでいい、という許可。でも、別に離陸許可をもらうまでは離陸しちゃだめだよ。"],"91994145":["030cd7364560.mp3","よくすすめられる方法は、場周経路の高度で、ダウンウィンドに45度の角度で入ること。ほかの機体を見つけやすく、見つけてもらいやすくなるよ。"],"53dbbc81":["7bc8a700e3b9.mp3","フライトサービスステーションは、飛行前の気象ブリーフィングや、VFR 飛行計画の提出と終了みたいなサービスをしてくれるの。航空管制の間隔設定はしないよ。"],"3b83e46b":["b3e3db6c09c0.mp3","1-800-WX-BRIEF は、パイロットが気象ブリーフィングを受けたり、電話で飛行計画を出したりするために、フライトサービスにかける昔からの電話番号だよ。"],"0535b557":["d5bee4bec990.mp3","18000フィート未満では、AIM によると、千の位の数字を一つずつ言って、それに百の位を足すの。だから4500は「フォー サウザンド ファイブ ハンドレッド」、12500は「ワン ツー サウザンド ファイブ ハンドレッド」。「フォーティーファイブ ハンドレッド」はくだけた言い方ではよく使うけど、標準の形じゃないよ。"],"f3fc37d7":["017ab0322124.mp3","送信がかぶったり、よく分からなかったりしたら、欠けた指示を推測しないで、管制官にブロックされたと伝えるか、ただ「セイ アゲイン」と言おう。"],"414afe8a":["b1a1002fdd9a.mp3","「レーダー サービス ターミネイテッド」は、その区間ではもう ATC がレーダーのサービス、たとえば交通情報をくれない、という意味。レーダーの範囲や、ある空域から出るときによく言われるよ。"],"264d7032":["d4721991d9dc.mp3","「ラジャー」は、最後の送信を受け取った、という意味だけ。はいかいいえの質問の答えには使わないでね。賛成は「アファーマティブ」、従います、は「ウィルコ」だよ。"],"cafc676c":["a87e3147e797.mp3","「ウィルコ」は、will comply、従います、の短い形。メッセージを受け取って、理解して、その通りにする、という意味だよ。"],"db463189":["4d0ed9382b54.mp3","指示に従えないときは、すぐに ATC に「アンエイブル」と伝えて、できれば短く理由も言おう。そうすれば管制官が対応を調整できるよ。"],"e090cd95":["8845ce56f13f.mp3","ATIS の識別の文字は、放送が更新されるたびに変わるの。パイロットも管制官も、最新の情報を持っているかすぐに確認できるよ。"],"64bb25b1":["cb0163b59aec.mp3","送信する前に聞くと、ほかの送信と重なるのをさけられるの。二つの送信が重なると、どちらもはっきり聞こえないからね。混んでいる周波数や共通の周波数では特に大事だよ。"],"be5c3f01":["182717bafc23.mp3","パイロットは ATC の許可を復唱するのがふつう。特に、滑走路の指定、高度の制限、そのほかの安全に大事なことは、正しく受け取ったか確かめるために復唱してね。"],"a7f89a6b":["df74ccebd238.mp3","「スコーク」のあとに四けたのコードが続いたら、そのコードを機体のトランスポンダーに入れなさい、という指示。ATC がレーダーで機体を見分けられるようにするの。"],"64f4f9c7":["c8c9494358a2.mp3","無線が聞きとりにくいときは、まず相手にゆっくりはっきり話してもらう、大事な情報をくり返す、使えるなら聞きやすい周波数を試す、みたいなかんたんなことから始めよう。"],"99357313":["0d42234e089e.mp3","空港での運用。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"f72291f0":["c9ba05cb5208.mp3","滑走路の標識は、番号や滑走路の始まりの標示もふくめて、白くぬられているの。黄色は誘導路の標識用だよ。"],"743ce596":["4b0b8f2ae9e7.mp3","誘導路の中心線は、一本の続いた黄色い線。地上走行の道をたどりやすくしてくれるの。滑走路の中心線は、白い破線だよ。"],"e9fe6e88":["cb16dff3fd11.mp3","空港が右回りの場周経路を指定していなければ、標準の場周経路は左旋回だよ。右回りは、チャートや空港の標識でよく示されているの。"],"a8831dca":["526d306244f3.mp3","近づいてくる機体どうしでは、右側にいる機体が優先なの。もう一方がよけて、その上、下、前を通らないようにするよ。"],"c3326e65":["988f07026fb3.mp3","セグメントサークルは、場周経路の向きを示して、吹き流しや T の字と一緒に今の風向きを教えてくれるの。場周経路への入り方を計画するのに役立つよ。"],"21f9b44b":["3a9e7fb166cd.mp3","PAPI は、正しい進入角にいるときは白が二つ、赤が二つ。白が多いと高すぎ、赤が多いと低すぎだよ。"],"553beaa5":["954c6ee5e166.mp3","滑走路の二けたの番号は、だいたいの磁方位を10度単位に丸めて、最後の0を取ったもの。たとえば、270度くらいの向きなら滑走路27だよ。"],"39da87c7":["3aeceb5c8534.mp3","ずらした滑走路末端、ディスプレイスト・スレッショルドは、たいてい障害物のために着陸の始まりを奥にずらしたもの。その手前の舗装は、地上走行や、ときには離陸に使えることが多いよ。"],"d954d057":["f5e9727fbd37.mp3","122.9 メガヘルツのマルチコム周波数は、専用の CTAF がない空港で、パイロットが自分の位置と予定を知らせるのによく使われるよ。"],"752dd95c":["abbc1ada7fb3.mp3","管制塔のある空港では、使っているかどうかに関係なく、どの滑走路に入るにも横切るにも、ATC のはっきりした許可が必要なの。滑走路への誤進入を防ぐため、2010年からの FAA の方針だよ。"],"7a2cc57a":["bd3539f92ee8.mp3","赤地に白い文字の標識は、必ず従う指示を表すの。一番多いのは滑走路の停止位置の標識で、管制塔のある空港では、ATC のはっきりした許可なしに越えちゃだめだよ。"],"2aef789c":["63855879c949.mp3","黄色地に黒い文字の標識は、方向の標識。交差点から出ていく誘導路の名前を示したり、情報を伝えたりするよ。"],"4411537e":["0728ea36cc6f.mp3","黒地に黄色い文字の標識は、位置の標識。今いる誘導路や滑走路を確認できて、地上走行中に自分の位置を見失わないようにしてくれるよ。"],"a9fd4740":["5a0a783e8ebc.mp3","地上の機体に向けた赤の点滅は、使っている滑走路や着陸する場所から出なさい、という意味。そこで地上走行したり運用したりするのが危ないからだよ。"],"336312a0":["0d38e5ec7539.mp3","地上の機体に向けた白の点滅は、空港の出発した場所に戻りなさい、という指示だよ。"],"561188cb":["f07d13ca8d94.mp3","進入が不安定になったり、危なくなったり、滑走路があいていなかったりしたら、いつでもゴーアラウンドする準備をしておこう。危ない進入や着陸を最後まで続けないでね。"],"c39ac7f3":["fe954c03063c.mp3","ウイングロー方式では、風上の翼を下げて風に向かって少しバンクして、反対のラダーで機体の軸を滑走路の中心線に合わせたまま接地するの。"],"bb2baa7f":["7c91acd01fc1.mp3","標高が高くて密度高度の高い空港では、離陸距離が長くなって、上昇性能が落ちて、同じ指示対気速度でも真対気速度が速くなるの。だから対地速度も速くなって、着陸滑走も長くなるよ。"],"1dc00a5f":["886a7792e38b.mp3","滑走路の手前で止まる指示や、滑走路に関わるほかの許可は、ATC に復唱して正しく理解したか確認しよう。滑走路への誤進入を防ぐ大事な習慣だよ。"],"d75469f1":["83ca18c9ecd9.mp3","空港図のホットスポットは、滑走路への誤進入が起きたことがある場所、誘導路の形が分かりにくい場所、そのほかの安全の心配がある場所を示しているの。そこでは特に気をつけてね。"],"318d0a8f":["9dfdf5463c09.mp3","滑走路の縁の灯火は白。計器用の滑走路では、最後の2000フィート、または滑走路が短ければその半分が、着陸する方向から黄色に見えて、残りの滑走路が少ないことを知らせるよ。"],"379d02e9":["769e8883d8b5.mp3","誘導路の縁の灯火は青。夜や視界が悪いとき、白い縁の灯火の滑走路と区別できるようにしているの。"],"7383023a":["dcd93ca118e2.mp3","接地帯標識は、滑走路の始まりから500フィートごとにならんだ長方形の対のしるし。接地する範囲を示して、着陸のときの距離の目安になるよ。"],"49f9f960":["6fd8aba13a7a.mp3","ノンムーブメントエリアは、ふつうエプロンや駐機場のことで、ATC が直接管理していない場所。特別な地上走行の許可なしで動けるけど、気をつけて、地元の手順に従ってね。"],"28f9d7e6":["3f45dfdc3bc3.mp3","ホールドショートラインは、正しい許可や確認なしに越えてはいけない場所を示す線。実線が止まる側のパイロットのほうを向いていて、破線は滑走路側にあるよ。"],"c5abf382":["5f74eee58e69.mp3","ILS クリティカルエリアは、ローカライザーとグライドスロープの電波を守る場所。電波を乱さないように、特に視界が悪い中で計器進入しているときは、機体も車も近づかないようにするよ。"],"f5bb90c3":["fa82687fe14e.mp3","FBO、フィックスト・ベース・オペレーターは、空港でパイロットや機体の持ち主にサービスをする会社。給油、駐機、格納庫、ときには飛行訓練や整備もしてくれるよ。"],"6d314dcd":["f06b7f851bdc.mp3","緊急時の手順。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"ab5649bc":["3f8b628f88b7.mp3","エンジンが止まったあと、低い高度で滑走路に引き返そうとするのは、インポッシブルターンと呼ばれて、失速につながることが多いの。十分な高度と練習した技術がなければ、操縦を保って、だいたい前方に着陸するのが安全な基本だよ。"],"1141ad9f":["d4d3336cdd7d.mp3","飛行中のエンジン火災のチェックリストでは、ふつう燃料を止めるの。燃料セレクターをオフ、ミクスチャーをアイドルカットオフ。それから、煙を客室に引きこむかもしれないキャビンヒートと換気を閉じて、不時着の準備をするよ。"],"9785494f":["d94e16932d6b.mp3","電気火災の手順では、ふつうマスタースイッチを切って電気を止めて、チェックリストに従って問題の装置を切り離すの。必要なら、そのあと大事なシステムだけを戻してみるよ。"],"193c40b8":["df97f6ab9735.mp3","最良滑空速度は、失う高度に対して一番遠くまで進める速度。適した着陸場所を選んでたどり着くための、時間と範囲を一番大きくしてくれるよ。"],"cf3ff264":["07ff524550cf.mp3","緊急降下は、高度と引きかえに危険をすばやく減らすこと。煙や火の危険がある高度から下りたり、呼吸しやすい空気まで下りたりするの。機体の構造と速度の限界は守ってね。"],"7aaee064":["2f37bae61855.mp3","ふつうのスピンからの回復は、パワーを絞って、補助翼を中立にして、回転と反対のラダーで回転を止めるの。それから昇降舵を前に押して失速から抜けて、その降下からなめらかに引き起こすよ。"],"f88c90b1":["2873b253faba.mp3","飛行中にドアが開くと、危ないというよりびっくりすることが多いの。操縦にはほとんど影響しないから、操縦を保って、ふつうに着陸しよう。飛行中にむりに直そうとしないでね。"],"2a6287e4":["4314e8f1eb2c.mp3","道に迷ったときのよく教えられる手順は、まず上昇して見晴らしと通信の範囲を広げること。それから ATC やフライトサービスに連絡して、言われた指示に従うよ。"],"889e51ed":["7ae703d759e9.mp3","7700 をスコークして連絡をとると、ATC がレーダーで機体を見つけて、航法の手助け、地形や交通の情報、そのほか必要な手助けをしてくれるよ。"],"4b1cbe0c":["366d47babfe1.mp3","しめった日に回転数がだんだん下がって、エンジンがガタガタするのは、キャブレターアイスの典型的なサイン。キャブレターヒートを入れるのが、決まった対処だよ。"],"c12e3714":["b3f0edc777ec.mp3","パワーが一部だけ落ちたときは、ふつう緊急チェックリストに沿って、キャブレターヒート、ミクスチャー、燃料セレクターと燃料の量、点火、つまりマグネトーを確かめて、原因を見つけて直そうとするの。"],"149eb07e":["c5ad13eb3825.mp3","予防着陸は、本当の緊急事態になる前に、自分で決めて着陸すること。天気が悪くなってきたときや、エンジンの表示が気になるときに早めに対応するの。完全に故障して下りざるをえない不時着とは違うよ。"],"4fdef3af":["ee6dbffb607d.mp3","着水、ディッチングでは、ふつうできるだけ風に向かって着水して、接地の対地速度を小さくするの。乗客に準備してもらって、ゆるんだ物を固定して、すぐに脱出できるようにしておくよ。"],"957b498c":["be33222e3fdb.mp3","放電の表示や低電圧の警告は、ふつうオルタネーターか発電機が故障して、今はバッテリーだけが電気の源だというサイン。電気の使用を減らして、それに合わせて計画してね。"],"89af505c":["a46945e6ac0a.mp3","バキュームが故障すると、バキュームで動く姿勢指示器と方位指示器が信頼できなくなるの。だから、ピトー静圧の計器と電気式の旋回計を頼りにするよ。これをパーシャルパネル飛行って呼ぶの。"],"477bbee6":["c99faf408e05.mp3","フラップが左右ふぞろいに出ると、翼の揚力と抗力が左右で違って、フラップが少ないほうにロールするの。補助翼で打ち消す必要があって、進入速度を上げることも考えてね。"],"ade85c18":["1a95e3aa73f3.mp3","引き込み脚の飛行機のほとんどには、代わりの方法や緊急の脚下げの手順が POH に書いてあるの。脚を上げたままの着陸を考える前に、まずそれを試してね。"],"df19fada":["420b557f5233.mp3","うっかり VFR から IMC に入ったときの訓練では、計器を見て操縦を保つこと、分かっている VFR の天気の方へ標準旋回で引き返すことを強く考えること、そして ATC に助けを求めることを大事にするの。この場面では、空間識失調が死亡事故の大きな原因だからね。"],"969188a7":["45337d6b27af.mp3","サバイバルのアドバイスでは、できれば機体のそばにいることがすすめられるの。人一人より機体のほうが、捜索の人にずっと見つけてもらいやすいからね。天気から身を守ることと、救助への合図を優先して、ELT が作動しているかも確かめてね。"],"d49bd390":["3fbd3d89d505.mp3","客室に煙やにおいが入ってきたら、まずできれば換気を良くして、電気のトラブルみたいな原因を見つけてなくそうとするの。すぐにおさまらなければ、予防着陸や緊急着陸の準備をしてね。"],"0d07294d":["bf55c008cc45.mp3","昔からの優先順位は、アビエイト、ナビゲート、コミュニケート。まず機体を操縦して、次に安全な方へ向かって、それから状況を伝えるの。通信に気をとられて操縦がおろそかにならないようにね。"],"184c29bc":["ed8d5dfead15.mp3","燃料の汚れが疑われるときは、飛ぶ前に地上で、ちゃんとサンプリングして点検して解決しよう。汚れた燃料で飛ぶと、エンジンの力が落ちたり止まったりする危険があるよ。"],"28e3cd37":["fad22adfde3a.mp3","代わりの静圧源は、メインの静圧孔がつまったときの予備の静圧の源。ピトー静圧の計器が使い続けられるよ。POH に書いてある、少しの決まった誤差はあるけどね。"],"329735a1":["7f085c780e97.mp3","オルタネーターが故障すると、残りが限られたバッテリーだけが電気の源になるの。だから、大事でない電気を切って、大事な装置を使える時間をのばすように訓練されるよ。"],"7f650aef":["118785efbffa.mp3","高度と時間に余裕があれば少しだけ原因を探してもいいけど、エンジンが止まったら一番大事なのは、最良滑空速度にして、適した着陸場所を見つけること。不時着を成功させることが一番の目標だからね。"],"cbcf4207":["2e784044a5c6.mp3","油圧が急に大きく下がったら、オイルがもれているみたいな、深刻なエンジンの問題かもしれないの。そのまま飛ぶとエンジンが完全に止まる危険があるから、できるだけ早く着陸する強いサインだと考えてね。"],"72c7c8c7":["c6d0f3a98a1e.mp3","緊急時の一番の基本は、まず機体の操縦を保つこと。それから、正しい手順やチェックリストを順番に落ち着いて進めること。あわてると、手順をとばしたり、さらにミスしたりするからね。"],"550469ae":["7e13d119d8db.mp3","体の主な器官系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"9beb740f":["a9022ba6b338.mp3","解剖学の本では、ふつう8から11の主な器官系を説明するの。循環器系、呼吸器系、消化器系、神経系、骨格系、筋肉系、内分泌系、泌尿器系、生殖器系、外皮系、免疫とリンパ系みたいにね。分け方は本によって少し違うよ。"],"5ae3ac6d":["81f677eef4e6.mp3","循環器系は、心臓と血管が中心で、酸素、栄養、ホルモン、老廃物をのせた血液を全身に運ぶよ。"],"fc71784c":["e24b9d240088.mp3","呼吸器系は、肺をふくめて、体に酸素を取りこんで、肺胞でのガス交換で二酸化炭素を外に出すの。"],"463abd6f":["22d58291ab4e.mp3","消化器系は、口から腸まで、食べ物を物理的にも化学的にも分解して、栄養を血液に吸収できるようにするよ。"],"ab0f8a84":["c219c6415845.mp3","神経系は、脳、脊髄、神経でできていて、体の働き、動き、感覚をコントロールする信号を伝えるの。刺激にすばやく反応できるのも神経系のおかげだよ。"],"850c3ca1":["1417fd91500c.mp3","泌尿器系は、腎臓が中心で、血液をろ過して老廃物と余分な水分を取りのぞき、尿を作って最後に体の外に出すの。"],"0654b9c8":["528e7dcaf72d.mp3","内分泌系は、甲状腺、すい臓、副腎みたいな腺でできていて、ホルモンを血液に出して、代謝、成長、ストレスへの反応などを調節するの。ふつう神経系よりゆっくりはたらくよ。"],"3b745dcd":["265969f2e973.mp3","骨は体を支えて守るだけじゃないの。一部の骨の中には骨髄があって、赤血球、白血球、血小板を作っているよ。"],"c515a2af":["d1ebed50076d.mp3","骨格筋は骨にくっついていて、縮むことで体を動かすの。骨格と一緒に、てこのしくみではたらくよ。"],"ed253437":["a26686cd5684.mp3","免疫系は、白血球、リンパ節、その仲間たちで、病原体や異常な細胞を見つけて戦って、体を守るの。"],"c48c24af":["4b1531590758.mp3","外皮系は、皮膚、髪、爪のこと。外の環境から体を守るバリアになって、体温の調節を助けて、感覚の情報もくれるよ。"],"cb3e6801":["70758d83d7b7.mp3","生殖器系は、生殖細胞と性ホルモンを作って、女性では妊娠と出産を支えるの。"],"4067c345":["7bf8805ab51a.mp3","肝臓は、血液から毒をこしとって、栄養を代謝して、脂肪の消化を助ける胆汁を作るよ。"],"68e183b3":["9aa21f5d236c.mp3","すい臓には二つの役目があるの。消化酵素を作る外分泌の役目と、インスリンやグルカゴンみたいな血糖を調節するホルモンを作る内分泌の役目だよ。"],"87da888a":["1dfbe18b8191.mp3","脾臓は血液をろ過して、古い赤血球をリサイクルして、感染と戦うのも手伝うの。だから免疫とリンパ系の一部だよ。"],"030ffaa0":["dea581b07b38.mp3","外皮系、つまり皮膚は、汗腺や、表面近くの血管が広がったり縮んだりすることで、体温を調節するのを助けているよ。"],"4919956e":["9c76356df626.mp3","リンパ節はリンパ液をこしとって、免疫細胞のすみかになっているの。リンパ系と免疫系の大事な部分だよ。"],"2cf636a8":["abcb5ec42046.mp3","副腎は腎臓の近くにあるけど、内分泌の器官なの。アドレナリンやコルチゾールみたいなホルモンを作っているよ。"],"f9f5b4e1":["9a564e93a4ca.mp3","神経系は電気の信号で、速くて短い調節をして、内分泌系はホルモンで、ゆっくりで長く続く調節をするの。二つが一緒になって、体のほとんどの働きをまとめているよ。"],"d4dff515":["6097d7f24854.mp3","気管、気管支、肺胞は、どれも呼吸器系の一部。ガス交換のために、肺へ空気を出し入れしているよ。"],"648884e7":["eefdc525fc42.mp3","腎臓、尿管、膀胱、尿道が一緒になって泌尿器系を作っているの。血液をろ過して、尿をためて、外に出すよ。"],"84dbbe7a":["015af59c4896.mp3","胸腺、扁桃、骨髄は、どれも免疫細胞を作ったり育てたりすることに関わっていて、免疫系の大事な部分だよ。"],"17f526e6":["6d9b848429ce.mp3","体の方向と面。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"e37fec84":["6a8716db682a.mp3","解剖学的正位は、基準になる姿勢のこと。まっすぐ立って、前を向いて、腕は体の横、手のひらは前に向けるよ。"],"e5ebede1":["df240f23e50e.mp3","前方、腹側は、体の前のほうの位置。後方、背側は、体のうしろのほうの位置だよ。"],"c904fa5f":["17a992d2b017.mp3","上方、頭側は、上のほう、頭に近いほう。下方、尾側は、下のほう、足に近いほうだよ。"],"320f20a1":["b62a87f133d1.mp3","内側は、体の正中線、真ん中に近いほう。外側は、正中線から遠い、横のほうだよ。"],"7669e054":["cf2da463ef49.mp3","近位は、手足にそって、胴体やつけ根に近いほう。遠位は、指先やつま先みたいに、遠いほうだよ。"],"f75abc58":["62da8364cb3f.mp3","矢状面は、体を左右に分けるたての面。正中矢状面は、体をぴったり同じ左右半分に分けるの。"],"060a511e":["4cf60fa33b98.mp3","冠状面、前頭面は、体を前と後ろに分けるたての面だよ。"],"dcf6d213":["40b0c85f3864.mp3","水平面、横断面は、体を上と下に分ける横の面だよ。"],"8b27223b":["6d1c729ba170.mp3","浅いは、体の表面や、表面に近い位置。深いは、表面から遠い、内側の位置だよ。"],"30b3161c":["787c8f1a58a8.mp3","背側は、ほとんど後方と同じ意味で、体のうしろ側のこと。人の解剖学では、特に手と足の甲側に使うよ。"],"aba7b61b":["048f69730f6d.mp3","掌側は、手のひらの側、つまり前の側。背側は、手の甲の側だよ。"],"abacfc70":["4559139b597c.mp3","対側は、基準の点から見て、体の反対側にあること。同側は、同じ側にあることだよ。"],"0241073d":["51a418bb0f16.mp3","尾側は、もともとしっぽの方という意味で、ふつう下方と同じ。体の下の端のほうの位置を表すよ。"],"c4abb5b2":["139cb1a722ff.mp3","心臓は胸のだいたい真ん中にあって、肺に対して内側、つまり正中線に近いほう。肺は両側の、もっと外側にあるよ。"],"5dfd4dde":["c0ca1ebc4e6f.mp3","遠位は、手足にそって、胴体やつけ根から遠い位置。たとえば、指はひじより遠位だよ。"],"aa645e80":["0f4554b65c82.mp3","CT や MRI の横断、アキシャルの画像は、水平面にあたるの。体を上と下に分ける断面を見ているよ。"],"7ae823e8":["de15d6f61f97.mp3","深いは、体の表面から遠い位置で、表面に近い浅いの反対だよ。"],"65b7e037":["0afe7f13100b.mp3","前方は、体や構造の前の側のこと。だから、ひざの前にあるひざのお皿、膝蓋骨は、前方にあるって言うよ。"],"5cc0fcc8":["14982bff2b48.mp3","同側は、基準の点と体の同じ側にあること。対側の反対だよ。"],"6fb7ed4e":["f0cd55d81c18.mp3","冠状面は、体を前と後ろに分けるの。ちょうど真ん中を通らなければ、二つの部分の大きさは違うよ。"],"f8837b00":["4c0db0f602fd.mp3","手のひらを前に向けた解剖学的正位では、親指は手の外側にあって、小指のほうが内側だよ。"],"9f4f4510":["b34e13e15148.mp3","足底は、地面につく足の裏のこと。掌側が手のひらを表すのと同じだね。"],"ae2d479a":["05d692179348.mp3","大陸と海。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"59f11972":["0bc5d1e18425.mp3","英語の国でよく教えられる考え方では、大陸は7つ。アフリカ、南極、アジア、オーストラリア、ヨーロッパ、北アメリカ、南アメリカ。ヨーロッパとアジアをユーラシアにまとめたり、南北アメリカをまとめたりして、6つにする考え方もあるよ。日本の学校では、六大陸って習うことが多いね。"],"c1f68dce":["5ca3dc23346f.mp3","アジアは、面積でも人口でも一番大きな大陸だよ。"],"bf8a6e00":["ebff5483b9df.mp3","アフリカは、アジアの次に大きな、二番目の大陸だよ。"],"a72dc064":["cb820c758e18.mp3","太平洋は、地球で一番広くて一番深い海。地球のぜんぶの陸を合わせたより広いんだよ。"],"80b38e7b":["3e1456811438.mp3","大西洋は、南北アメリカと、ヨーロッパやアフリカの間にある海だよ。"],"24b78a4b":["0b2f29d6578e.mp3","インド洋は、西をアフリカ、北をアジア、東をオーストラリアに囲まれているよ。"],"9615fec6":["cf20b89fc774.mp3","北極海は北極のまわりにあって、世界の海で一番小さくて一番浅いの。"],"549d97ad":["de9dbe6539b6.mp3","南極大陸は、ほとんどぜんぶ氷におおわれていて、ずっと住んでいる人はいないの。主に科学の研究に使われているよ。"],"2de85d60":["18007b337524.mp3","オーストラリアは、大陸でもあり、一つの国でもある、めずらしい場所だよ。"],"821e953e":["cb6c2d2f0b96.mp3","ヨーロッパとアジアは、つながった一つの大きな陸地で、まとめてユーラシアと呼ばれることが多いの。境目は、ふつうウラル山脈などにそって引かれているよ。"],"0e2a61cb":["4b9d309df40a.mp3","南アメリカは、ほとんどが南半球にあって、東は大西洋、西は太平洋に面しているよ。"],"335512f7":["bd16ad1c9f84.mp3","南極海は南極大陸をぐるっと囲んでいて、五つ目の海として数えられることもあるよ。"],"d17481f3":["7face45154dc.mp3","南極には、ずっと住んでいる人はいないの。そこにいるのは、交代でやってくる科学者と、それを支えるスタッフがほとんどだよ。"],"00eae9dd":["f027d7712c26.mp3","地中海は、ヨーロッパの南、アフリカの北、アジアの西に囲まれているよ。"],"af8587ab":["f7142e673f22.mp3","アマゾン川は、主にブラジルと南アメリカのほかの国を流れて、大西洋に注いでいるよ。"],"c97f837b":["d3a17e922edf.mp3","サハラ砂漠は、北アフリカの大部分に広がっているよ。"],"e25bf670":["a6ba9ea53cca.mp3","アフリカは西を大西洋、東をインド洋に面しているけど、ずっと北にある北極海には面していないよ。"],"5b79b0f5":["4650fcde639d.mp3","グレートバリアリーフは、オーストラリアの北東の海岸の沖、珊瑚海にあるよ。"],"edfd5f52":["dab31845df88.mp3","グリーンランドは、地理的には北アメリカの大陸棚の上にあるけど、ヨーロッパの国デンマークの自治領なの。だから、どこに分類するかはよく話題になるよ。"],"9816789b":["6d97cb1ffabf.mp3","ベーリング海峡は、アジアにあるロシアのチュクチ半島と、北アメリカにあるアラスカのスワード半島の間にあるよ。"],"a1cfa057":["d16f66976d7e.mp3","スイスはヨーロッパの真ん中にあって、まわりをぜんぶ陸に囲まれた内陸国。海に直接出られないの。"],"44277ff5":["77ce690eb2af.mp3","死海はイスラエルとヨルダンの国境にあって、世界で一番塩からい水のひとつだよ。"],"bcbe6c8b":["f43fc263fb7c.mp3","骨と骨格系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"a54bbc94":["bd7b2a20576d.mp3","大人の骨は、およそ206個。赤ちゃんはもっとたくさんの骨を持って生まれて、成長するうちに多くがくっついていくの。"],"f428475c":["59b81f993923.mp3","太ももにある大腿骨は、体で一番長くて、一番強い骨のひとつだよ。"],"0e2c6e9e":["20f9d027290c.mp3","肋骨のかごは、心臓、肺、そのほかの胸の中の器官を囲んで守っているよ。"],"019e8255":["97d2a216e627.mp3","頭蓋骨は脳を包んで守りながら、顔の形を作って、筋肉がつく場所にもなっているの。"],"3e9fe496":["3fe72f1dc26d.mp3","背骨、脊柱は、脊髄を囲んで守りながら、胴体を支えて、しなやかに動けるようにしているよ。"],"54943788":["89bceadb01fc.mp3","関節学は、二つ以上の骨が出会う関節の、つくりと働きを研究する解剖学の分野だよ。"],"b4ac4fcf":["d4892b69d736.mp3","骨は、特にカルシウムとリンみたいなミネラルをたくわえていて、体のミネラルのバランスを保つために、必要なときに血液に出すの。"],"774317bd":["f5c657211d35.mp3","骨髄、特に一部の骨の中にある赤色骨髄が、血液の細胞を作る一番の場所。これを造血って呼ぶよ。"],"f24a2b4b":["7b06468d5075.mp3","中耳にある三つの小さな耳小骨、つち骨、きぬた骨、あぶみ骨は、体で一番小さい骨。音の振動を伝えているよ。"],"fde5fc53":["9b7efa90b2cf.mp3","軟骨は、骨よりやわらかくてしなやかな結合組織で、ふつう自分の血管を持っていないの。関節、鼻、耳などにあって、クッションになったり支えたりしているよ。"],"1a6023fb":["16af3806676f.mp3","体軸骨格は、頭蓋骨、背骨、肋骨のかご。付属肢骨格は、腕、脚、肩、骨盤の骨だよ。"],"5db70980":["aa3d4864b9ae.mp3","骨粗しょう症は、骨の密度が減って、すかすかでもろくなる病気。特にお年寄りで、骨折の危険が高くなるよ。"],"c7b0989a":["cc0e6a607631.mp3","骨折は、骨が折れたり、ひびが入ったりすること。髪の毛みたいに細いひびから、完全に折れるものまであるよ。"],"04ae4f95":["9a2aa0bd0b5f.mp3","鎖骨は、胸の骨、胸骨と、肩甲骨をつないで、肩を安定させて位置を決めるのを助けているよ。"],"a6fa36aa":["c7dd0e1c49c1.mp3","骨盤は骨の輪になっていて、背骨と上半身の重さを支えながら、膀胱、腸、生殖器みたいな器官を守っているよ。"],"0334765d":["c73aeb9a0231.mp3","X線は、骨みたいなかたいものより、やわらかい組織を通りやすいの。だから、骨折や骨の異常が X線写真ではっきり見えるよ。"],"b1ada031":["c3283f117f57.mp3","背骨の区分は、上から、首の頸椎、背中の上の胸椎、腰の腰椎、仙骨、そして尾てい骨の尾骨だよ。"],"003c06fd":["c2362d6a2e94.mp3","靭帯は、骨と骨をつないで関節を安定させる、繊維でできた結合組織。腱は、筋肉と骨をつなぐよ。"],"c7989a30":["9fb47577ad7a.mp3","骨のリモデリングは、一生続くしくみ。破骨細胞が古い骨をこわして、骨芽細胞が新しい骨を作るの。骨の強さを保って、小さな傷を直しているよ。"],"8c4f9410":["a40ab028cde2.mp3","ねんざは、関節を急にひねったりぶつけたりして、靭帯がのびたり切れたりすること。筋肉や腱のけがの、肉ばなれとは違うよ。"],"2f441225":["c74d391d6401.mp3","球関節は、丸い骨の先がお椀みたいなくぼみにはまった関節。回すことをふくめて、ほかのほとんどの関節より広く動かせるよ。"],"9eec5afc":["d6d89ed9fe42.mp3","蝶番関節は、ドアの蝶番みたいに、主に一つの面で、曲げたりのばしたりする動きをするの。"],"ea727c4c":["c829b2374379.mp3","国とその場所。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"82e4d3d5":["888ceb030361.mp3","ロシアは、面積で世界一大きな国。ヨーロッパとアジアの両方にまたがっているよ。"],"fd510641":["d84c25f396fb.mp3","国連の推計によると、2020年代のはじめに、インドが中国を追いこして、世界で一番人口の多い国になったの。"],"398c9318":["0a3218ec240c.mp3","オーストラリアは、大陸でもあり、一つの独立した国でもある、めずらしい場所だよ。"],"47fe782e":["170c4b8ce966.mp3","ブラジルは、チリとエクアドル以外の、南アメリカのすべての国と国境を接しているよ。"],"d6ef00aa":["af5e5708eae6.mp3","エジプトはほとんどがアフリカの北東にあるけど、国の一部のシナイ半島は地理的にアジアにあるの。だからエジプトは、二つの大陸にまたがる国だよ。"],"a91ec438":["e0d4b6fb934b.mp3","トルコは、東トラキアっていうヨーロッパの小さな部分と、ずっと大きなアジアのアナトリア半島にまたがる国だよ。"],"d91ca1e3":["8aec01805744.mp3","メキシコは北アメリカの一部で、アメリカのすぐ南にあるよ。"],"759d7b1a":["bc9accb5a103.mp3","バチカン市国は、イタリアのローマの中にある独立した都市国家で、面積も人口も世界一小さい国だよ。"],"6aeca6a2":["bb1f639cd5ec.mp3","日本は、四つの大きな島と何千もの小さな島でできた島国で、アジア大陸の東の沖にあるよ。"],"6211cb2f":["df2bab9b170a.mp3","南アフリカは、アフリカ大陸の一番南の地域にあるよ。"],"6108ff58":["e684ced12cba.mp3","アメリカとカナダの国境は、アラスカの部分も入れておよそ8900キロ。世界で一番長い国境で、アメリカとメキシコの国境のほぼ三倍だよ。"],"269f7d78":["6e8cdff6c148.mp3","インドネシアは世界一大きな島国で、17000以上の島でできた群島なの。"],"b6327ecd":["f85a77056496.mp3","ナイジェリアはアフリカで一番人口が多い国で、世界でも人口の多い国のひとつだよ。"],"3e155bff":["1f0d6f04524e.mp3","中国とインドは、どちらもアジアにある大きな国。アジアは世界で一番大きくて、人口も一番多い大陸だよ。"],"ce0bf489":["58980d1e5b66.mp3","インドはよく亜大陸と呼ばれるの。大きな陸地で、アジアのほかの部分とは少し別の、インドプレートの上にあるからだよ。"],"b79243fb":["00332a01a5e8.mp3","アルゼンチンの海岸は、太平洋じゃなくて大西洋に面しているの。チリ、ペルー、エクアドルは、どれも太平洋に面しているよ。"],"f3bc7958":["6bab46ebaeb9.mp3","イギリスは、イングランド、スコットランド、ウェールズ、北アイルランドでできているの。アイルランド共和国は、別の独立した国だよ。"],"b8c8faff":["6b0d8cb0e7fb.mp3","小さな国アンドラは、ピレネー山脈の中にあって、北のフランスと南のスペインにはさまれているよ。"],"e96ba050":["ec54a73b69d4.mp3","カナダの首都はオンタリオ州のオタワ。でも、一番大きな都市はトロントだよ。"],"9ba4167b":["86eb847c500e.mp3","ロシアは、ひと続きの国土で11の時間帯にまたがっているの。フランスは、世界中の海外領土まで数えたときだけ、もっと多い12になるよ。"],"577095dd":["e76c9db4d26b.mp3","ニュージーランドは、太平洋の南西、オーストラリアの南東にある島国だよ。"],"1c36f512":["332b44c84989.mp3","スカンジナビアは、昔からノルウェー、スウェーデン、デンマークのこと。もっと広い北欧の国として、フィンランドとアイスランドを入れることもあるよ。ドイツ、ポーランド、オランダはスカンジナビアじゃないの。"],"ca050663":["da31106d2c28.mp3","筋肉と筋肉系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"533e5ca0":["82541ddcf13f.mp3","筋肉の組織は三種類。骨についていて自分で動かせる骨格筋、心臓だけにある心筋、そして胃や血管みたいな器官にある、自分では動かせない平滑筋だよ。"],"c43b3a3e":["3b62d9b0457b.mp3","骨についている骨格筋は、ふつう自分の意思で動かせる随意筋。思った通りに体を動かせるよ。"],"9b5fec43":["72978957faf3.mp3","心筋は、心臓の壁だけにある、特別な不随意筋だよ。"],"e3a542eb":["27d5af88f7c5.mp3","平滑筋は自分の意思とは関係なくはたらいて、消化や血管の太さみたいなことを、意識しなくてもコントロールしているの。"],"36786526":["98833f0a3376.mp3","腱は、筋肉を骨につなぐ、じょうぶな繊維の結合組織。筋肉が縮む力を伝えて、体を動かすよ。"],"56435418":["c9e05b6a8391.mp3","屈曲は、ひじを曲げるみたいに、体の二つの部分の角度を小さくする動き。たいてい筋肉が縮んで、骨どうしを引き寄せることで起きるよ。"],"6c1a7366":["78b43106c443.mp3","伸展は、ひじやひざをのばすみたいに、関節の角度を大きくする動きだよ。"],"dcff07a1":["03d1c80dd377.mp3","拮抗筋のペア、たとえば力こぶの上腕二頭筋と、うらの上腕三頭筋は、反対にはたらくの。片方が縮んで動くとき、もう片方はゆるむ。反対の動きでは、その逆になるよ。"],"2111163e":["6ae0970c8c2e.mp3","おしりにある大殿筋は、体積で体の中で一番大きくて、一番強い筋肉のひとつと考えられているよ。"],"cf41c098":["223e76f590ce.mp3","筋肉の疲れは、グリコーゲンみたいなエネルギーのたくわえが減って、代謝でできたものがたまってきて、筋肉がうまく縮み続けられなくなると起きるの。"],"a7c8e510":["5173c968073d.mp3","等尺性収縮、アイソメトリックでは、筋肉の長さはほとんど変わらずに力を出すの。同じ姿勢を保ったり、動かないものを押したりするときだよ。"],"01e3804d":["0dff7f62c972.mp3","筋トレをすると、ふつう筋肥大が起きるの。一本一本の筋繊維が太くなって、ほかの神経と筋肉の変化と一緒に、時間をかけて力が強くなるよ。"],"df86a7d9":["dd5e6f51cca2.mp3","筋肉痛は、医学用語で筋痛。使いすぎ、けが、病気などで起きるよ。"],"655760b3":["81311b3af9f5.mp3","協働筋は、主に動かす筋肉、主動筋を助ける筋肉。力を足したり、関節を安定させたりするよ。"],"c2606f37":["e5f1f9bc4ef8.mp3","腕の上腕二頭筋は、ひじを曲げて、前腕を回して手のひらを上に向ける、回外も手伝うよ。"],"72a68e48":["9d20b3890dab.mp3","上腕三頭筋は、ひじをのばすの。ひじを曲げる上腕二頭筋の、反対の役目の拮抗筋だよ。"],"ce085445":["000c2306cda0.mp3","ふくらはぎのメインの筋肉、腓腹筋は、つま先を下に向ける底屈をするの。歩く、走る、跳ぶのに大事だよ。"],"f2ce3511":["93ef7e703e38.mp3","太ももの前の大腿四頭筋は、ひざをのばすの。立ち上がる、歩く、けるみたいな動きでたくさん使うよ。"],"cdad7957":["9a2933584fee.mp3","体幹の筋肉、つまりおなかと腰の筋肉は、背骨を支えて良い姿勢を保つのに大きな役目をはたしているよ。"],"c8f01c57":["8a23c07bbf35.mp3","あとから来る筋肉痛は、慣れない運動や激しい運動で、筋繊維に目に見えない小さな傷ができることが原因と考えられているの。炎症と修復が起きて、一日か二日あとに痛くなるんだよ。"],"c76965aa":["2ed9485ac5e9.mp3","ちゃんとウォームアップすると、血流と筋肉の温度が上がって、体がやわらかくなって反応も速くなるの。そのあとの運動でけがをしにくくなるよ。"],"35cf1a0c":["b5782733210f.mp3","筋緊張は、休んでいるときにも筋肉が自然に少しだけ縮み続けている状態のこと。姿勢を保って、いつでも動けるようにしてくれるよ。"],"0c42b2e0":["e9b06d05b9e3.mp3","緯度、経度、座標。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"a2acea7e":["0260facf4c83.mp3","緯線は、地球を東西にぐるっと回る横の線で、赤道と平行。赤道から北か南へ、どれだけ離れているかを表すよ。"],"027ea2ba":["879767ad3447.mp3","経線、子午線は、北極から南極までのびる線で、本初子午線から東か西へ、どれだけ離れているかを表すよ。"],"54bab20f":["c564044522c0.mp3","赤道は、緯度0度の基準の線。北極と南極から同じ距離にあって、地球を北半球と南半球に分けているの。"],"2c1a9704":["d6aa9ba50223.mp3","本初子午線は、国際的な取り決めでイギリスのグリニッジを通っていて、東か西の経度を測る0度の基準になっているよ。"],"1a325f35":["7d8513ef04d8.mp3","緯度は、赤道の0度から、北極か南極の90度まで測るよ。"],"2bc71772":["681f89d7dca6.mp3","経度は、本初子午線の0度から、東か西へ180度まで測るの。二つは、だいたい太平洋の上にある180度の経線で出会うよ。"],"d671392f":["b69d46b39c79.mp3","北半球で西半球にある場所は、ふつうの書き方では、緯度がプラス、つまり北緯で、経度がマイナス、つまり西経になるよ。"],"813b380f":["48b596fc5d22.mp3","時間と同じように、座標も、1度を60分、1分を60秒に分けて、もっと細かく場所を表せるよ。"],"14942924":["a3c83741bec0.mp3","北緯およそ23.5度の北回帰線と、南緯およそ23.5度の南回帰線は、太陽が真上に来ることがある一番北と一番南の緯度なの。6月と12月の至の日だよ。"],"9e303a1d":["0d2e538369ca.mp3","GPS の受信機は、いくつかの衛星からの信号が届くまでの時間を測って、三辺測量で緯度、経度、高度を正確に計算するよ。"],"fef96817":["8b1ed5f0772b.mp3","エクアドルのキトは、ほぼちょうど赤道の上にあるの。国の名前も、スペイン語で赤道という意味のエクアドルからきているよ。"],"8d73e1db":["a43c4154606f.mp3","緯度と経度は地球の表面での横の位置を表して、標高が三つ目の次元を足すの。それで、三次元の空間の一点が完全に決まるよ。"],"c73ce6b0":["5c42020b4953.mp3","日付変更線は、だいたい本初子午線の反対側の、経度180度の線にそっているの。人が住む地域や国を分けないように、ところどころ曲がっているよ。"],"2bac1436":["811d139c0a52.mp3","時間帯は主に経度にそって決められているの。地球が自転しているから、経度によって昼と夜になる時刻が違うんだよ。"],"4a5ddaa8":["a33288ca4013.mp3","経線は北極と南極で一点に集まるから、経度1度ぶんの地上の距離は、緯度が高くなるほど短くなって、極では0になるの。緯度1度ぶんの距離は、どこでもだいたい同じだよ。"],"a38be2fa":["cdd326075af3.mp3","緯度がマイナス、つまり南緯なら、その場所は南半球にあるの。南緯33度、西経70度は、だいたいチリのサンティアゴだよ。"],"77652243":["45563dd81c90.mp3","対蹠点は、ある場所の地球のちょうど反対側の点。緯度のプラスとマイナスを入れかえて、経度を180度ずらすと見つかるよ。"],"59573129":["3560e96e326d.mp3","1海里は、子午線にそった緯度1分ぶんの長さで、およそ1852メートル、6076フィートだよ。"],"8d31ca5c":["58dff0530a43.mp3","座標は、40.7128 みたいな十進法の度でも、昔ながらの度、分、秒の形でも表せるよ。"],"9503cfc7":["1d6406d4f1f7.mp3","本初子午線と、その反対の経度180度の線が、一緒になって地球を東半球と西半球に分けているよ。"],"be4a955f":["c1140779a3be.mp3","緯度0度の赤道と、経度0度の本初子午線が出会う点は、西アフリカの沖の大西洋にあるの。ヌル島って呼ばれることもあるよ。"],"9b5912bd":["fb8aa7a7bd7d.mp3","天測航法は、星や太陽みたいな天体が水平線からどれだけ高いかの角度と、正確な時刻を使って、船の緯度と経度を計算する方法だよ。"],"1e87cdd6":["95a513afb115.mp3","脳と神経系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"b64dbf68":["4aaf3d994ae3.mp3","中枢神経系は脳と脊髄。それと組になるのが末梢神経系で、体のほかの部分へのびる神経のことだよ。"],"3e5769a6":["c0109cb5decc.mp3","大脳は脳の一番大きな部分で、左右二つの半球に分かれていて、考える力、自分で動かす運動、意識できる感覚を受け持っているよ。"],"14a771b9":["73c12703409d.mp3","小脳は、バランス、筋肉の張り、そして自分で動かす動きの細かい調整をしているよ。"],"60bc27d7":["0abfdfa631d9.mp3","脳幹は、呼吸、心拍、血圧の調節みたいな、自動で命を支える働きをたくさんコントロールしているの。"],"7513dcff":["a13097aa53af.mp3","神経細胞、ニューロンは、シナプスっていう小さなすき間でやりとりするの。電気の信号で化学物質の神経伝達物質が出て、次の細胞に信号を渡すんだよ。"],"02cb5547":["50df19e712ad.mp3","自律神経系は、心拍、消化、呼吸の速さみたいな、自分の意思とは関係ない体の働きを、ふつう意識しないうちに調節しているよ。"],"59675e86":["330fb0b84f3d.mp3","交感神経系は、ふつう体を活動にそなえさせるの。闘争か逃走の反応だね。副交感神経系は、休んで回復するのを助けるよ。休息と消化の反応だね。"],"965a1c37":["ce5cf018ee01.mp3","脊髄は脳と末梢神経の間で信号を運んで、ひざをたたくと足がはね上がる膝蓋腱反射みたいに、脳を通さずに反射を起こすこともできるよ。"],"851013e1":["33cb35dc05c0.mp3","脳のうしろにある後頭葉は、主に目からの見た情報を処理しているよ。"],"25acb27f":["2782ff716004.mp3","前頭葉は、考える、計画する、問題を解く、性格、そして自分で動きを始めるみたいな、高度な働きで大きな役目をはたしているよ。"],"7ceefd2d":["16784899791e.mp3","多くの反射は、脊髄のレベルの反射弓で処理されるの。だから、脳が感覚をちゃんと受け取る前に、とても速く体を守る反応ができるよ。"],"bf35e302":["5f4f31b20e3f.mp3","神経伝達物質は神経細胞からシナプスに出されて、となりの細胞の受容体にくっついて、神経の信号を伝えたり調節したりするよ。"],"171f07ed":["fe6a25cb5ccf.mp3","頭頂葉は、さわる、温度、痛み、空間の感覚みたいな情報を処理して、体からの感覚をまとめるのを助けているよ。"],"a9b8c87a":["d9ee373f8efb.mp3","側頭葉は、聞いた情報を処理して、言葉の理解や、ある種類の記憶にも関わっているよ。"],"ab7b8860":["75da0165bf40.mp3","海馬は、新しい長期の記憶を作って定着させるのにとても大事な役目をしているの。ここが傷つくと、新しいことを覚えるのがとてもむずかしくなることがあるよ。"],"83426ee9":["9a2c20d188c2.mp3","扁桃体は、感情、特に恐怖や、体が危険に反応するしくみで、中心的な役目をはたしているよ。"],"78a71b68":["79d2bbbc1ec4.mp3","脳脊髄液は、脳と脊髄を包んでクッションになり、代謝でできたごみを取りのぞいて、少し栄養も届けているよ。"],"4e7034ed":["64bde241e78c.mp3","脳梁は、左右の大脳半球をつなぐ、神経繊維の太い束。二つの半球がやりとりして、協力できるようにしているよ。"],"5809bac2":["a0b13f799d9f.mp3","運動ニューロンは、中枢神経から筋肉へ信号を送って、筋肉を縮めて体を動かすの。感覚ニューロンは、その反対向きに情報を運ぶよ。"],"eb2a220f":["e31e95e05203.mp3","感覚ニューロンは、体中の感覚の受容器から中枢神経へ情報を送って、脳がさわる、光、音みたいな刺激を感じられるようにしているよ。"],"48c075d9":["a2b00690a981.mp3","脳しんとうは、頭を打ったり急に揺さぶられたりして起きる、軽い外傷性の脳のけが。一時的に脳のふつうの働きが乱れるの。"],"556ac3c6":["36e6c2e7ca29.mp3","ミエリンは多くの神経繊維を包む絶縁のさやで、神経を伝わる電気の信号のスピードを、ぐっと速くしているよ。"],"6eaba90b":["1acf514813c8.mp3","心臓と循環器系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"3ff4cfb8":["dbb8cb8b374d.mp3","人の心臓には四つの部屋があるの。上の二つの心房と、下の二つの心室だよ。"],"ea5b2304":["0eede57b9fa2.mp3","心臓は筋肉でできたポンプで、血液を全身にめぐらせて、組織に酸素と栄養を届けて、老廃物を運び去るの。"],"857d7d7f":["3b90c22986c1.mp3","大動脈は体で一番太い動脈で、酸素をたっぷりふくんだ血液を、心臓の左心室から全身へ運ぶよ。"],"afac19bd":["63ab1d4d55b5.mp3","肺動脈は、酸素の少ない血液を右心室から肺へ運ぶの。肺で酸素を受け取って、二酸化炭素を出すんだよ。"],"6fac2459":["27c6f40ac531.mp3","心臓の筋肉そのものには、冠動脈が酸素の多い血液を届けているの。冠動脈は、大動脈のつけ根近くから枝分かれしているよ。"],"a308e90b":["d216d0d3e2d0.mp3","健康な大人の安静時の心拍数は、ふつう一分間におよそ60から100回。体力、年齢、そのほかのことで変わるよ。"],"4c853271":["a99562ab4d07.mp3","洞房結節は、右心房にある特別な細胞の小さなかたまりで、ふつうの心臓の拍動ごとの電気の信号を作っているの。心臓の天然のペースメーカーだよ。"],"118453f9":["209ea6c86039.mp3","動脈と静脈を分ける決め手は、酸素の量じゃなくて、心臓に対する血液の流れの向きなの。酸素の量で言うと、肺動脈と肺静脈が目立つ例外だよ。"],"9efe20fb":["55818ba31c55.mp3","毛細血管は、目に見えないほど細くて壁のうすい血管。ここで血液とまわりの組織の間で、酸素、栄養、二酸化炭素、老廃物が交換されるの。"],"50e9c99c":["6cffa519bbb6.mp3","血圧の最初の大きいほうの数字は、心室が縮むときの収縮期血圧。二つ目の小さいほうの数字は、拍動の間に心臓がゆるむときの拡張期血圧だよ。"],"86dfe8c7":["f9e52cf85dcb.mp3","英語の cardio は心臓、vascular は血管のこと。合わせて cardiovascular、心臓と血管のしくみ、つまり循環器系を表すよ。"],"cb4f255e":["7d38410c34e2.mp3","心臓の四つの弁は、拍動ごとにそろって開いたり閉じたりして、血液が部屋の中を一方向に流れて、逆流しないようにしているよ。"],"adf415b5":["c848ae7f44f7.mp3","脈は、心臓が血液を送り出すたびに、動脈がリズムよく広がったり縮んだりすることで、体のいくつかの場所でさわって感じられるよ。"],"03f065cf":["30f11fcfad45.mp3","規則正しい有酸素運動は、ふつう心臓の筋肉を強く、効率よくして、時間をかけて循環器全体の健康を良くしてくれるよ。"],"4ae9c8ce":["6ca7cd461111.mp3","動脈硬化、アテローム性動脈硬化は、脂肪、コレステロールなどが動脈の壁にだんだんたまっていくこと。時間とともに動脈がせまくなって、血流がさまたげられることがあるよ。"],"5381b0fd":["6bfe6befa452.mp3","肺と呼吸器系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"8c60f870":["ff31569307cc.mp3","肺はガス交換の一番の場所。吸いこんだ空気の酸素が血液に入って、血液の二酸化炭素が空気に出て、はき出されるの。"],"8ad079ee":["7cf73a7a88cd.mp3","気管のあと、空気は気管支に入って、どんどん細い細気管支に枝分かれして、最後に肺胞っていう小さな空気のふくろにたどり着くよ。"],"6f2dff4f":["ec466f7ddc99.mp3","肺胞は、気管支の木の先にある、とても小さくて壁のうすい空気のふくろ。毛細血管に囲まれていて、ここで血液と酸素や二酸化炭素を交換するの。"],"8e42f87d":["51de961e6c98.mp3","横隔膜は呼吸の一番の筋肉。息を吸うときに縮んで平らになって、胸を広げて肺に空気を引きこんで、息をはくときにゆるむよ。"],"94b44cab":["0c7757f598d3.mp3","ふつうの人の体では、右の肺は三つ、左の肺は二つの葉に分かれているの。左は心臓の場所をあけるために、少し小さいんだよ。"],"b2253f54":["57788b22be3a.mp3","気管は、C の形をした軟骨の輪がいくつもならんで支えているの。空気の通り道を開いたまま、少ししなやかにも動けるようにしているよ。"],"bbf26d7b":["9e6886694f28.mp3","喉頭蓋は、飲みこむときに気管の入り口にふたをして、食べ物や飲み物を気道じゃなくて食道へ向かわせるのを助けているよ。"],"237f62f1":["ce3ab29fb07c.mp3","健康な大人の安静時の呼吸は、ふつう一分間におよそ12回から20回だよ。"],"2c713071":["8267e24fb918.mp3","胸膜は、それぞれの肺を包む二重の膜。膜の間にうすい液体の層があって、肺がふくらんだり縮んだりするときのこすれを減らしているの。"],"6d68c30c":["79450a391bb3.mp3","赤血球の中のヘモグロビンは、肺の毛細血管で酸素とくっついて、それを全身の組織にわたすの。酸素を運ぶ主役だよ。"],"95f9b079":["4e5c49002d4c.mp3","ふつうにリラックスして息をはくときは、横隔膜と吸うときの筋肉がゆるんで、胸が自然に小さくなって、肺から空気が押し出されるの。"],"d2c720d2":["1d9a1cc7bfe4.mp3","肺活量は、できるだけ深く息を吸ったあと、思いきりはき出せる空気の一番多い量。肺の働きを調べるのによく使われるよ。"],"17f40ce0":["81eef1dc8d88.mp3","気道の内側に生えている線毛は、波のようにそろって動いて、粘液や、つかまえたほこりやごみを上へ外へとはき出して、肺を守っているの。"],"d586c954":["2153dbd14582.mp3","たばこは、時間とともに線毛と肺胞をいためることがよく分かっているの。粘液やごみを外に出す力が落ちて、ガス交換の効率も下がってしまうよ。"],"b013890d":["f2ed03d7917a.mp3","呼吸器系は血液に酸素を入れて二酸化炭素を取りのぞき、循環器系はその酸素の多い血液を全身に配って、二酸化炭素の多い血液を肺に戻すの。だから二つのしくみは、しっかり支え合っているよ。"],"e69581f0":["c6eb04d5e1cd.mp3","消化器系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"2bd2a65b":["a09742f0e279.mp3","消化は口から始まるの。かむことで食べ物を物理的にくだいて、だ液がでんぷんの化学的な分解を始めるよ。"],"ff5b09f2":["89c278825c89.mp3","食道は筋肉でできた管で、飲みこんだ食べ物をのどから胃へ運ぶよ。"],"7013e1f5":["dd69644d2777.mp3","胃は、食べ物を物理的にかき混ぜて、胃酸と消化酵素で化学的に分解して、どろっとした状態にするの。"],"fc48d4db":["0c08bfe345e6.mp3","小腸は、絨毛っていう指みたいな突起で表面積がとても広くて、栄養を血液に吸収する一番の場所だよ。"],"7e0d5d56":["0e28425d4b09.mp3","大腸は、主に残った消化物から水分と電解質を吸収して、うんちを作ってためておくの。"],"5ced2ca1":["d3be76d9f4fe.mp3","胆汁は肝臓で作られて、胆のうでためられて濃くなるの。胆のうはそれを小腸に出して、脂肪の消化と吸収を助けるよ。"],"5af10248":["958e917e9582.mp3","すい臓は、炭水化物、たんぱく質、脂肪を分解する消化酵素を作って、小腸に出しているよ。"],"61237cf4":["b6053f93a6c1.mp3","ぜん動運動は、消化管にそった筋肉が波のようにそろって縮んだりゆるんだりして、食べ物やかすを先へ送り出す動きだよ。"],"16830e8c":["6deb9a835a62.mp3","肝臓は胆汁を作るだけじゃないの。消化管から吸収した栄養を代謝して、血液から毒をこしとって、ビタミンや、グリコーゲンみたいなエネルギーのたくわえも保存しているよ。"],"dd5383a8":["064a98eeb4a7.mp3","消化酵素は、たんぱく質、炭水化物、脂肪みたいな大きな分子を、体が吸収して使える小さな単位に化学的に分解するの。"],"b49bea21":["8f224a2b409d.mp3","虫垂の本当の働きはまだ議論されているの。良い腸内細菌のすみかになったり、少し免疫の役目をしたりするかもしれないけど、なくても困らなくて、手術で取ったあともふつうに暮らせるよ。"],"d1fc5a8e":["f66cdfd8b99b.mp3","絨毛と、さらに小さな微絨毛が、小腸の内側の表面積をぐっと広げて、栄養をとても効率よく吸収できるようにしているよ。"],"0eb24909":["2e54b06b7874.mp3","胃の強い酸性は、食べ物を分解して、ある消化酵素をはたらかせて、食べ物と一緒に入ってきた細菌などの病原体の多くをやっつけるのを助けているの。"],"ad439b00":["a9fb97114f20.mp3","腸内細菌叢、腸内マイクロバイオームは、消化管にすむ細菌などの微生物の集まり。ある物質の消化を助けて、免疫を支えて、もっと広く健康に影響していることが分かってきているよ。"],"c88b8c67":["b8a72af1e8d0.mp3","食べてから外に出すまでの消化の全部は、平均でおよそ24時間から72時間。でも、人や食事などによってかなり違うよ。"],"4263670f":["b07cbfa35bee.mp3","腎臓と泌尿器系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"fa1c18fa":["30e200e1ee29.mp3","腎臓は血液をろ過して、老廃物、余分な塩分、余分な水分を取りのぞいて尿を作りながら、体の水分と電解質のバランスを調節するのを助けているよ。"],"98a32e19":["59c49b91c9f1.mp3","尿はそれぞれの腎臓から、筋肉の管の尿管を通って膀胱へ流れて、外に出すまでためられるよ。"],"76a9ea79":["37771e9763e1.mp3","尿道は、おしっこのときに尿が膀胱から体の外へ出ていく管だよ。"],"3d6197cf":["a586cb857570.mp3","それぞれの腎臓には、ネフロンっていう小さなろ過の単位がおよそ百万個あって、一つ一つが血液をろ過して尿を作るのを助けているの。"],"c86b56d8":["af2a71527a0d.mp3","腎臓は血液から老廃物をろ過するだけじゃなくて、血圧の調節や、体の水分、電解質、酸と塩基のバランスを保つのも助けているよ。"],"b68817cd":["7018e2f47ff6.mp3","腎臓はエリスロポエチンっていうホルモンを出して、骨髄にもっと赤血球を作るように伝えるの。血液の酸素が少ないときに、特に大事だよ。"],"2408d7a2":["d12d2c427436.mp3","ほとんどの人は、背骨の両側、おなかのうしろ寄りに、腎臓を二つ持って生まれてくるの。でも、ちゃんと働く腎臓が一つあれば生きていけるよ。"],"d13a9b7f":["60a2d8ad3c7d.mp3","水分を十分にとると、腎臓が老廃物を効率よくろ過できて、尿が濃くなりすぎるのを防げるの。濃い尿は、腎臓結石の危険が高くなることと関係しているよ。"],"ae4b3ad6":["28a291668768.mp3","腎臓結石は、シュウ酸カルシウムみたいな尿の中のミネラルや塩が結晶になって固まったもの。尿の通り道を動くと、とても痛いことがあるよ。"],"1765ed3e":["92f2efc20f08.mp3","膀胱は筋肉でできた、のびちぢみする器官。腎臓で作られた尿を、おしっことして出すまでためておくの。"],"c6344101":["b4ffc9e70794.mp3","英語の renal は腎臓を表す医学用語。renal artery は腎動脈、renal failure は腎不全、みたいに使うよ。"],"10b33543":["506eed257209.mp3","腎動脈は大動脈から枝分かれして、ろ過のために血液をそれぞれの腎臓へ届けるの。ろ過された血液は、腎静脈を通って循環に戻るよ。"],"48adcd6a":["c53b01cca01c.mp3","腎臓は毎日とてもたくさんの血液をろ過していて、その量はおよそ150から200リットル。でもろ過した液体のほとんどは再吸収されて、尿として出るのはおよそ1から2リットルだけなの。"],"eb6f863e":["7f01a142b45b.mp3","腎臓が自分でちゃんと働けなくなったとき、透析で血液から老廃物と余分な水分をろ過するの。機械を使う血液透析と、おなかの内側の膜を使う腹膜透析があるよ。"],"7426e35d":["617d9d97d570.mp3","泌尿器系と生殖器系は、体の中で近くにあって、男性の尿道みたいに一部を共有しているの。でも主な役目は、老廃物を出すことと、子どもを作ることで、全然違うよ。"],"82459ca4":["da83e0afec93.mp3","内分泌系とホルモン。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"b3751a9e":["b5a573cb94d6.mp3","内分泌系は、化学の伝令役のホルモンを直接血液に出して、体のいろんな働きを調節する腺でできているよ。"],"f408748c":["243b6bdf3be9.mp3","甲状腺は、体の代謝の速さを調節するホルモンを作っていて、エネルギーの使い方、成長、そのほかたくさんの働きに影響しているよ。"],"625e726f":["4539ffff7589.mp3","すい臓はインスリンを作るの。インスリンは、細胞が血液からブドウ糖を取りこめるようにして、血糖値を調節するのを助けるホルモンだよ。"],"fc121e29":["0d7659b4d025.mp3","副腎はいくつかのホルモンを作っていて、その一つがアドレナリン、エピネフリン。ストレスや危険に対する、体のすばやい闘争か逃走の反応を引き起こすよ。"],"3b778a66":["797ddc0803ef.mp3","下垂体は脳の底にあって、ほかの多くの内分泌腺の働きをコントロールするホルモンを出して、調節しているの。"],"8b67b842":["a3dd4d08a599.mp3","成長ホルモンは主に下垂体で作られて、子どものころの成長と、一生続く組織の修復や代謝で大事な役目をはたしているよ。"],"010c23d1":["097bff270e2f.mp3","ホルモンは血液にのって運ばれるから、ふつう神経の信号よりゆっくりはたらくの。でもその効き目は長く続くことが多くて、体の働きを持続して調節しているよ。"],"51957281":["d402cdb59420.mp3","糖尿病は、インスリンが足りなかったり、体がインスリンにうまく反応しなかったりして、血液のブドウ糖をうまく調節できなくなる病気だよ。"],"8421d862":["11c22d3610b7.mp3","卵巣と精巣には二つの役目があるの。生殖細胞を作ることと、性ホルモンを作ること。卵巣はエストロゲンとプロゲステロン、精巣はテストステロンを作るよ。"],"83dd0012":["c51d52be1d76.mp3","メラトニンは、脳の中の小さな松果体で作られるの。明るさと暗さに合わせて出されて、眠りと目覚めのリズムを調節するのを助けているよ。"],"eacd1d90":["9e3b15bdf640.mp3","コルチゾールは副腎で作られて、体のストレス反応で大事な役目をしているの。代謝や免疫の働きの調節もしているよ。"],"00c8deac":["7a044ee9ecef.mp3","内分泌の多くのしくみはフィードバックの輪、特に負のフィードバックにたよっているの。ホルモンやその効果が増えてくると、体がそれ以上作るのを減らすように合図して、体の中のバランスを安定させるよ。"],"3a5e5579":["f9afac0dac55.mp3","副甲状腺は副甲状腺ホルモンを作って、血液のカルシウムの量を調節するのを助けているの。骨の健康、筋肉の働き、神経の信号にとって大事だよ。"],"7b28a414":["1f1a81263bea.mp3","思春期は、脳から始まるホルモンの連鎖で起きるの。脳が下垂体に合図して、卵巣や精巣がもっと性ホルモンを作るようにうながすんだよ。"],"89332382":["12deb731f85f.mp3","内分泌の病気は、ホルモンを作ること、調節すること、または体のホルモンへの反応に問題があるもの。甲状腺のはたらきすぎやはたらかなさ、糖尿病などがあるよ。"],"911f0ae7":["82f92ff6fe0b.mp3","免疫系とリンパ系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"f5714d5e":["9862d67587c3.mp3","免疫系は、病原体、異常な細胞、そのほかの脅威を見つけて戦って、感染や病気から体を守っているよ。"],"eb15736a":["25ca80cb380f.mp3","免疫の守りで中心的な役目をする白血球のほとんどは、骨の中のやわらかい組織、骨髄で作られているよ。"],"56e5293d":["757b62beb12e.mp3","リンパ節は、体をめぐるリンパ液をろ過して、病原体をつかまえて、感染を見つけて戦う免疫細胞のすみかになっているの。"],"040c09f9":["ab967ced5600.mp3","抗体は免疫細胞が作るたんぱく質で、特定の病原体や異物を見分けてくっつくの。それを無力にしたり、ほかの免疫細胞がこわすための目印をつけたりするよ。"],"e1c9287d":["4fe07203bcbb.mp3","ワクチンは、病原体を弱くしたもの、不活化したもの、またはその一部を免疫系に見せて、練習させるの。本物の病原体が来たときに、すばやく強く反応できるようになるよ。"],"43ec974d":["beb0806031ac.mp3","自然免疫は、生まれたときから持っている、体の一般的で特定しない最初の守り。皮膚みたいな物理的なバリアや、いろんな脅威に広く反応する免疫細胞があるよ。"],"eb9f2681":["b9b217aeb370.mp3","獲得免疫は、病原体に出会ったあとで、その病原体だけに合わせたとても特定の反応を作るの。そして大事なのは免疫の記憶を作ること。同じ病原体にまた出会ったら、もっと速く強く反応できるよ。"],"828dbc72":["e6bc83f24391.mp3","炎症は、体を守るための免疫の反応で、赤くなる、熱を持つ、はれる、痛む、が特徴なの。けがや感染した場所に、血流と免疫細胞が集まってくるからだよ。"],"68048d12":["9915f381e302.mp3","リンパ管は、免疫細胞をふくむ透明な液体、リンパを運ぶの。体の組織から余分な水分を回収して、ろ過のためにリンパ節を通して運ぶのを助けているよ。"],"e1debf71":["271539323a61.mp3","脾臓は血液をろ過して、古くなったり傷ついたりした赤血球を取りのぞいて、感染に反応するのを助ける免疫細胞のすみかにもなっているよ。"],"71943bb6":["d33bc4b11a9f.mp3","アレルギー反応は、花粉、ペットのふけ、ある食べ物みたいな、ふだんは害のないものを、免疫系がまちがえて敵だと思って、大げさに反応してしまうことだよ。"],"e3198613":["0076a7b58332.mp3","自己免疫の病気では、免疫系が体の健康な細胞や組織をまちがえて異物だと思って、攻撃してしまうの。病気によって、いろんな器官やしくみに影響が出るよ。"],"26066573":["049d5f8aefce.mp3","胸の上のほうにある胸腺は、T細胞っていう白血球が育って一人前になる場所。そのあと全身をめぐって、免疫の反応をまとめるのを助けるの。"],"26fbbb6c":["dee09fb1284b.mp3","適度な熱は、ある病原体にとって住みにくい環境を作って、一部の免疫細胞の働きを強めて、感染と戦うのを助けると考えられているの。でも、熱が高すぎると、それ自体が危険になることもあるよ。"],"2bcba845":["c51294d8fdea.mp3","傷のない皮膚は、化学的な守りや微生物の守りと一緒に、多くの病原体がそもそも体に入らないようにする、とても大事な物理的なバリア。免疫の大事な最初の守りだよ。"],"cc8259bb":["cbee372a567e.mp3","皮膚、髪、爪。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"3338bf29":["a75fbe280b5b.mp3","皮膚は、ふつう面積でも重さでも体で一番大きな器官と考えられていて、体を守ったり調節したりする大事な役目をたくさん持っているよ。"],"7cd43807":["6d4b9614abb5.mp3","表皮は皮膚の一番外側の層。体を守るバリアになっていて、色素のメラニンを作る細胞もあるよ。"],"4d194a37":["e1fda6fc1d54.mp3","真皮は表皮の下にあって、血管、神経の終わり、毛包、汗腺などがあるの。"],"1a7cef33":["fdc6a9710512.mp3","皮下組織は真皮の下にあって、主に脂肪と結合組織でできているの。体温を逃がさず、クッションにもなるよ。"],"70913fee":["7b13770ab1d4.mp3","メラニンは表皮の特別な細胞が作る色素で、皮膚、髪、目に色をつけて、紫外線のダメージから少し守ってくれるよ。"],"5a4fc947":["82915c649336.mp3","汗腺は汗を作って、汗が皮膚の表面から蒸発することで体を冷やすの。体温を調節する大事なしくみだよ。"],"b477c3b3":["44dbea280425.mp3","毛包は皮膚の中にある管みたいなつくりで、一本一本の毛がここから生えるの。毛は、のびる時期、休む時期、ぬける時期をくり返しているよ。"],"96198e9e":["d16128a052af.mp3","爪は主にケラチンでできていて、敏感な指先やつま先を守りながら、細かい作業を助けて、さわる感覚も高めているよ。"],"ab836d97":["a3127d403117.mp3","皮脂腺は、皮脂っていう油っぽいものを出して、皮膚と髪をなめらかにして水をはじくのを助けるの。少し細菌をおさえる働きもあるよ。"],"d55dc737":["9c5c1f51eb46.mp3","太陽の紫外線を浴びると、皮膚のある細胞がビタミン D を作れるの。ビタミン D は骨の健康や、ほかの体の働きに大事だよ。"],"530245f1":["231307d52960.mp3","ケラチンはじょうぶな繊維のたんぱく質で、皮膚の外側の層、髪、爪の大事な材料。強さと守りを与えているよ。"],"01d0fa25":["753b3c784dd4.mp3","皮膚にはいろんな種類の感覚の神経の終わりがあって、さわる、押す、温度、痛みを感じて、外の環境について大事な情報をくれるの。"],"fa1495b8":["2e9e356af6ba.mp3","たこは、皮膚が同じところで何度もこすれたり押されたりすると、体を守るために厚くなってできるの。負担にたえやすくなるんだよ。"],"240d4561":["5d21e770456d.mp3","爪は皮膚の下の爪母から、ゆっくり休まずにのびていくの。ふつう手の爪のほうが足の爪より少し速くのびて、のびる速さは年齢や健康などで変わるよ。"],"464ef0e7":["1a3a22a7631a.mp3","皮膚の血管は、体が暑いときは広がって表面の血流を増やして熱を逃がし、寒いときは縮んで熱が逃げるのを減らして、体温の調節を助けているよ。"],"a7add780":["71b9256e7327.mp3","生殖器系。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"b94ff178":["828f49ce8460.mp3","生殖器系の一番の生物学的な役目は、子どもを作れるようにすること。精子や卵子みたいな生殖細胞を作って、女性では妊娠と赤ちゃんの成長を支えるの。"],"45f9c563":["4c0c68908544.mp3","卵巣は女性の生殖器で、卵子を作って、エストロゲンとプロゲステロンっていうホルモンも作っているよ。"],"30422772":["a0d61f9e29e6.mp3","精巣は男性の主な生殖器で、精子を作って、テストステロンっていうホルモンも作っているよ。"],"8f6b1205":["ac46ddf9819e.mp3","子宮は筋肉の器官で、妊娠の間ずっと赤ちゃんを支えて育てるの。妊娠しなかったときは、月経で内側の膜がはがれ落ちるよ。"],"7b4a4285":["8f3899581a59.mp3","月経周期は、エストロゲンやプロゲステロンをふくむホルモンの、そろった流れで調節されていて、周期ごとに妊娠にそなえて体を準備しているの。"],"833b3e08":["15ef130e0611.mp3","受精、つまり精子と卵子が一つになるのは、ふつう卵管の中。そのあと、できた胚が子宮へ移動していくよ。"],"e8bd99d7":["6d6a9c56b388.mp3","思春期は、生殖器系が成熟して子どもを作れるようになる成長の時期。体全体の変化やホルモンの変化も一緒に起きるよ。"],"d51ff106":["e377bae04ce5.mp3","胎盤は妊娠中にできる一時的な器官で、お母さんの血液と赤ちゃんの間で、栄養、酸素、老廃物を交換できるようにしているよ。"],"22a6058d":["dfce209a8115.mp3","テストステロンとエストロゲンは、生殖の発達、二次性徴、生殖の働きで中心的な役目をする性ホルモン。どちらも、程度は違っても、すべての人の体にあるの。"],"ac88ffb7":["02e39e77ea58.mp3","ふつうの妊娠は、最後の月経が始まった日から出産まで、およそ40週、だいたい9か月。少し前後することもあるよ。"],"20860335":["18435e9088f2.mp3","妊娠期間、ゲステーションは、受精から出産まで、胚や胎児が子宮の中で育つ期間のことだよ。"],"95d70ed3":["f5cff0ac9c94.mp3","二次性徴は、声の変化や体毛の生え方みたいな体の特徴で、思春期に性ホルモンの影響でできてくるの。でも、それ自体は子どもを作ることに直接関わっていないよ。"],"75070f41":["d78bdacaab15.mp3","脳の視床下部と下垂体がホルモンを出して、生殖器の働きを調節しているの。月経周期や精子を作ることみたいなしくみをまとめているよ。"],"58d612c6":["db2bdc045c44.mp3","避妊には、ホルモンを使うもの、バリアを使うもの、そのほかいろんな方法があって、妊娠を防ぐために使われるよ。"],"08766acd":["11198cd71319.mp3","リプロダクティブヘルスは広い考え方で、妊娠や出産のときだけじゃなく、一生を通しての、生殖器に関わる体、ホルモン、全体の健康をふくむの。"],"2d4651db":["7a611a2b34bc.mp3","人の感覚と知覚。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"42e6b398":["0d97044ad04f.mp3","昔から言われている五感は、見る、聞く、におう、味わう、さわる。でも今の科学では、バランスや固有感覚みたいな、ほかの感覚もあると考えられているよ。"],"1823983b":["db21f7d74514.mp3","目に入った光は最後に網膜に集められるの。網膜は目のうしろにある光を感じる細胞の層で、光を信号に変えて脳に送るよ。"],"b4432475":["53a313106d7b.mp3","網膜には、光にとても敏感で暗いところで見るのに大事な桿体と、色を感じて明るいところでよくはたらく錐体があるよ。"],"cd6d11b9":["52d7267644fa.mp3","音の波は耳の穴を通って鼓膜をふるわせて、小さな骨を通って内耳の蝸牛に伝わるの。そこで振動が神経の信号に変わるよ。"],"e2448209":["8432682abcff.mp3","におい、嗅覚は、鼻の奥の高いところにある特別な受容細胞が、空気中の化学物質の分子を感じとって、脳に信号を送ることで分かるの。"],"f7f19ce3":["24a026a88870.mp3","味蕾は主に舌にあって、食べ物や飲み物の化学物質を感じとるの。味はふつう、甘い、しょっぱい、すっぱい、苦い、そしてうま味に分けられるよ。うま味は、日本で見つかった味なんだ！"],"e2e28b2c":["15d3b70a94e7.mp3","においと味はしっかりつながっているの。風味だと思っているものの多くは、舌からの味の信号と、食べているときに鼻の奥に届く香りのにおいの信号が合わさったものなんだよ。"],"1820c676":["b45e383831fe.mp3","さわる感覚は、皮膚にあるいろんな特別な受容器で、押す、手ざわり、振動、温度、痛みなどを感じとっているよ。"],"8d470e57":["c05b0596d300.mp3","固有感覚は、自分の体の位置、動き、力の入れ具合を感じる感覚。見なくても手足がどこにあるか分かるのはこのおかげで、なめらかに動くのに大事だよ。"],"f6140451":["b6c31af230b4.mp3","前庭系は内耳にあるつくりで、頭の動きと位置を感じとって、バランスと空間の向きの感覚に大きく役立っているよ。"],"b93a6728":["b99a5f9e92b7.mp3","瞳孔は大きさが変わる穴で、虹彩がコントロールして、目に入る光の量を調節するの。明るいと小さく、暗いと大きくなるよ。"],"1bf2ad05":["b5b73a59eddf.mp3","色覚の違いのほとんどは、網膜の一種類以上の錐体細胞の働きの違いから来ていて、ある色の見分けに影響するの。一番多いのは、赤と緑だよ。"],"5b70955e":["5eec363e1834.mp3","痛みはいやなものだけど、実際の、またはこれから起きそうな体の傷を知らせて、さらにけがをしないように反応させてくれる、大事な守りの役目があるの。"],"9ce0c415":["d7d8e421ae82.mp3","感覚の順応は、変わらずに続く刺激に、神経系の反応がだんだん小さくなること。ずっとしているにおいに、しばらくすると気づかなくなるのはそのためだよ。"],"16e9c6c0":["7dd00137eff2.mp3","感覚は、受容器が刺激をそのまま感じとること。知覚は、そのあとで脳がその情報を解釈して整理して、意味のある体験にすることだよ。"],"fa919c7a":["a209444fc978.mp3","細胞、組織、器官のしくみ。大事なポイントを説明するね。先に進みたいときは、いつでも Next をタップしてね。"],"c0c4ac48":["2a9a07468a42.mp3","細胞は、生命のつくりと働きの基本の単位。すべての生き物は、一つ以上の細胞でできているよ。"],"4dd032c3":["c7f061bb17be.mp3","核には細胞の遺伝情報の DNA が入っていて、司令塔として、成長や増えることをふくむ細胞のたくさんの活動を指示しているの。"],"8f24a1f8":["4be6632a60ac.mp3","ミトコンドリアは、よく細胞の発電所って呼ばれるの。細胞呼吸で、ATP っていう分子の形で、細胞が使うエネルギーのほとんどを作っているからだよ。"],"ad952fd2":["3bf742126454.mp3","細胞膜は細胞のまわりで選んで通すバリアになっていて、栄養、老廃物、信号の分子みたいなものの、出入りを調節しているよ。"],"1e99a996":["087fb50c9d30.mp3","組織は、似た細胞とそのまわりの物質の集まりで、一緒にある決まった働きをするの。筋肉の組織や神経の組織みたいにね。"],"82b9e786":["6b2aef5c0e5c.mp3","人の体の組織は、ふつう基本の四種類に分けられるの。表面をおおう上皮組織、支えてつなぐ結合組織、動きを生む筋組織、そして信号を伝える神経組織だよ。"],"91a29767":["c1bf5e2bbafe.mp3","器官は、心臓や胃みたいに、二種類以上の違う組織が一緒になって、決まった複雑な働きをするものだよ。"],"d7785e80":["6e5a3fe127f7.mp3","器官系は、いくつもの器官がもっと大きな共通の目的に向かって一緒にはたらくもの。消化器系の器官が、みんなで食べ物を処理するみたいにね。"],"6a1bc3fe":["191b922cb582.mp3","DNA は、その並び方で書かれた遺伝の指示をたくわえていて、生き物の細胞の成長、働き、増え方を導いているよ。"],"7eb36a99":["c94ed1c7e01f.mp3","細胞分裂のおかげで、生き物は成長して、傷ついた組織を直して、生殖細胞の場合は子孫を残すことにもつながるの。"],"c3398f95":["c6cf00463b32.mp3","幹細胞は、まだあまり専門化していない細胞で、いろんな専門の細胞に育つ、分化する力を持っているの。成長、発達、組織の修復で大事な役目をしているよ。"],"4f617986":["0d2433363425.mp3","恒常性、ホメオスタシスは、外の環境が変わっても、体温、pH、水分のバランスみたいな体の中の環境を、だいたい安定させておくための体のいろんな調節のしくみのことだよ。"],"4d4bd584":["693661ea1fbb.mp3","細胞呼吸は主にミトコンドリアで起きて、酸素とブドウ糖などの燃料の分子を使って、使えるエネルギーを作るの。そのとき、二酸化炭素と水が出るよ。"],"ce74cba7":["5631e7905873.mp3","遺伝子は、指示をのせた DNA の決まった部分で、多くは特定のたんぱく質の作り方なの。親から子へ受けつがれる、いろんな特徴に影響しているよ。"],"32076dfc":["10e1e26d7123.mp3","生き物のつくりは、ふつう基本の単位の細胞から始まるの。細胞が集まって組織、組織が集まって器官、器官が一緒にはたらいて器官系。段階ごとに、複雑さとまとまりが増していくよ。"]};
